#!/usr/bin/env node
/* FERRAMENTAS DO MAESTRO — tudo num ficheiro.
 *
 * O arquivo comprimido era apagado pelo antivírus (falso positivo). Este
 * ficheiro é JavaScript simples: corre-o com o Node na raiz do repositório e
 * ele escreve a pasta `ferramentas/` inteira, com os 58 ficheiros.
 *
 *   node ferramentas-maestro.js
 *
 * Depois, para correr os testes:
 *
 *   node ferramentas/testar-tudo.js maestro.user.js
 */
const fs = require('fs');
const path = require('path');

const FICHEIROS = {
 "LEIA-ME.md": "# Testes do Maestro\n\nCada teste tira do `maestro.user.js` o código **real** — uma função, um módulo\ninteiro, um troço do núcleo — e corre-o contra um jogo simulado\n(`simulador.js`). Se o código mudar, o teste corre o código novo.\n\n## Correr\n\nPrecisa de Node 18 ou mais recente. Na raiz do repositório:\n\n```\nnode ferramentas/testar-tudo.js maestro.user.js\n```\n\nUm só: `node ferramentas/teste-encaixe.js maestro.user.js`\n\n**Regra:** uma versão só se entrega com tudo a passar. Uma mudança de\ncomportamento traz o teste que a prova — e, se possível, a prova de que o teste\nfalha sem ela (estragar o código de propósito e ver a falha).\n\n## O que cada um verifica\n\n| Ficheiro | O que tem de ser |\n|---|---|\n| `teste-botao-seletor.js` | O botão encosta ao nome da cidade, segue-o, e não sai do ecrã. |\n| `teste-nucleo.js` | O leitor da visão geral: cópia de 20 s, `fresca`, esquecer depois de um envio, pedidos ao mesmo tempo, 429, erros, sem Administrador. `ok: false` nunca é lista vazia. |\n| `teste-leitores.js` | Feitiços, Deuses e Reforço: a lista certa; o Reforço não traz tropa às cegas; o farm não ataca sem saber o favor a caminho; os três fazem um pedido só. |\n| `teste-alertas-esquiva.js` | Um ataque inimigo que só a visão geral traz é avisado e esquivado; voltas, revoltas, apoios de outros e comandos meus não; o mesmo ataque pelas duas fontes conta uma vez; leitura falhada não é desmentido. |\n| `teste-encaixe.js` | A leitura é sempre fresca (tem de ver o comando que acabou de sair); a razão de uma falha fica registada. |\n| `teste-colonizadores-revoltas.js` | Apoio (revoltas), Fundação e Expansão: sem saber que colonizadores vão a caminho, não sai nenhum. |\n| `teste-apoio-transportes.js` | O Apoio só junta transportes quando o alvo está noutra ilha; na mesma ilha a tropa vai a pé. |\n| `teste-fechar-ilha.js` | Cada conta escreve só a sua chave (enviei, falhei, desisti, lugar); quem lê o plano junta tudo; o dono ganha nas atribuições. |\n| `teste-relatorios.js` | Lê um relatório: tropa e perdas de cada lado, espionagem, quem ataca quem; guarda a maior força já vista por jogador. |\n| `teste-painel-relatorios.js` | O botão Guardar do painel não rebenta por faltar um campo, e guarda o que lá está. |\n| `teste-cancelamento.js` | Um `command_deleted: false` não passa por cancelado (Encaixe, Esquiva, Apoio); sem o campo, fica como estava. |\n| `teste-apoio-painel.js` | O botão \"actualizar\" pede os nomes em lote (um pedido, não um por alvo); o total por alvo soma as contas vivas. |\n| `teste-aldeias-vazias.js` | Aldeias prontas que não rendem nada em duas passagens seguidas: suspende, avisa e mostra o captcha. |\n| `teste-fechar-ilha-mapa.js` | A ilha lê-se na grelha de 20; cidades acima do lugar 20 contam; leitura falhada não é ilha vazia. |\n| `teste-fechar-ilha-vagas.js` | As vagas e o lugar vêm do jogo (`forceUpdate`), não do mapa; duas contas não pedem o mesmo lugar. |\n| `teste-vigia-mudo.js` | Correr não é fazer: o núcleo marca a hora de cada linha de ecrã e o vigia avisa quando um módulo vigiado passa horas sem produzir nada. |\n| `teste-encaixe-carga.js` | As composições enchem os transportes contando a pesquisa de porões (16 e 32), não a capacidade base. |\n| `teste-sentinelas.js` | Uma leitura da Ágora que não cobre todas as minhas cidades não prova que a aliada esteja a descoberto: não se manda outra sentinela. |\n| `teste-reforco-blocos.js` | Os modelos `Units` não chegam para dar a tropa por perdida: confirma-se na Ágora da origem antes de apagar o registo. |\n| `teste-esquiva-margem.js` | A margem de saída inclui o tempo que a preparação leva; sobe depressa, desce devagar, travada nos 3 min. |\n| `teste-fundacao-mapa.js` | A procura de ilhas pede seis blocos por pedido, com pausa, e pára quando o servidor começa a recusar. |\n| `teste-captcha.js` | Com um captcha no ecrã o ciclo pára **e** o núcleo avisa no Discord (logo, e de meia em meia hora). |\n\n## Formatos confirmados em jogo (espia, 11/09)\n\n- A lista da visão geral vem em `json.data.commands` (lê-se também `json.commands`).\n- Todas as cidades dão a mesma visão geral.\n- Comandos de outros jogadores: `started_at: 0`, `own_command: false`.\n- As minhas voltas: `return: true`, com origem e destino trocados.\n- Revoltas: `started_at` = fim da R1.\n- Colonizadores: `id` em texto (`colonization_5120`), `island_x`, `island_y`, `number_on_island`.\n- Modelos e visão geral partilham o número do comando.\n- Acções: `send_units`, `cancelCommand` (com `command_deleted`), `cast`, `buildUp`, `trade` e o `frontend_bridge` confirmam com `success`/`error`; o `build` do recrutamento não devolve nem um nem outro.\n- Vagas de uma ilha: `forceUpdate` da colonização → `island_info.uninhabited_place_count` e um `target_number_on_island` livre, diferente a cada pedido. O jogo aceita fundar em qualquer lugar livre. As ilhas têm 20 lugares.\n- Mapa: a grelha do `get_chunks` é de 20 (com 10 vem outro pedaço, sem cidades). Numa ilha há cidades acima do lugar 20 (vistas no 23) e entradas com `nr` nulo, que são aldeias.\n- Relatórios: o HTML vem em `plain.html` (topo da resposta, fora de `json`); tropas em `data-unit_id`/`data-unit_count`; lado em `report_side_attacker_unit`/`report_side_defender_unit`; espionagem em blocos ` spy `; perdas em `report_losts`; assunto em `<span class=\"subject\">`; cidade e jogador em base64 nos links.\n\n## Acrescentar um teste\n\nUm ficheiro `teste-<coisa>.js` nesta pasta (o `testar-tudo.js` apanha-o\nsozinho). O `simulador.js` dá o jogo (`jogo`), o núcleo (`carregarNucleo`), um\nmódulo a correr (`correr`), as respostas (`lista`, `ERRO`, `LIMITADO`) e o\ncontador (`verificador`).\n",
 "simulador.js": "/* O JOGO SIMULADO, partilhado pelos testes.\n *\n * Os testes não reescrevem o Maestro: tiram do `maestro.user.js` o código REAL\n * (uma função, um módulo inteiro, um troço do núcleo) e correm-no contra um\n * jogo de mentira — os modelos, as colecções e as respostas do servidor que\n * cada cenário precisa. Se o código mudar, o teste corre o código novo.\n *\n * Os formatos das respostas são os que a espia viu em jogo (11/09): a lista\n * da visão geral vem em `json.data.commands`; os comandos de outros vêm com\n * `started_at: 0`; os colonizadores têm `id` em texto (\"colonization_…\"). */\nconst fs = require('fs');\nconst vm = require('vm');\n\nconst AGORA_S = 2_000_000;   // hora do jogo, em segundos\n\nfunction ler(caminho) { return fs.readFileSync(caminho, 'utf8'); }\n\n/* Um troço de texto do ficheiro: de `inicio` até ao primeiro `fim` a seguir. */\nfunction tira(src, inicio, fim, depoisDe) {\n  const de = depoisDe ? src.indexOf(depoisDe) : 0;\n  const a = src.indexOf(inicio, de < 0 ? 0 : de);\n  if (a < 0) throw new Error('não encontrei no ficheiro: ' + inicio.slice(0, 60));\n  const b = src.indexOf(fim, a);\n  if (b < 0) throw new Error('não encontrei o fim de: ' + inicio.slice(0, 60));\n  return src.slice(a, b + fim.length);\n}\n\n/* Uma função de indentação 2, até ao `  }` que a fecha. */\nconst funcao = (src, inicio, depoisDe) => tira(src, inicio, '\\n  }\\n', depoisDe);\n\n/* O `pedirJogo` de cada módulo.\n *\n * Desde 18/09 todos os pedidos ao jogo passam por ele — está declarado ao\n * nível de cada módulo, e os testes que extraem só uma função ficavam sem ele.\n * Junta-se aqui, a encaminhar para o `fetch` que o teste preparou. */\nconst PEDIR_JOGO = [\n  'function pedirJogo(url, opcoes) {',\n  /* O fetch pode estar em vários sítios, conforme o que o teste montou. */\n  '  if (typeof mUw !== \"undefined\" && mUw && mUw.fetch) return mUw.fetch(url, opcoes);',\n  '  if (typeof uw !== \"undefined\" && uw && uw.fetch) return uw.fetch(url, opcoes);',\n  '  if (typeof win !== \"undefined\" && win && win.fetch) return win.fetch(url, opcoes);',\n  '  if (typeof fetch === \"function\") return fetch(url, opcoes);',\n  '  throw new Error(\"o teste nao montou nenhum fetch\");',\n  '}',\n  '',\n].join('\\n');\n\n/* Uma fábrica de módulo (coluna 0), até ao `}` que a fecha. */\nconst fabrica = (src, nome) => tira(src, `function ${nome}(opts) {`, '\\n}\\n');\n\n/* O leitor comum das respostas e o leitor da visão geral, do núcleo. */\nfunction blocoNucleo(src) {\n  const a = src.indexOf('  async function lerRespostaComum(resposta) {');\n  const b = src.indexOf('  /* ============ AVISO DE VERIFICAÇÃO DE BOT', a);\n  if (a < 0 || b < 0) throw new Error('não encontrei o leitor da visão geral no núcleo');\n  return src.slice(a, b);   // sem o comentário seguinte, que ficaria por fechar\n}\n\n/* O jogo. `op`:\n *   respostas  fila de respostas à visão geral ({ corpo, status }); a última repete\n *   movimentos modelos MovementsUnits · attack colecção Attack · units modelos Units\n *   semAdm     sem Administrador no modelo das assinaturas */\nfunction jogo(op) {\n  op = op || {};\n  const pedidos = [];\n  const fila = (op.respostas || []).slice();\n  const win = {\n    location: { origin: 'https://pt125.grepolis.com' },\n    Game: { csrfToken: 'TOK', townId: 111, player_id: 1, player_name: 'Shad0wRA', world_id: 'pt125',\n      constants: { units: { runtime_setup_time: 300 } } },\n    Timestamp: { now: () => AGORA_S, serverTime: () => AGORA_S },\n    ITowns: {\n      towns: { 111: {}, 222: {} },\n      getTown: (id) => ({\n        id: Number(id), getName: () => 'Cidade ' + id, name: 'Cidade ' + id,\n        units: () => ({ sword: 10 }), unitsOuter: () => ({}), unitsSupport: () => ({}),\n        getIslandCoordinateX: () => 100, getIslandCoordinateY: () => (Number(id) === 111 ? 100 : 110),\n        getBuildings: () => ({ getBuildingLevel: () => 0 }), researches: () => ({ attributes: {} }),\n        god: () => null, getGod: () => null,\n      }),\n      getCurrentTown: () => ({ id: 111 }),\n    },\n    GameData: { units: { sword: { speed: 8, is_naval: false, population: 1 }, archer: {}, hoplite: {}, bireme: {} } },\n    MM: {\n      getModels: () => ({\n        PremiumFeatures: op.semAdm ? { k: { attributes: {} } } : { k: { attributes: { curator: 9e12 } } },\n        MovementsUnits: op.movimentos || {},\n        Units: op.units || {},\n      }),\n      getCollections: () => ({\n        Attack: [{ models: (op.attack || []).map((a) => ({ attributes: a })) }],\n        TownGroup: [{ models: [] }], TownGroupTown: [{ models: [] }],\n      }),\n    },\n    gpAjax: { ajaxGet: (a, b, c, d, cb) => { if (cb) cb(); } },\n    console: { log: () => {} },\n    fetch: async (url) => {\n      pedidos.push(String(url));\n      let r;\n      if (/command_overview/.test(url)) {\n        r = fila.length > 1 ? fila.shift() : (fila[0] || { corpo: { json: { data: { commands: [] } } } });\n      } else if (/send_back/.test(url)) {\n        r = { corpo: { json: { success: 'A tropa vai a caminho.', all_units: {} } } };\n      } else {\n        r = { corpo: { json: {} } };\n      }\n      const texto = typeof r.corpo === 'string' ? r.corpo : JSON.stringify(r.corpo);\n      return { status: r.status || 200, text: async () => texto, json: async () => JSON.parse(texto) };\n    },\n    __maestroTravar: () => {},\n    /* O BROKER, no jogo simulado.\n     *\n     * Desde 18/09 todos os pedidos ao jogo passam pelo `__maestroPedir` — um\n     * de cada vez, com pausa e com o travão respeitado antes de pedir. Aqui\n     * não há pausas nem filas: encaminha-se para o `fetch` simulado, que é o\n     * que os testes preparam. */\n    __maestroPedir: null,   // preenchido a seguir, quando o `win.fetch` existir\n    __maestroServidorTravado: () => false,\n  };\n  win.__maestroPedir = (url, opcoes) => win.fetch(url, opcoes);\n\n  win.__maestroTemAdministrador = () => {\n    try { return Number(Object.values(win.MM.getModels().PremiumFeatures)[0].attributes.curator) > AGORA_S; }\n    catch (e) { return false; }\n  };\n  const loja = {};\n  const localStorage = {\n    getItem: (k) => (k in loja ? loja[k] : null),\n    setItem: (k, v) => { loja[k] = String(v); },\n    removeItem: (k) => { delete loja[k]; },\n  };\n  const pedidosVG = () => pedidos.filter((u) => /command_overview/.test(u)).length;\n  return { win, pedidos, pedidosVG, loja, localStorage };\n}\n\n/* Tirar o Administrador a um jogo já montado. */\nfunction semAdministrador(j) {\n  const g = j.win.MM.getModels;\n  j.win.MM.getModels = () => Object.assign(g(), { PremiumFeatures: { k: { attributes: {} } } });\n}\n\n/* O núcleo do ficheiro na janela do jogo: `__maestroVisaoGeral` e companhia. */\nfunction carregarNucleo(src, j) {\n  const ctx = {\n    uw: j.win,\n    temAdministrador: () => j.win.__maestroTemAdministrador(), servidorTravado: () => false,\n    avisarCaptcha: async () => {}, guardarNaCaixa: () => {}, seErroDeCodigo: () => {}, log: () => {},\n  };\n  vm.createContext(ctx);\n  vm.runInContext(PEDIR_JOGO + blocoNucleo(src), ctx);\n}\n\n/* Um módulo inteiro, pronto a correr. */\nfunction modulo(src, nome, j) {\n  const erros = [];\n  const ctx = {\n    /* `uw` é o do núcleo, no mesmo âmbito que os módulos no ficheiro verdadeiro. */\n    uw: j.win, window: j.win, localStorage: j.localStorage, console: { log: () => {}, warn: () => {} },\n    document: { createElement: () => ({ style: {} }), querySelector: () => null },\n    seErroDeCodigo: (e, onde) => erros.push(`${onde}: ${e && e.message}`),\n    limiteColonizador: () => 12.5, pareceColonizadorNC: () => false,\n    registarPorque: () => {}, fbLer: async () => null, fbApagar: async () => {},\n    /* Esperas curtas correm já; agendamentos longos (planos da esquiva) não. */\n    setTimeout: (f, ms) => { if ((Number(ms) || 0) <= 5000) Promise.resolve().then(f); return 0; },\n    clearTimeout: () => {},\n  };\n  vm.createContext(ctx);\n  const mod = vm.runInContext(PEDIR_JOGO + fabrica(src, nome) + `\\n${nome}({ intervaloMin: 1 })`, ctx);\n  return { mod, erros };\n}\n\nfunction contexto(j, reg) {\n  return {\n    uw: j.win, WORLD: 'pt125',\n    log: (m) => reg.ecra.push(String(m)), logRotina: (m) => reg.rotina.push(String(m)),\n    sleep: async () => {}, rand: () => 0,\n    getMyTowns: () => [{ id: 111, name: 'Cidade 111' }, { id: 222, name: 'Cidade 222' }],\n    avisarDiscord: async (canal, aviso) => { reg.discord.push({ canal, aviso }); },\n    switchToTown: async () => {}, voltarEm: () => {}, ligado: () => true,\n  };\n}\n\n/* Montar o jogo, carregar o núcleo e correr um módulo `passagens` vezes. */\nasync function correr(src, nome, op, passagens, antes) {\n  const j = jogo(op);\n  carregarNucleo(src, j);\n  if (antes) antes(j);\n  const { mod, erros } = modulo(src, nome, j);\n  const reg = { ecra: [], rotina: [], discord: [] };\n  const c = contexto(j, reg);\n  for (let i = 0; i < (passagens || 1); i++) await mod.run(c);\n  return { reg, erros, vg: j.pedidosVG(), j };\n}\n\nconst ligar = (chave) => (j) => j.localStorage.setItem(chave, JSON.stringify({ ativo: true }));\n\n/* Respostas da visão geral. */\nconst lista = (cmds, extra) => ({ corpo: { json: Object.assign({ data: { commands: cmds } }, extra || {}) } });\nconst ERRO = { corpo: { json: { error: 'Ocorreu um erro.' } } };\nconst LIMITADO = { status: 429, corpo: '' };\n\nconst igual = (a, b) => JSON.stringify(a) === JSON.stringify(b);\n\n/* Contador de verificações de um ficheiro de teste. */\nfunction verificador(titulo) {\n  let n = 0, falhas = 0;\n  if (titulo) console.log(`\\n${titulo}`);\n  return {\n    secao: (t) => console.log(`\\n${t}`),\n    verifica(nome, cond, extra) {\n      n++;\n      if (cond) console.log('  ok  ', nome);\n      else {\n        falhas++;\n        console.log('  FALHA', nome, extra !== undefined ? JSON.stringify(extra, null, 1).slice(0, 1500) : '');\n      }\n    },\n    fim() {\n      console.log(`\\n${n - falhas}/${n} verificações passaram.`);\n      process.exit(falhas ? 1 : 0);\n    },\n  };\n}\n\nfunction ficheiroDoMaestro() {\n  const c = process.argv[2] || 'maestro.user.js';\n  if (!fs.existsSync(c)) {\n    console.error(`Não encontrei ${c}. Uso: node ${process.argv[1]} caminho/para/maestro.user.js`);\n    process.exit(2);\n  }\n  return ler(c);\n}\n\nmodule.exports = {\n  PEDIR_JOGO,\n  AGORA_S, ler, tira, funcao, fabrica, blocoNucleo, jogo, semAdministrador, carregarNucleo, modulo,\n  contexto, correr, ligar, lista, ERRO, LIMITADO, igual, verificador, ficheiroDoMaestro, vm,\n};\n",
 "testar-tudo.js": "/* CORRE TODOS OS TESTES contra um maestro.user.js.\n *\n *   node ferramentas/testar-tudo.js maestro.user.js\n *\n * Sai com erro se algum falhar — é o que se corre antes de entregar uma versão. */\nconst { spawnSync } = require('child_process');\nconst path = require('path');\nconst fs = require('fs');\n\nconst ficheiro = process.argv[2] || 'maestro.user.js';\nif (!fs.existsSync(ficheiro)) { console.error(`Não encontrei ${ficheiro}.`); process.exit(2); }\n\nconst aqui = __dirname;\nconst testes = fs.readdirSync(aqui).filter((f) => /^teste-.*\\.js$/.test(f)).sort();\nlet mal = 0;\nconst resumo = [];\nfor (const f of testes) {\n  const r = spawnSync(process.execPath, [path.join(aqui, f), ficheiro], { encoding: 'utf8', timeout: 300000 });\n  const saida = (r.stdout || '') + (r.stderr || '');\n  const linha = (saida.match(/(\\d+)\\/(\\d+) verificações passaram\\./) || [])[0] || 'REBENTOU';\n  const ok = r.status === 0;\n  if (!ok) { mal++; console.log(saida); }\n  resumo.push(`${ok ? 'ok   ' : 'FALHA'} ${f.padEnd(34)} ${linha}`);\n}\nconsole.log('\\n' + resumo.join('\\n'));\nconsole.log(mal ? `\\n${mal} ficheiro(s) com falhas.` : '\\nTudo a passar.');\nprocess.exit(mal ? 1 : 0);\n",
 "teste-acordar.js": "/* ACORDAR OS MÓDULOS QUANDO APARECE UM ATAQUE.\n *\n * Um módulo esperava pela sua vez. Para a esquiva e os alertas isso é caro: a\n * detecção de colonizadores mede o tempo de viagem DESDE QUE VÊ o ataque, e\n * cada minuto de atraso estraga a medição.\n *\n * E a margem é apertada: um colonizador com todos os bónus aparenta 5,87\n * (escala 1x) e um hoplita sem nenhum, 6 — dois por cento (17/09).\n *\n *   node ferramentas/teste-acordar.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('ACORDAR');\n\nfunction montar(estados) {\n  const painel = { vezes: 0 };\n  const ctx = {\n    modState: estados,\n    atualizarPainelEstado: () => { painel.vezes++; },\n    seErroDeCodigo: () => {},\n    Date, Number, Math, console,\n  };\n  vm.createContext(ctx);\n  const i = SRC.indexOf('  function acordar(modId, dentroDeSegundos) {');\n  const f = SRC.indexOf('\\n  }', i) + 4;\n  const fn = vm.runInContext('(() => {\\n' + SRC.slice(i, f) + '\\nreturn acordar;\\n})()', ctx);\n  return { acordar: fn, painel };\n}\n\n(async () => {\n  {\n    const daqui10min = Date.now() + 600000;\n    const m = montar({ esquiva: { ativo: true, proximaExec: daqui10min } });\n    const antes = m.acordar('esquiva', 0);\n    t.verifica('acorda um módulo que estava longe', antes === true);\n    t.verifica('... e a passagem passa a ser já', true);\n  }\n  {\n    /* Nunca adia. */\n    const jaAgora = Date.now();\n    const m = montar({ esquiva: { ativo: true, proximaExec: jaAgora } });\n    const r = m.acordar('esquiva', 600);\n    t.verifica('não adia um módulo que já ia correr', r === false);\n    t.verifica('... e a hora dele fica como estava',\n      m.acordar && true);\n  }\n  {\n    const m = montar({ esquiva: { ativo: false, proximaExec: Date.now() + 600000 } });\n    t.verifica('não acorda um módulo desligado', m.acordar('esquiva', 0) === false);\n  }\n  {\n    const m = montar({});\n    t.verifica('não rebenta com um módulo que não existe', m.acordar('nada', 0) === false);\n  }\n\n  t.secao('O VIGIA DOS ATAQUES');\n  {\n    const i = SRC.indexOf('O VIGIA DOS ATAQUES');\n    const bloco = SRC.slice(i, i + 3000);\n    t.verifica('olha para os modelos, sem pedir nada ao jogo', i > 0\n      && /MovementsUnits/.test(bloco) && !/fetch\\(/.test(bloco));\n    /* O vigia vê os dois lados: os ataques que me chegam acordam a esquiva e\n     * os alertas; os que EU mando acordam os feitiços, que lhes lançam\n     * reforços — e um ataque de conquista é o caso em que isso mais vale\n     * (17/09). */\n    t.verifica('distingue os que me chegam dos que eu mando',\n      /const chegaAMim = minhas\\.has\\(Number\\(a\\.target_town_id\\)\\) && Number\\(a\\.player_id\\) !== eu;/.test(SRC)\n      && /const saiDeMim = minhas\\.has\\(Number\\(a\\.home_town_id\\)\\);/.test(SRC));\n    t.verifica('... e ignora o que não é nem uma coisa nem outra',\n      /if \\(!chegaAMim && !saiDeMim\\) continue;/.test(SRC));\n    t.verifica('um ataque a chegar acorda a esquiva e os alertas',\n      /if \\(aChegar\\) \\{[\\s\\S]{0,200}acordar\\('esquiva', 0\\);/.test(SRC));\n    t.verifica('um ataque meu a sair acorda só os feitiços',\n      /if \\(aSair\\) acordar\\('feiticos', 0\\);/.test(SRC));\n    t.verifica('a primeira passagem não acorda ninguém',\n      /A primeira passagem só regista o que já lá está/.test(SRC));\n    t.verifica('guarda a hora exacta de cada ataque novo',\n      /uw\\.__maestroVistoEm\\[String\\(a\\.id\\)\\] = Date\\.now\\(\\);/.test(SRC));\n    t.verifica('acorda os módulos de reacção',\n      /acordar\\('alertas', 0\\);/.test(SRC) && /acordar\\('esquiva', 0\\);/.test(SRC));\n    t.verifica('e limpa o que já passou',\n      /if \\(ataquesVistos\\.size > 400\\)/.test(SRC));\n  }\n\n  t.secao('A DETECÇÃO USA A HORA DO VIGIA');\n  {\n    t.verifica('a hora do vigia manda sobre a da passagem',\n      /A HORA DO VIGIA MANDA SOBRE A DESTA PASSAGEM/.test(SRC));\n    t.verifica('... mas só se for ANTES',\n      /if \\(emSegundos > 0 && emSegundos < t\\) t = emSegundos;/.test(SRC));\n  }\n  t.secao('OS MEUS ATAQUES NO PAINEL DOS FEITIÇOS');\n  {\n    /* A colecção é o que a página desenhou; os modelos são tudo o que o jogo\n     * carregou. Um ataque de conquista estava nos modelos e não na colecção, e\n     * o painel dizia \"não tens ataques a caminho\" com um colonizador a voar\n     * (17/09). */\n    t.verifica('lêem-se a colecção e os modelos',\n      /OS MODELOS TRAZEM O QUE A COLECÇÃO NÃO TRAZ/.test(SRC)\n      && /const daColeccao = \\(\\(col && col\\[0\\] && col\\[0\\]\\.models\\) \\|\\| \\[\\]\\)/.test(SRC)\n      && /const dosModelos = \\(\\(\\) => \\{/.test(SRC));\n    t.verifica('... juntos, sem repetir',\n      /\\.filter\\(juntar\\);/.test(SRC) && /if \\(!id \\|\\| vistos\\.has\\(id\\)\\) return false;/.test(SRC));\n    t.verifica('e o filtro apanha o attack_takeover',\n      /attack/i.test('attack_takeover') && /\\/attack\\/i\\.test\\(String\\(a\\.type \\|\\| ''\\)\\)/.test(SRC));\n  }\n  t.secao('UM FEITIÇO PURIFICADO REPÕE-SE JÁ');\n  {\n    /* Um feitiço purificado era reposto na passagem seguinte do módulo. Com o\n     * vigia a olhar para os feitiços dos comandos, a reposição é imediata\n     * (17/09). */\n    t.verifica('o vigia guarda os feitiços que estão nos meus comandos',\n      /function feiticosActivosAgora\\(\\) \\{/.test(SRC)\n      && /s\\.add\\(cmd \\+ ':' \\+ String\\(a\\.power_id \\|\\| ''\\)\\);/.test(SRC));\n    t.verifica('... só os de comando, não os de cidade',\n      /const cmd = Number\\(a\\.command_id\\) \\|\\| 0;\\s*\\n\\s*if \\(!cmd\\) continue;/.test(SRC));\n    t.verifica('o que desaparece do conjunto acorda os feitiços',\n      /const caidos = \\[\\.\\.\\.feiticosNosComandos\\]\\.filter\\(\\(k\\) => !feiticosAgora\\.has\\(k\\)\\);/.test(SRC)\n      && /if \\(caidos\\.length\\) \\{\\s*\\n\\s*acordar\\('feiticos', 0\\);/.test(SRC));\n    t.verifica('e a primeira passagem não acusa nada',\n      /if \\(feiticosNosComandos\\.size\\) \\{/.test(SRC));\n  }\n  t.secao('A TROPA QUE CHEGA A CASA');\n  {\n    /* Um apoio que regressa, uma esquiva que volta: quando chega, há tropa\n     * disponível que até aí contava como ausente. Os módulos ficavam a saber\n     * só na passagem seguinte — até dois minutos depois (18/09). */\n    t.verifica('o vigia guarda os regressos em curso',\n      /function regressosAgora\\(\\) \\{/.test(SRC) && /if \\(!a\\.is_returning\\) continue;/.test(SRC));\n    t.verifica('o que sai da lista chegou',\n      /const chegaram = \\[\\.\\.\\.regressosEmCurso\\]\\.filter\\(\\(k\\) => !agoraR\\.has\\(k\\)\\);/.test(SRC));\n    t.verifica('e acorda quem pode querer a tropa',\n      /if \\(chegaram\\.length\\) \\{[\\s\\S]{0,160}acordar\\('reforco', 0\\);[\\s\\S]{0,80}acordar\\('apoio', 0\\);/.test(SRC));\n    t.verifica('a primeira passagem não acusa nada',\n      /if \\(regressosEmCurso\\.size\\) \\{/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-agora-semantica.js": "/* A ÁGORA DIZ O QUE A LEITURA É.\n *\n * O `porAlvo` devolvia o que se leu. Vazio, não se sabia se não havia tropa\n * fora ou se a leitura falhou — e foi dessa confusão que vieram os erros que\n * ocuparam dois dias: o apoio a retirar com números de horas antes, as\n * sentinelas a duplicar tropa, o reforço a dar comandos por perdidos.\n *\n * Agora a leitura traz quando foi feita, que cidades cobre e quais faltam. E a\n * retirada — a decisão mais cara do módulo — só acontece nas cidades cuja\n * Ágora foi lida há pouco.\n *\n *   node ferramentas/teste-agora-semantica.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('ÁGORA — SEMÂNTICA');\n\nconst AGORA = Date.now();\n\n/* `cache` são as leituras guardadas; `minhas` as cidades desta conta. */\nfunction montar(cache, minhas) {\n  const sem = (() => {\n    const c = {}; vm.createContext(c);\n    const i = SRC.indexOf('  function leitura(valor, opcoes) {');\n    const f = SRC.indexOf('\\n  try {\\n    uw.__maestroLeitura', i);\n    return vm.runInContext('(() => {\\n' + SRC.slice(i, f)\n      + '\\nreturn { nova: leitura, podeAgir: podeAgirCom, porque: porqueNaoPosso };\\n})()', c);\n  })();\n\n  const ctx = {\n    uw: {\n      __maestroLeitura: sem,\n      ITowns: { towns: Object.fromEntries((minhas || []).map((id) => [id, {}])) },\n    },\n    lerCacheApoioFora: () => cache,\n    apoioForaPorAlvo: () => ({ 500: { unidades: { sword: 10 } } }),\n    APOIO_FORA_VALIDADE: 30 * 60 * 1000,\n    Date, Number, Object, String, console,\n  };\n  vm.createContext(ctx);\n  const i = SRC.indexOf('      leitura: (validadeMs) => {');\n  const f = SRC.indexOf('\\n      },', i) + 8;\n  return vm.runInContext('(() => { const o = {\\n' + SRC.slice(i, f) + '\\n}; return o.leitura; })()', ctx);\n}\n\n(async () => {\n  {\n    /* Tudo lido agora: leitura completa. */\n    const f = montar({ 111: { quando: AGORA }, 222: { quando: AGORA } }, [111, 222]);\n    const l = f(35 * 60 * 1000);\n    t.verifica('com todas as cidades lidas, a leitura é completa', l.completa === true, l);\n    t.verifica('... e diz quais cobre', l.valor.cobertas.length === 2, l.valor);\n    t.verifica('... e que não falta nenhuma', l.valor.emFalta.length === 0, l.valor);\n  }\n  {\n    /* Metade lida: incompleta, e diz quais faltam. */\n    const f = montar({ 111: { quando: AGORA } }, [111, 222]);\n    const l = f(35 * 60 * 1000);\n    t.verifica('com metade lida, a leitura é incompleta', l.completa === false, l);\n    t.verifica('... e diz qual falta', l.valor.emFalta[0] === 222, l.valor);\n    t.verifica('... com a razão escrita', /1 cidade\\(s\\) por ler/.test(l.razao), l.razao);\n  }\n  {\n    /* Leitura velha: não conta como coberta. */\n    const f = montar({ 111: { quando: AGORA - 3600 * 1000 } }, [111]);\n    const l = f(35 * 60 * 1000);\n    t.verifica('uma leitura de há uma hora não conta', l.valor.cobertas.length === 0, l.valor);\n    t.verifica('... e a leitura dá-se por falhada', l.ok === false, l);\n    t.verifica('... dizendo porquê', /não foi lida/.test(l.razao), l.razao);\n  }\n  {\n    /* Sem cidades lidas de todo. */\n    const f = montar({}, [111, 222]);\n    const l = f(35 * 60 * 1000);\n    t.verifica('sem nenhuma leitura: não está ok', l.ok === false && l.completa === false, l);\n  }\n\n  t.secao('A RETIRADA SÓ ONDE A LEITURA É FRESCA');\n  {\n    /* A Ágora é lida a duas cidades por passagem: exigir que cubra as 63\n     * bloquearia a retirada para sempre. */\n    t.verifica('guardam-se as cidades com leitura fresca',\n      /cidadesComLeituraFresca = new Set\\(\\(est && est\\.valor && est\\.valor\\.cobertas\\) \\|\\| \\[\\]\\);/.test(SRC));\n    t.verifica('... e só dessas se retira',\n      /if \\(!cidadesComLeituraFresca\\.has\\(Number\\(c\\)\\)\\) ondeTenho\\.delete\\(c\\);/.test(SRC));\n    t.verifica('as outras ficam para a próxima passagem, com o motivo dito',\n      /a Ágora delas não foi lida há pouco/.test(SRC));\n    t.verifica('e não se exige a leitura toda',\n      /NÃO SE EXIGE A LEITURA TODA — EXIGE-SE A DA CIDADE/.test(SRC));\n  }\n  t.secao('O RITMO DA LEITURA')\n  {\n    /* Com duas cidades por passagem e 63 cidades, uma volta completa demora\n     * perto de uma hora — e as primeiras leituras já passaram dos 35 minutos\n     * quando se chega ao fim. Com cinco, a volta faz-se em vinte e tal\n     * minutos (17/09). */\n    t.verifica('lêem-se cinco cidades por passagem',\n      /api\\.candidatas\\(meus\\) \\|\\| \\[\\]\\)\\)\\), 5\\);/.test(SRC));\n    t.verifica('... e a volta completa cabe na validade da leitura',\n      (() => {\n        const CIDADES = 63, PORPASSAGEM = 5, PASSAGEM_MIN = 2, VALIDADE_MIN = 35;\n        return Math.ceil(CIDADES / PORPASSAGEM) * PASSAGEM_MIN < VALIDADE_MIN;\n      })(), Math.ceil(63 / 5) * 2 + ' min por volta, validade 35 min');\n  }\n  t.secao('O DONO DA CIDADE ONDE A TROPA ESTÁ');\n  {\n    /* Vem no bloco da leitura de uma vez e estava a ser deitado fora. É o que\n     * permite saber que um alvo mudou de mãos: a 2385, tomada ao Jomaras,\n     * aparecia no painel como dele e parecia um erro (17/09). */\n    t.verifica('a leitura guarda o dono de cada bloco',\n      /donoId: Number\\(l\\.player_id\\) \\|\\| 0,/.test(SRC)\n      && /donoNome: String\\(l\\.player_name \\|\\| ''\\)\\.trim\\(\\),/.test(SRC));\n    t.verifica('... e chega ao resto do módulo',\n      /if \\(b\\.donoId && !alvo\\.donoId\\) \\{ alvo\\.donoId = b\\.donoId; alvo\\.donoNome = b\\.donoNome; \\}/.test(SRC));\n    t.verifica('o painel mostra o dono de agora, não o guardado',\n      /O DONO DE AGORA, NÃO O DE QUANDO SE LEU/.test(SRC)\n      && /donoAgora\\[id\\] \\? \\{ jogador: donoAgora\\[id\\] \\} : \\{\\}/.test(SRC));\n    t.verifica('... e mantém o guardado quando não há leitura',\n      /const info = Object\\.assign\\(\\{\\}, guardado,/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-agora-velha.js": "/* A ÁGORA VELHA NÃO PODE PASSAR POR FRESCA.\n *\n * \"Não havia nada a refrescar\" e \"tentei e não consegui\" devolviam ambos zero,\n * e o apoio dizia \"as leituras ainda estão frescas\". Numa conta, as leituras\n * envelheceram CINCO HORAS a dizer isso, e o apoio decidiu com esses números\n * (visto em jogo, 15/09: cidades entre 227 e 519 minutos).\n *\n *   node ferramentas/teste-agora-velha.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('ÁGORA VELHA');\n\nfunction nucleo(cachePreenchida) {\n  const loja = {};\n  if (cachePreenchida) loja['grepoMaestro_apoioFora_v1'] = JSON.stringify(cachePreenchida);\n  const ctx = {\n    uw: {\n      location: { origin: 'https://x' }, Game: { csrfToken: 'T' },\n      /* A Ágora recusa: é o caso que interessa. */\n      fetch: async () => { throw new Error('rede em baixo'); },\n    },\n    localStorage: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = v; } },\n    seErroDeCodigo: () => {}, console, Math, Number, Object, JSON, Date, Promise, setTimeout,\n  };\n  vm.createContext(ctx);\n  const a = SRC.indexOf('  const APOIO_FORA_KEY =');\n  const b = SRC.indexOf('\\n  /* O que esta conta tem em CADA cidade apoiada', a);\n  const api = vm.runInContext('(() => {\\n' + SRC.slice(a, b)\n    + '\\nreturn { refrescar: refrescarApoioFora, ultima: () => ultimaLeitura };\\n})()', ctx);\n  return api;\n}\n\n(async () => {\n  {\n    /* A Ágora falha: zero lidas — mas NÃO é \"estava tudo fresco\". */\n    const n = nucleo();\n    const lidas = await n.refrescar([111, 222], 5);\n    t.verifica('a Ágora falha: zero cidades lidas', lidas === 0, lidas);\n    t.verifica('... e fica registado que se tentaram 2 e falharam 2',\n      n.ultima().tentadas === 2 && n.ultima().falhadas === 2, n.ultima());\n  }\n  {\n    /* Leituras dentro da validade: não há nada a tentar. */\n    const agora = Date.now();\n    const n = nucleo({ 111: { quando: agora, blocos: [] }, 222: { quando: agora, blocos: [] } });\n    const lidas = await n.refrescar([111, 222], 5);\n    t.verifica('tudo fresco: zero lidas e ZERO tentadas', lidas === 0 && n.ultima().tentadas === 0,\n      n.ultima());\n    t.verifica('... e nenhuma falhada — é o caso em que o silêncio é correcto',\n      n.ultima().falhadas === 0, n.ultima());\n  }\n  {\n    /* Leituras velhas: tenta, e falha — não pode passar por fresco. */\n    const velho = Date.now() - 6 * 3600 * 1000;\n    const n = nucleo({ 111: { quando: velho, blocos: [] } });\n    await n.refrescar([111], 5);\n    t.verifica('leitura de há 6 horas: tenta refrescar',\n      n.ultima().tentadas === 1 && n.ultima().falhadas === 1, n.ultima());\n  }\n  t.secao('SÓ AS CIDADES DESTA CONTA');\n  {\n    /* Os modelos incluem blocos de apoio que estão NAS minhas cidades mas\n     * pertencem a outras contas. A cidade de origem desses blocos não é minha,\n     * e pedir a Ágora dela dá \"esta cidade não lhe pertence\" (15/09). */\n    const ctx = {\n      uw: { MM: { getModels: () => ({ Units: {\n        meu: { attributes: { home_town_id: 111, current_town_id: 999 } },\n        deOutraConta: { attributes: { home_town_id: 3104, current_town_id: 111 } },\n      } }) } },\n      localStorage: { getItem: () => '{}', setItem: () => {} },\n      Set, Object, Number, console,\n    };\n    vm.createContext(ctx);\n    const a = SRC.indexOf('  function cidadesComApoioFora(minhasIds) {');\n    const b = SRC.indexOf('\\n  /* ', a + 200);   // até ao comentário seguinte\n    /* Só a função e a leitura da cache de que ela precisa. */\n    const ca = SRC.indexOf('  function lerCacheApoioFora() {');\n    const cb = SRC.indexOf('\\n  }\\n', ca) + 4;\n    const f = vm.runInContext('(() => {\\n  const APOIO_FORA_KEY = \"k\";\\n'\n      + SRC.slice(ca, cb) + SRC.slice(a, b) + '\\nreturn cidadesComApoioFora;\\n})()', ctx);\n    const lista = f([111, 222]);\n    t.verifica('a minha cidade com apoio fora entra na lista', lista.indexOf(111) >= 0, lista);\n    t.verifica('a cidade de outra conta NÃO entra', lista.indexOf(3104) < 0, lista);\n  }\n  t.secao('ABRIR A ÁGORA ANTES DO SEPARADOR');\n  {\n    /* O jogo pede `culture` e só depois `units_beyond` (16/09). O maestro\n     * pedia o segundo directamente e às vezes levava \"erro interno\". */\n    const i = SRC.indexOf('O SEPARADOR SOZINHO NEM SEMPRE CHEGA');\n    const bloco = SRC.slice(i, i + 1800);\n    t.verifica('tenta primeiro o separador, como antes', i > 0\n      && /let txt = await pedir\\('units_beyond'\\);/.test(bloco));\n    t.verifica('... e só se vier sem conteúdo abre a Ágora e repete',\n      /if \\(semHtml\\(txt\\)\\) \\{/.test(bloco) && /await pedir\\('culture'\\);/.test(bloco));\n    t.verifica('nos casos normais não há pedido a mais',\n      bloco.indexOf(\"await pedir('culture')\") > bloco.indexOf('if (semHtml(txt))'));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-aldeias-vazias.js": "/* ALDEIAS — recolher muito e não render nada: pergunta-se ao jogo.\n *\n * Visto em jogo (12/09, conta sem Capitão): \"Recolhidas 126 aldeia(s)\n * (~0 recursos)\" durante mais de uma hora. Por pedido directo o servidor\n * aceita e não dá nada, sem recusa nenhuma. Então abre-se uma aldeia e\n * carrega-se em Recolher: se houver verificação, o jogo mostra-a. Só aí se\n * suspende. O código REAL da recolha, com os modelos simulados.\n *\n *   node ferramentas/teste-aldeias-vazias.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, tira } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('ALDEIAS — RECOLHA VAZIA');\nconst AL = 'function makeAldeiasModule(opts)';\n\n/* `rende` de cada aldeia pronta; `apareceu` = o captcha aparece ao clicar. */\nfunction montar(rende, apareceu) {\n  const chamadas = { tratou: [], mostrou: 0, individual: 0 };\n  const ctx = {\n    mUw: { Game: { player_name: 'MultiX' } }, mWorld: 'pt126', seErroDeCodigo: () => {}, console,\n    relacoesProntas: () => Array.from({ length: 126 }, (_, i) => ({ relationId: i, farmTownId: 900 + i, rende })),\n    temCapitao: () => false,\n    recolhaIndividual: async () => { chamadas.individual++; },\n    recolherEmMassa: async () => ({ ok: true }),\n    tratarCaptcha: async (c, onde) => { chamadas.tratou.push(onde); },\n    mostrarCaptchaPelaRecolha: async () => { chamadas.mostrou++; return !!apareceu; },\n    aldeiaParaMostrarCaptcha: () => ({ farmTownId: 900, townId: 111 }),\n  };\n  vm.createContext(ctx);\n  /* O `fazerRecolha` usa o `recursosEmCasa`, que vive ao nível do módulo. */\n  const txt = 'let antesDeRecolher = -1;\\nlet semEntrada = 0;\\n'\n    + 'let noLimiteHoje = new Set();\\nlet diaDoLimite = new Date().getDate();\\n'\n    + funcao(SRC, '  function limparLimiteSeMudouODia() {', AL)\n    + funcao(SRC, '  function recursosEmCasa() {', AL)\n    + funcao(SRC, '  async function fazerRecolha(ctx, towns) {', AL) + '\\nfazerRecolha';\n  const f = vm.runInContext(txt, ctx);\n  const reg = { ecra: [], rotina: [] };\n  const c = { log: (m) => reg.ecra.push(String(m)), logRotina: (m) => reg.rotina.push(String(m)),\n    sleep: async () => {}, rand: () => 0 };\n  return { reg, chamadas, correr: () => f(c, [{ id: 111 }]) };\n}\n\n(async () => {\n  {\n    const m = montar(1800, false);\n    await m.correr();\n    t.verifica('aldeias que rendem: recolhe como sempre, sem abrir nada',\n      m.chamadas.individual === 1 && m.chamadas.mostrou === 0, m.chamadas);\n  }\n  {\n    const m = montar(0, true);\n    await m.correr();\n    t.verifica('a zero: abre a aldeia e carrega em Recolher', m.chamadas.mostrou === 1, m.chamadas);\n    t.verifica('... o captcha aparece: suspende e avisa', m.chamadas.tratou.length === 1\n      && /render zero/.test(m.chamadas.tratou[0]), m.chamadas);\n    t.verifica('... e não faz a recolha nessa passagem', m.chamadas.individual === 0, m.chamadas);\n  }\n  {\n    const m = montar(0, false);\n    await m.correr();\n    t.verifica('a zero mas sem captcha: NÃO suspende', !m.chamadas.tratou.length, m.chamadas);\n    t.verifica('... e a recolha segue na mesma', m.chamadas.individual === 1, m.chamadas);\n    t.verifica('... com a razão na rotina', m.reg.rotina.some((x) => /nenhuma rende nada/.test(x)), m.reg.rotina);\n  }\n  /* A SUSPENSÃO: enquanto houver verificação, e não meia hora fixa. */\n  {\n    const suspensao = (haCaptcha, hMin) => {\n      const loja = { 'grepoAldeias_captcha_v1': String(Date.now() - hMin * 60000) };\n      const ctx = {\n        armazem: { getItem: (k) => loja[k] || null, setItem: (k, v2) => { loja[k] = v2; },\n          removeItem: (k) => { delete loja[k]; } },\n        agoraServidorMs: () => Date.now(),\n        window: { __maestroHaCaptcha: () => haCaptcha },\n        CAPTCHA_KEY: 'grepoAldeias_captcha_v1',\n        seErroDeCodigo: () => {},\n      };\n      vm.createContext(ctx);\n      const f = vm.runInContext(funcao(SRC, '  function captchaAtivo() {', AL) + '\\ncaptchaAtivo', ctx);\n      return { activo: f(), marca: () => loja['grepoAldeias_captcha_v1'] };\n    };\n    const a = suspensao(true, 2);\n    t.verifica('captcha ainda no ecrã: continua suspenso', a.activo === true);\n    const b = suspensao(false, 2);\n    t.verifica('resolvido ao fim de 2 min: retoma já', b.activo === false, b.activo);\n    t.verifica('... e apaga a marca', !b.marca(), b.marca());\n    const c2 = suspensao(true, 45);\n    t.verifica('tecto de 30 min: não fica suspenso para sempre', c2.activo === false);\n  }\n  t.secao('RECOLHER E NADA ENTRAR NOS ARMAZÉNS');\n  {\n    /* O número do registo é o que as aldeias DEVIAM render, não o que entrou.\n     * Com um captcha por resolver, o servidor aceita, não dá nada, e o registo\n     * anuncia milhões — os armazéns é que não mexem (16/09). */\n    const i = SRC.indexOf('OS RECURSOS QUE ESTAVAM NOS ARMAZÉNS ANTES DE RECOLHER');\n    t.verifica('lê os armazéns antes de recolher', i > 0\n      && /^    antesDeRecolher = recursosEmCasa\\(\\);$/m.test(SRC));\n    t.verifica('... e compara depois', /const entrou = \\(antesDeRecolher >= 0 && depois >= 0\\)/.test(SRC));\n    t.verifica('nada entrou duas vezes seguidas: abre uma aldeia para ver o captcha',\n      /if \\(semEntrada >= 2\\) \\{/.test(SRC) && /abro uma aldeia para ver se há verificação/.test(SRC));\n    t.verifica('uma passagem só não chega — os armazéns podem estar cheios',\n      /confirmo na passagem seguinte/.test(SRC));\n    t.verifica('e o registo passa a dizer quanto entrou de facto',\n      /entraram \\$\\{entrou\\}/.test(SRC));\n  }\n  t.secao('AS FUNÇÕES ESTÃO AO ALCANCE UMAS DAS OUTRAS');\n  {\n    /* O `recursosEmCasa` estava declarado dentro do `fazerRecolha` e era usado\n     * no `recolhaIndividual`, que é outra função: o módulo rebentava com\n     * \"recursosEmCasa is not defined\" (16/09, na 9300). */\n    const nivelDe = (marca) => {\n      const linhas = SRC.split('\\n');\n      const i = linhas.findIndex((l) => l.includes(marca));\n      for (let k = i; k >= 0; k--) {\n        if (/^  (async )?function /.test(linhas[k])) return linhas[k].trim();\n      }\n      return '?';\n    };\n    t.verifica('o recursosEmCasa vive ao nível do módulo',\n      nivelDe('  function recursosEmCasa() {').startsWith('function recursosEmCasa'),\n      nivelDe('  function recursosEmCasa() {'));\n    /* O mesmo erro, a segunda vez: o total de antes era declarado no\n     * `fazerRecolha` e lido no `recolhaIndividual`. O módulo morria a cada\n     * passagem e houve contas dez horas sem recolher (16/09). */\n    t.verifica('o total de antes de recolher também',\n      /^  let antesDeRecolher = -1;$/m.test(SRC)\n      && /^    antesDeRecolher = recursosEmCasa\\(\\);$/m.test(SRC));\n    t.verifica('... e nenhuma das duas é declarada dentro de uma função',\n      !/const antesDeRecolher = recursosEmCasa\\(\\);/.test(SRC)\n      && !/const recursosEmCasa = /.test(SRC));\n    t.verifica('... e as duas funções que o usam alcançam-no',\n      nivelDe('    antesDeRecolher = recursosEmCasa();').includes('fazerRecolha')\n      && nivelDe('const depois = recursosEmCasa();').includes('recolhaIndividual'));\n  }\n  t.secao('NO LIMITE DIÁRIO NÃO É SINAL DE VERIFICAÇÃO');\n  {\n    /* Uma aldeia que já deu o que tinha hoje rende zero — e isso não tem nada\n     * a ver com captchas. Numa conta com as 18 aldeias no limite, o módulo\n     * abria uma aldeia a cada passagem e o clique fazia aparecer a verificação\n     * que não existia antes (17/09, Lagostax no pt127). */\n    t.verifica('as aldeias no limite ficam registadas',\n      /noLimiteHoje\\.add\\(Number\\(p\\.farmTownId\\)\\)/.test(SRC));\n    t.verifica('... e não contam para a sonda do captcha',\n      /const foraDoLimite = prontas\\.filter\\(\\(p\\) => !noLimiteHoje\\.has\\(Number\\(p\\.farmTownId\\)\\)\\);/.test(SRC));\n    t.verifica('só se sonda quando há aldeias fora do limite que não rendem',\n      /if \\(foraDoLimite\\.length\\s*\\n\\s*&& foraDoLimite\\.reduce/.test(SRC));\n    t.verifica('e o registo esvazia-se quando o dia muda',\n      /if \\(hoje !== diaDoLimite\\) \\{ diaDoLimite = hoje; noLimiteHoje = new Set\\(\\); \\}/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-alertas-esquiva.js": "/* ALERTAS E ESQUIVA — a visão geral pelo núcleo, e o que dela se aproveita.\n *\n * O que tem de ser: um ataque inimigo que só a visão geral traz (started_at 0,\n * espia 11/09) é avisado e esquivado; voltas minhas, revoltas, apoios de outros\n * e comandos meus não; o mesmo ataque pelas duas fontes conta uma vez; uma\n * leitura falhada diz-se e não conta como desmentido; um pedido só para os dois.\n *\n *   node ferramentas/teste-alertas-esquiva.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { AGORA_S, vm, tira, funcao, jogo, carregarNucleo, semAdministrador, correr, ligar, lista, ERRO, LIMITADO,\n  igual, PEDIR_JOGO } = S;\nconst SRC = S.ficheiroDoMaestro();\n\nconst t = S.verificador('ALERTAS E ESQUIVA');\n\nconst INIMIGO = { id: 701, type: 'attack', own_command: false, return: false, cmd_return: false, started_at: 0,\n  origin_town_id: 9101, origin_town_name: 'Inimiga', origin_town_player_id: 77, origin_town_player_name: 'Vilão',\n  destination_town_id: 111, arrival_at: AGORA_S + 5400 };\nconst OUTROS = [\n  { id: 702, type: 'attack_land', own_command: true, return: true, cmd_return: true, started_at: AGORA_S - 1000,\n    origin_town_id: 9102, origin_town_player_id: 88, destination_town_id: 111, arrival_at: AGORA_S + 600 },\n  { id: 703, type: 'revolt', own_command: true, started_at: AGORA_S + 3600, origin_town_id: 9103,\n    destination_town_id: 222, arrival_at: AGORA_S + 7200 },\n  { id: 704, type: 'support', own_command: false, started_at: 0, origin_town_id: 9104,\n    destination_town_id: 111, arrival_at: AGORA_S + 400 },\n  { id: 705, type: 'attack_takeover', own_command: true, origin_town_id: 111, destination_town_id: 9999, arrival_at: AGORA_S + 800 },\n  { id: 706, type: 'attack_sea', own_command: true, started_at: AGORA_S - 50, origin_town_id: 222,\n    destination_town_id: 9998, arrival_at: AGORA_S + 900 },\n];\nconst MODELO = (id) => ({ mX: { attributes: { id, type: 'attack', target_town_id: 111, home_town_id: 9101,\n  town_name_origin: 'Inimiga', arrival_at: AGORA_S + 5400 } } });\nconst MODELO_222 = { m1: { attributes: { id: 601, type: 'attack', target_town_id: 222, home_town_id: 9005,\n  town_name_origin: 'DoModelo', arrival_at: AGORA_S + 7000 } } };\nconst naAttack = (tid) => ({ attack: [{ town_id: tid, incoming: 1 }] });\nconst op = (cmds, mais) => Object.assign({ respostas: [lista(cmds)] }, naAttack(111), mais || {});\nconst ligaA = ligar('grepoAlertas_cfg_v1');\nconst ligaE = ligar('grepoEsquiva_cfg_v1');\nconst nada = (r) => r.reg.rotina.some((x) => /nenhum ataque a chegar/.test(x));\nconst desmentidas = (r) => JSON.parse(r.j.localStorage.getItem('grepoEsquiva_desmentidas_v1') || '{}');\n\n(async () => {\n  t.secao('ALERTAS');\n  {\n    const r = await correr(SRC, 'makeAlertasModule', Object.assign({ respostas: [lista(OUTROS)], movimentos: MODELO_222 },\n      naAttack(222)), 1, ligaA);\n    t.verifica('ataque que os modelos trazem: um aviso', r.reg.discord.length === 1, r.reg);\n  }\n  {\n    const r = await correr(SRC, 'makeAlertasModule', op([INIMIGO].concat(OUTROS)), 1, ligaA);\n    t.verifica('ataque inimigo só na visão geral (started_at 0): um aviso, com o nome do atacante',\n      r.reg.discord.length === 1 && /Vilão/.test(JSON.stringify(r.reg.discord)), r.reg.discord);\n    t.verifica('... sem erros de código', r.erros.length === 0, r.erros);\n  }\n  {\n    const r = await correr(SRC, 'makeAlertasModule', op(OUTROS), 1, ligaA);\n    t.verifica('voltas minhas, revoltas, apoio de outro, conquista e ataque meus: nenhum aviso', r.reg.discord.length === 0, r.reg.discord);\n  }\n  for (const [nome, id] of [['com o mesmo número', 701], ['com outro número', 99701]]) {\n    const r = await correr(SRC, 'makeAlertasModule', op([INIMIGO].concat(OUTROS), { movimentos: MODELO(id) }), 1, ligaA);\n    t.verifica(`o mesmo ataque nos modelos e na visão geral, ${nome}: um aviso só`, r.reg.discord.length === 1, r.reg.discord);\n  }\n  {\n    const j = jogo(op([INIMIGO].concat(OUTROS), { movimentos: MODELO(99701) })); carregarNucleo(SRC, j); ligaA(j);\n    const m = S.modulo(SRC, 'makeAlertasModule', j).mod;\n    const reg = { ecra: [], rotina: [], discord: [] }; const c = S.contexto(j, reg);\n    await m.run(c);\n    j.win.MM.getModels = () => ({ PremiumFeatures: { k: { attributes: { curator: 9e12 } } }, MovementsUnits: {} });\n    j.win.__maestroVisaoGeralEsquecer();\n    await m.run(c);\n    t.verifica('passagem seguinte, o mesmo ataque pelo outro número: não repete o aviso', reg.discord.length === 1, reg.discord.length);\n  }\n  {\n    const r = await correr(SRC, 'makeAlertasModule', { respostas: [ERRO] }, 2, ligaA);\n    t.verifica('leitura falhada: diz no ecrã, com a razão', r.reg.ecra.length === 1\n      && /não consegui ler a visão geral \\(Ocorreu um erro\\.\\)/.test(r.reg.ecra[0]), r.reg);\n    t.verifica('... a segunda vez vai para a rotina, e um pedido por passagem', r.reg.rotina.some((m) => /não consegui ler/.test(m))\n      && r.vg === 2, { rotina: r.reg.rotina, vg: r.vg });\n  }\n  {\n    const r = await correr(SRC, 'makeAlertasModule', { respostas: [LIMITADO] }, 1, ligaA);\n    t.verifica('429: diz que o servidor limitou', /429/.test(r.reg.ecra[0] || ''), r.reg.ecra);\n  }\n\n  t.secao('ESQUIVA');\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', op([INIMIGO].concat(OUTROS)), 1, ligaE);\n    t.verifica('ataque inimigo só na visão geral: vê-o (não diz \"nenhum ataque a chegar\")', !nada(r), r.reg);\n    t.verifica('... sem erros de código', r.erros.length === 0, r.erros);\n  }\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', op(OUTROS), 1, ligaE);\n    t.verifica('voltas, revoltas, apoios e comandos meus: nenhum ataque', nada(r), r.reg);\n  }\n  {\n    const so = await correr(SRC, 'makeEsquivaModule', op(OUTROS, { movimentos: MODELO(701) }), 1, ligaE);\n    for (const [nome, id] of [['com o mesmo número', 701], ['com outro número', 99701]]) {\n      const r = await correr(SRC, 'makeEsquivaModule', op([INIMIGO].concat(OUTROS), { movimentos: MODELO(id) }), 1, ligaE);\n      t.verifica(`o mesmo ataque nas duas fontes, ${nome}: faz o mesmo que só com o modelo`,\n        igual(so.reg.ecra, r.reg.ecra) && igual(so.reg.rotina, r.reg.rotina), { so: so.reg, r: r.reg });\n    }\n  }\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', op([OUTROS[4]]), 1, ligaE);\n    t.verifica('servidor responde e não confirma: conta um desmentido, e diz porquê',\n      (desmentidas(r)['111'] || {}).falhas === 1\n      && r.reg.rotina.some((m) => /devolveu 1 comando\\(s\\) mas nenhum para esta cidade/.test(m)), { d: desmentidas(r), rotina: r.reg.rotina });\n  }\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', Object.assign({ respostas: [ERRO] }, naAttack(111)), 10, ligaE);\n    t.verifica('10 leituras falhadas: nenhum desmentido, nenhuma quarentena', !desmentidas(r)['111']\n      && !r.reg.rotina.some((m) => /deixo de perguntar/.test(m)), desmentidas(r));\n    t.verifica('... diz porquê na rotina', r.reg.rotina.some((m) =>\n      /não consegui ler a visão geral \\(Ocorreu um erro\\.\\).*não conta como desmentido/.test(m)), r.reg.rotina);\n    t.verifica('... no ecrã uma vez só, sem dizer \"nenhum ataque a chegar\"',\n      r.reg.ecra.filter((m) => /não consegui ler/.test(m)).length === 1 && !nada(r), r.reg);\n  }\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', Object.assign({ respostas: [LIMITADO] }, naAttack(111)), 1, ligaE);\n    t.verifica('429: diz que o servidor está a limitar', /429/.test(r.reg.ecra[0] || ''), r.reg.ecra);\n  }\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', op([INIMIGO]), 1, (j) => { ligaE(j); semAdministrador(j); });\n    t.verifica('sem Administrador: nenhum pedido, conta o desmentido como sempre, e diz porquê',\n      r.vg === 0 && (desmentidas(r)['111'] || {}).falhas === 1 && r.reg.rotina.some((m) => /\\(sem Administrador\\)/.test(m)),\n      { vg: r.vg, d: desmentidas(r), rotina: r.reg.rotina });\n  }\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', { respostas: [lista([INIMIGO])] }, 1, ligaE);\n    t.verifica('leitura global (nada na colecção Attack): um pedido só', r.vg === 1, r.vg);\n  }\n\n  t.secao('OS DOIS NA MESMA PASSAGEM');\n  {\n    const j = jogo(op([INIMIGO].concat(OUTROS))); carregarNucleo(SRC, j); ligaA(j); ligaE(j);\n    const reg = { ecra: [], rotina: [], discord: [] }; const c = S.contexto(j, reg);\n    await S.modulo(SRC, 'makeAlertasModule', j).mod.run(c);\n    await S.modulo(SRC, 'makeEsquivaModule', j).mod.run(c);\n    t.verifica('alertas + esquiva seguidos → 1 pedido à visão geral', j.pedidosVG() === 1, j.pedidosVG());\n  }\n  t.secao('RECLASSIFICAR');\n  {\n    /* Um ataque visto cedo parece rápido; mais tarde revela-se colonizador.\n     * A marca para o módulo dos feitiços tem de aparecer na mesma. */\n    const marca = (j) => {\n      try { return JSON.parse(j.localStorage.getItem('grepoAlertas_nc_v1') || '{}'); }\n      catch (e) { return {}; }\n    };\n    const INIMIGO_NC = Object.assign({}, INIMIGO, { id: 900, arrival_at: AGORA_S + 60 });\n    const r = await correr(SRC, 'makeAlertasModule',\n      Object.assign({ respostas: [lista([INIMIGO_NC])] }, naAttack(111)), 1, ligaA);\n    t.verifica('um ataque classificado como colonizador fica marcado para os feitiços',\n      Object.keys(marca(r.j)).length >= 0, marca(r.j));\n  }\n  t.secao('SÓ AS CIDADES DESTA CONTA');\n  {\n    /* A lista de cidades a confirmar chegou a trazer cidades que não são da\n     * conta (650 e 5123, numa conta onde não existem): perguntava-se por elas\n     * ao servidor e gastava-se um pedido a não fazer nada (15/09). */\n    t.verifica('a esquiva filtra as cidades que não são desta conta',\n      /\\.filter\\(\\(tid\\) => saoMinhas\\.has\\(Number\\(tid\\)\\)\\)/.test(SRC));\n    t.verifica('e os comandos sem destino não contam para o desmentido',\n      /const comDestino = cmds\\.filter\\(\\(cd\\) => Number\\(cd\\.target_town_id\\) > 0\\);/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-apagar-conta.js": "/* APAGAR UMA CONTA DO MAESTRO.\n *\n * Uma conta banida não volta a correr o Maestro. Fica no sinal de vida a fazer\n * o vigia disparar, nas equipas dos colonizadores a contar para o equilíbrio,\n * e a publicar revoltas que ninguém vai defender (17/09).\n *\n * O botão apaga-a de todos os sítios. É definitivo: se voltar, republica.\n *\n *   node ferramentas/teste-apagar-conta.js maestro.user.js\n */\nconst S = require('./simulador');\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('APAGAR UMA CONTA');\n\n(async () => {\n  const i = SRC.indexOf('APAGAR UMA CONTA DO MAESTRO');\n  const bloco = SRC.slice(i, i + 7000);\n\n  t.verifica('há um botão em cada linha da frota', i > 0\n    && /data-desligar=\"\\$\\{esc\\(x\\.conta\\)\\}\"/.test(SRC));\n  t.verifica('pede confirmação antes de apagar',\n    /if \\(!mUw\\.confirm\\(/.test(bloco) && /É definitivo/.test(bloco));\n\n  t.secao('O QUE APAGA');\n  t.verifica('o sinal de vida na frota',\n    /await fb\\.escrever\\(`frota\\/\\$\\{w\\}`, fr\\);/.test(bloco));\n  t.verifica('... procurando pelo nome, não pela chave',\n    /if \\(String\\(\\(fr\\[k\\] \\|\\| \\{\\}\\)\\.conta \\|\\| k\\) === conta\\)/.test(bloco));\n  t.verifica('as equipas dos colonizadores',\n    /await fb\\.escrever\\(`equipas\\/\\$\\{w\\}`, eq\\);/.test(bloco));\n  t.verifica('as revoltas que publicou',\n    /await fb\\.escrever\\(`revoltasMultis\\/\\$\\{w\\}`, rv\\);/.test(bloco));\n  t.verifica('e o lugar que tivesse no fechar ilha',\n    /delete p\\.atribuicoes\\[conta\\];/.test(bloco)\n    && /if \\(p\\.enviados\\) delete p\\.enviados\\[conta\\];/.test(bloco));\n\n  t.secao('CUIDADOS');\n  t.verifica('o nome é limpo antes de ir para um caminho do Firebase',\n    /const chave = String\\(conta\\)\\.replace\\(/.test(bloco));\n  t.verifica('sem Firebase, não se finge que apagou',\n    /sem Firebase configurado — não há de onde apagar/.test(bloco));\n  t.verifica('diz o que apagou',\n    /apagada do Maestro \\(\\$\\{apagados\\.join\\(', '\\)\\}\\)/.test(bloco));\n\n  t.secao('EM TODOS OS MUNDOS');\n  /* Quem leva ban leva-o na conta, não num mundo: apagar só do mundo actual\n   * deixava-a nos outros a fazer o vigia disparar (17/09). */\n  t.verifica('os mundos descobrem-se pelo que está publicado',\n    /for \\(const raiz of \\['frota', 'equipas', 'revoltasMultis'\\]\\)/.test(bloco));\n  t.verifica('... e o mundo actual entra sempre',\n    /const s = new Set\\(\\[mWorld\\]\\);/.test(bloco));\n  t.verifica('apaga-se em cada um deles',\n    /for \\(const w of mundos\\) \\{/.test(bloco));\n  t.verifica('e o aviso diz que é em todos',\n    /do Maestro, em TODOS os mundos\\?/.test(SRC));\n  t.verifica('... e diz quando não havia nada',\n    /já não estava em lado nenhum/.test(bloco));\n  t.verifica('cada sítio é apagado à parte: um erro não impede os outros',\n    (bloco.match(/catch \\(e\\) \\{ seErroDeCodigo\\(e, 'Frota'\\); \\}/g) || []).length >= 4);\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-apoio-botoes.js": "/* APOIO — reforçar e repor.\n *\n * \"Reforçar\" contava ENVIOS, e um envio era o pacote — que desapareceu com o\n * modo sem objectivo (5000): o botão deixou de mandar seja o que for.\n * \"Repor\" era o que ESTA conta perdeu, por isso nem aparecia na main quando\n * ela não tinha enviado nada. Agora: reforçar é tropa a mais, repor é encher\n * até ao objectivo. O código REAL do módulo.\n *\n *   node ferramentas/teste-apoio-botoes.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, tira, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('APOIO — REFORÇAR E REPOR');\nconst AP = 'function makeApoioModule(opts)';\n\nfunction montar(guardado) {\n  const loja = guardado ? { grepoApoio_reforcar_v1: JSON.stringify(guardado) } : {};\n  const escritos = [];\n  const ctx = {\n    armazem: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = v; } },\n    seErroDeCodigo: () => {}, console, JSON, Object, Number, Math,\n    fbUrlM: () => 'https://falso', fbLerM: async () => ({}),\n    fbEscreverM: async (p, v) => { escritos.push(v); return { ok: true }; },\n    fbCaminhoPedidos: () => 'pedidos/pt125',\n  };\n  vm.createContext(ctx);\n  const api = vm.runInContext(funcao(SRC, '  function lerReforco() {', AP)\n    + funcao(SRC, '  function gravarReforco(d) {', AP)\n    + funcao(SRC, '  async function publicarPedido(tipo, alvoId, quanto) {', AP)\n    + '\\n({ ler: lerReforco, gravar: gravarReforco, publicar: publicarPedido })', ctx);\n  return { api, escritos, loja };\n}\n\n(async () => {\n  {\n    const m = montar();\n    m.api.gravar({ 5512: { sword: 500, bireme: 200 } });\n    t.verifica('o reforço guarda-se como tropa, por alvo',\n      igual(m.api.ler(), { 5512: { sword: 500, bireme: 200 } }), m.api.ler());\n  }\n  {\n    const m = montar({ 5512: { sword: 500 } });\n    await m.api.publicar('reforcar', 5512, { sword: 500, bireme: 200 });\n    const p = m.escritos[0].reforcar_5512;\n    t.verifica('o pedido viaja com as unidades, não com um número de envios',\n      igual(p.unidades, { sword: 500, bireme: 200 }) && p.tipo === 'reforcar' && p.alvo === 5512, p);\n  }\n  {\n    const m = montar();\n    await m.api.publicar('repor', 5512, 1);\n    const p = m.escritos[0].repor_5512;\n    t.verifica('o pedido de repor não leva unidades (é o objectivo que manda)',\n      p.tipo === 'repor' && p.unidades === null && p.quanto === 1, p);\n  }\n  {\n    /* O desconto: o que sai abate ao reforço pedido. */\n    const m = montar({ 5512: { sword: 500, bireme: 200 } });\n    const ctx2 = {\n      armazem: { getItem: () => JSON.stringify({ 5512: { sword: 500, bireme: 200 } }),\n        setItem: (k, v) => { ctx2.__ultimo = JSON.parse(v); } },\n      seErroDeCodigo: () => {}, console,\n      alvo: 5512, cargaFinal: { sword: 300, bireme: 200 },\n      lerReforco: m.api.ler, gravarReforco: (d) => { ctx2.__ultimo = d; },\n      Math, Number, Object, JSON,\n    };\n    vm.createContext(ctx2);\n    vm.runInContext(tira(SRC, '        try {\\n          const extra = lerReforco();\\n          const pedido = extra[alvo];',\n      '        } catch (e) { seErroDeCodigo(e, \\'Apoio\\'); }\\n'), ctx2);\n    t.verifica('o que sai desconta ao reforço; o que ficou por mandar mantém-se',\n      igual(ctx2.__ultimo, { 5512: { sword: 200 } }), ctx2.__ultimo);\n  }\n  t.secao('O REFORÇO CONTA UMA VEZ SÓ, NA QUOTA');\n  {\n    /* O reforço soma-se ao objectivo de propósito. Mas a retirada do excesso\n     * olhava só para o objectivo: cada conta mandava o extra e retirava-o a\n     * seguir (15/09). A quota é o sítio certo — é dela que sai o que falta\n     * mandar E o que conta por excesso. */\n    t.verifica('a quota inclui o reforço pedido',\n      /const extra = lerReforco\\(\\)\\[alvoId\\] \\|\\| \\{\\};/.test(SRC)\n      && /out\\[u\\] = \\(out\\[u\\] \\|\\| 0\\) \\+ n;/.test(SRC));\n    t.verifica('... e já não é somado outra vez ao que há a mandar',\n      /O REFORÇO JÁ ESTÁ NA QUOTA/.test(SRC));\n    t.verifica('o reforço de um alvo que saiu da lista é apagado',\n      /não tem onde ser entregue/.test(SRC));\n  }\n  t.secao('ALVOS QUE NÃO EXPIRAM');\n  {\n    /* O tecto das 14 h foi pensado para revoltas. Mas a lista serve também\n     * para apoios de longa duração — cidades tomadas a um adversário — e\n     * esses estavam a ser tirados a cada passagem (17/09). */\n    const i = SRC.indexOf('OS ALVOS MARCADOS PARA FICAR NÃO EXPIRAM');\n    const bloco = SRC.slice(i, i + 1400);\n    t.verifica('há um registo de alvos fixos', i > 0\n      && /const FIXOS_KEY = 'grepoApoio_alvosFixos_v1';/.test(bloco));\n    t.verifica('o tecto salta os que estão marcados',\n      /\\.filter\\(\\(id\\) => !fixos\\[id\\]\\)/.test(SRC));\n    t.verifica('e o painel tem o visto por alvo',\n      /<input type=\"checkbox\" data-fixo=\"\\$\\{id\\}\"/.test(SRC)\n      && /marcarFixo\\(id, !!cb\\.checked\\);/.test(SRC));\n  }\n  t.secao('QUEM TIRA ALVOS DA LISTA');\n  {\n    /* A remoção lê a lista, tira o que expirou e reescreve-a inteira. Com\n     * vinte contas a fazer isso ao mesmo tempo, a última repõe o que as\n     * outras tiraram — a mensagem repetia-se a cada passagem e os alvos\n     * nunca saíam (17/09: a 3058 e a 652, quatro vezes em sete minutos). */\n    const i = SRC.indexOf('SÓ A CONTA PRINCIPAL TIRA ALVOS DA LISTA');\n    const bloco = SRC.slice(i, i + 1400);\n    t.verifica('a remoção é só da conta principal', i > 0\n      && /const velhos = souAPrincipal \\? alvosPassadosDoTecto\\(alvos\\) : \\[\\];/.test(SRC));\n    t.verifica('... e sabe-se pela marca do painel',\n      /localStorage\\.getItem\\('grepoMaestro_principal_v1'\\) === '1'/.test(bloco));\n    t.verifica('a limpeza dos pedidos segue a mesma regra',\n      /if \\(souAPrincipal && typeof fbLerM === 'function'/.test(SRC));\n    t.verifica('as outras contas continuam a marcar a entrada de cada alvo',\n      /marcarEntrada\\(alvos\\);/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-apoio-painel.js": "/* APOIO — nomes em lote e total por alvo.\n *\n * O botão \"actualizar\" pedia o nome de cada alvo à vez: com uma lista grande\n * o servidor respondia 429, e o 429 trava o maestro inteiro. O `get_chunks`\n * aceita vários blocos, por isso vão num pedido só. E o painel passa a mostrar\n * a tropa TOTAL no alvo (todas as contas), não só a desta conta.\n *\n *   node ferramentas/teste-apoio-painel.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, igual, PEDIR_JOGO } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('APOIO — PAINEL');\nconst AP = 'function makeApoioModule(opts)';\n\n/* Alvos em duas ilhas: 9001/9002 no mesmo bloco do mapa, 9003 noutro. */\nfunction ambiente(frota) {\n  const pedidos = [];\n  const cidade = (id, ix, iy, dono) => ({ id, name: 'Cidade ' + id, player_name: dono, island_x: ix, island_y: iy });\n  const mUw = {\n    location: { origin: 'https://pt125.grepolis.com' },\n    Game: { csrfToken: 'TOK' },\n    ITowns: { towns: { 111: {} } },\n    GameData: { units: { sword: { name: 'espadachim' }, bireme: { name: 'birreme' } } },\n    fetch: async (url) => {\n      pedidos.push(String(url));\n      const j = JSON.parse(decodeURIComponent((String(url).match(/json=([^&]+)/) || [])[1] || '{}'));\n      const data = {};\n      (j.chunks || []).forEach((c, i) => {\n        const towns = {};\n        if (c.x === 25 && c.y === 25) { towns[9001] = cidade(9001, 500, 500, 'Vilão'); towns[9002] = cidade(9002, 502, 505, 'Outro'); }\n        if (c.x === 30 && c.y === 30) { towns[9003] = cidade(9003, 600, 600, 'Terceiro'); }\n        data[i] = { towns };\n      });\n      const corpo = JSON.stringify({ json: { data } });\n      return { status: 200, text: async () => corpo, json: async () => JSON.parse(corpo) };\n    },\n  };\n  const ctx = {\n    mUw, mWorld: 'pt125', CHUNK: 20, seErroDeCodigo: () => {}, console, setTimeout,\n    cacheCidades: {}, gravarNomes: () => {},\n    lerResposta: async (r) => JSON.parse(await r.text()),\n    coordenadasPorMovimentos: (id) => ({ 9001: { x: 500, y: 500 }, 9002: { x: 502, y: 505 }, 9003: { x: 600, y: 600 } }[id] || null),\n    fbUrlM: () => 'https://falso', fbLerM: async () => frota,\n  };\n  vm.createContext(ctx);\n  const txt = PEDIR_JOGO + funcao(SRC, '  async function nomesEmLote(ids, townIdBase) {', AP)\n    + funcao(SRC, '  async function totaisNosAlvos() {', AP)\n    + '\\n({ nomesEmLote, totaisNosAlvos, cache: () => cacheCidades })';\n  return { api: vm.runInContext(txt, ctx), pedidos };\n}\n\nconst agora = Math.floor(Date.now() / 1000);\nconst FROTA = {\n  multi1: { quando: agora - 60, apoio: { alvos: { 9001: { u: { sword: 300, bireme: 20 } } } } },\n  multi2: { quando: agora - 120, apoio: { alvos: { 9001: { u: { sword: 200 } }, 9002: { u: { sword: 50 } } } } },\n  parada: { quando: agora - 7200, apoio: { alvos: { 9001: { u: { sword: 9999 } } } } },\n};\n\n(async () => {\n  {\n    const { api, pedidos } = ambiente(FROTA);\n    const n = await api.nomesEmLote([9001, 9002, 9003], 111);\n    t.verifica('três alvos em dois blocos → UM pedido ao mapa', pedidos.length === 1, pedidos.length);\n    t.verifica('... e descobre os três nomes', n === 3 && api.cache()[9001].nome === 'Cidade 9001'\n      && api.cache()[9003].jogador === 'Terceiro', api.cache());\n  }\n  {\n    const { api, pedidos } = ambiente(FROTA);\n    await api.nomesEmLote([9001], 111);\n    const antes = pedidos.length;\n    const n2 = await api.nomesEmLote([9001], 111);\n    t.verifica('um alvo já conhecido não custa pedido nenhum', n2 === 0 && pedidos.length === antes, pedidos.length);\n  }\n  {\n    const { api } = ambiente(FROTA);\n    const tt = await api.totaisNosAlvos();\n    t.verifica('soma as contas vivas em cada alvo', igual(tt.porAlvo['9001'], { sword: 500, bireme: 20 })\n      && igual(tt.porAlvo['9002'], { sword: 50 }), tt.porAlvo);\n    t.verifica('... e ignora uma conta calada há duas horas', tt.contas === 2 && tt.ok, tt);\n  }\n  {\n    const { api } = ambiente(null);\n    const tt = await api.totaisNosAlvos();\n    t.verifica('sem dados na frota: diz que leu, sem totais', tt.ok && !Object.keys(tt.porAlvo).length, tt);\n  }\n  /* QUANTOS ALVOS MAIS É QUE A TROPA EM CASA COBRE. */\n  {\n    /* O objectivo tem tropa terrestre: a conta precisa da população das\n     * unidades e dos transportes que a levam. */\n    const ctx = { Math, Number, Object, Infinity,\n      mUw: { GameData: { units: { sword: { population: 1 }, archer: { population: 1 },\n        hoplite: { population: 1 }, bireme: { is_naval: true, population: 1 } } } } };\n    vm.createContext(ctx);\n    const f = vm.runInContext(PEDIR_JOGO + funcao(SRC, '  function quantosAlvosMais(casa, objetivo) {', AP) + '\\nquantosAlvosMais', ctx);\n    const obj = { sword: 3000, archer: 3000, hoplite: 3000, bireme: 1500 };\n    t.verifica('tropa para três alvos, travada pelos birremes',\n      igual(f({ sword: 12000, archer: 12000, hoplite: 12000, bireme: 5200, __capacidade: 999999 }, obj), { quantos: 3, limita: 'bireme' }),\n      f({ sword: 12000, archer: 12000, hoplite: 12000, bireme: 5200, __capacidade: 999999 }, obj));\n    t.verifica('sem tropa nenhuma: zero alvos', f({}, obj).quantos === 0);\n    t.verifica('falta uma unidade do objectivo: conta zero, e diz qual',\n      igual(f({ sword: 99999, archer: 99999, hoplite: 99999, __capacidade: 999999 }, obj), { quantos: 0, limita: 'bireme' }),\n      f({ sword: 99999, archer: 99999, hoplite: 99999, __capacidade: 999999 }, obj));\n    t.verifica('sem objectivo definido: não dá para contar', f({ sword: 100 }, {}) === null);\n    /* Sem barcos, a tropa terrestre não sai da ilha. */\n    t.verifica('tropa de sobra mas sem transportes: zero alvos, e diz que são eles',\n      igual(f({ sword: 99999, archer: 99999, hoplite: 99999, bireme: 99999 }, obj),\n        { quantos: 0, limita: 'transportes' }),\n      f({ sword: 99999, archer: 99999, hoplite: 99999, bireme: 99999 }, obj));\n    t.verifica('transportes para dois alvos, tropa para muitos: manda o menor',\n      f({ sword: 99999, archer: 99999, hoplite: 99999, bireme: 99999, __capacidade: 18000 }, obj).quantos === 2,\n      f({ sword: 99999, archer: 99999, hoplite: 99999, bireme: 99999, __capacidade: 18000 }, obj));\n    t.verifica('objectivo com zeros é ignorado',\n      f({ sword: 6000, __capacidade: 999999 }, { sword: 3000, archer: 0 }).quantos === 2,\n      f({ sword: 6000, __capacidade: 999999 }, { sword: 3000, archer: 0 }));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-apoio-transportes.js": "/* APOIO — transportes só quando o alvo está noutra ilha.\n *\n * Na mesma ilha a tropa vai a pé e o jogo não pede transportes. O Apoio\n * pedia-os sempre, e uma cidade sem eles saltava: \"sem transportes para levar\n * a tropa; salto\". O código REAL do Apoio (as funções e as duas linhas onde se\n * decide), com as ilhas simuladas.\n *\n *   node ferramentas/teste-apoio-transportes.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, funcao, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('APOIO — TRANSPORTES');\nconst APOIO = 'function makeApoioModule(opts)';\n\n/* As minhas cidades: 111 na ilha 100:100, 222 na 100:110. `transportes` diz\n * quantos transportes rápidos tem cada uma. */\nfunction montar(transportes) {\n  const ilhas = { 111: [100, 100], 222: [100, 110] };\n  const mUw = {\n    ITowns: {\n      towns: { 111: {}, 222: {} },\n      getTown: (id) => ({\n        getIslandCoordinateX: () => ilhas[id][0], getIslandCoordinateY: () => ilhas[id][1],\n        units: () => Object.assign({ sword: 500 }, (transportes || {})[id] ? { small_transporter: transportes[id] } : {}),\n        researches: () => ({ attributes: {} }),\n      }),\n    },\n    GameData: { units: { sword: { population: 1 } } },\n  };\n  const txt = tira(SRC, '  const CAPACIDADE = {', \"const TERRESTRES = ['sword', 'slinger', 'archer', 'hoplite', 'rider', 'chariot', 'catapult'];\", APOIO)\n    + '\\n' + funcao(SRC, '  function temBeliche(townId) {', APOIO)\n    + funcao(SRC, '  function popDaUnidade(u) {', APOIO)\n    + funcao(SRC, '  function juntarTransportes(townId, pacote, c) {', APOIO)\n    + funcao(SRC, '  function mesmaIlhaQueOAlvo(townId, alvoId) {', APOIO)\n    + '\\nfunction decidir(t, alvo, carga, c) {\\n'\n    + tira(SRC, '        const aPe = mesmaIlhaQueOAlvo(t.id, alvo) === true;', 'juntarTransportes(t.id, carga, c);\\n', APOIO)\n    + '        return cargaFinal;\\n}\\n({ decidir, mesmaIlhaQueOAlvo })';\n  /* Alvos de outros jogadores: um na ilha da 111, outro noutra ilha. */\n  const ctx = { mUw, seErroDeCodigo: () => {},\n    cacheCidades: { 9001: { nome: 'Vizinha', ilha: { x: 100, y: 100 } }, 9002: { nome: 'Longe', ilha: { x: 300, y: 300 } } } };\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx);\n}\nconst temAlgo = (carga) => Object.keys(carga).some((u) => (Number(carga[u]) || 0) > 0);\n\n(async () => {\n  {\n    const a = montar();\n    t.verifica('alvo de outro jogador na mesma ilha → mesma ilha', a.mesmaIlhaQueOAlvo(111, 9001) === true);\n    t.verifica('alvo de outro jogador noutra ilha → outra ilha', a.mesmaIlhaQueOAlvo(111, 9002) === false);\n    t.verifica('alvo que é cidade minha noutra ilha → outra ilha', a.mesmaIlhaQueOAlvo(111, 222) === false);\n    t.verifica('alvo de que não se sabe a ilha → null (fica como estava)', a.mesmaIlhaQueOAlvo(111, 9999) === null);\n  }\n  {\n    const a = montar();   // sem transportes nenhuns\n    const c = a.decidir({ id: 111 }, 9001, { sword: 100 }, {});\n    t.verifica('sem transportes, alvo na mesma ilha: a tropa vai a pé', temAlgo(c) && igual(c, { sword: 100 }), c);\n    const l = a.decidir({ id: 111 }, 9002, { sword: 100 }, {});\n    t.verifica('sem transportes, alvo noutra ilha: não há como levar (salta, como antes)', !temAlgo(l), l);\n    const d = a.decidir({ id: 111 }, 9999, { sword: 100 }, {});\n    t.verifica('sem transportes, ilha do alvo desconhecida: como antes (salta)', !temAlgo(d), d);\n  }\n  {\n    const a = montar({ 111: 20 });\n    const l = a.decidir({ id: 111 }, 9002, { sword: 100 }, {});\n    t.verifica('com transportes, alvo noutra ilha: juntam-se os transportes', (l.small_transporter || 0) > 0 && l.sword === 100, l);\n    const c = a.decidir({ id: 111 }, 9001, { sword: 100 }, {});\n    t.verifica('com transportes, alvo na mesma ilha: não se levam transportes', !c.small_transporter && c.sword === 100, c);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-botao-seletor.js": "/* O BOTÃO DO MAESTRO — ao lado do nome da cidade.\n *\n * Já esteve a flutuar por cima do mapa, dentro da caixa do retrato (por trás\n * da moldura), ao lado do retrato (onde o DIO-Tools tem um painel por cima) e\n * fixo em coordenadas escritas à mão (ficava no sítio errado noutra janela).\n *\n * Agora mede o seletor de cidade e encosta-se a ele. Este teste tira do\n * `maestro.user.js` as duas peças reais — quem procura o seletor e quem\n * calcula o sítio — e corre-as contra um ecrã de mentira.\n *\n *   node ferramentas/teste-botao-seletor.js maestro.user.js\n */\nconst vm = require('vm');\nconst S = require('./simulador');\n\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('O BOTÃO AO LADO DA CIDADE');\n\n/* Tirar um troço do ficheiro, do cabeçalho até ao fecho ao mesmo nível. */\nfunction troco(inicio, fecho) {\n  const i = SRC.indexOf(inicio);\n  if (i < 0) throw new Error('não encontrei: ' + inicio);\n  const j = SRC.indexOf(fecho, i);\n  if (j < 0) throw new Error('não encontrei o fecho de: ' + inicio);\n  return SRC.slice(i, j + fecho.length);\n}\n\n/* Um elemento de mentira, com o tamanho e o sítio que lhe dermos. */\nconst el = (r) => ({ isConnected: true, getBoundingClientRect: () => r });\n\nfunction montar(porNome, janela) {\n  const btn = { style: {} };\n  const ctx = {\n    document: { querySelector: (s) => porNome[s] || null },\n    window: janela || { innerWidth: 1300, innerHeight: 900, addEventListener: () => {} },\n    btn, Math, Number, setTimeout: () => {}, setInterval: () => {}, console,\n  };\n  vm.createContext(ctx);\n  vm.runInContext(troco('function acharSeletorDeCidade() {', '\\n    }\\n'), ctx);\n  /* O `naBarraDoJogo` do ficheiro é isto mesmo: o que o procurador devolve. */\n  vm.runInContext('globalThis.seletor = acharSeletorDeCidade();', ctx);\n  return ctx;\n}\n\n/* O bloco real que calcula o sítio, corrido contra o ecrã de mentira. */\nfunction posicionar(ctx) {\n  /* O bloco real, tal e qual: a folga, os dois números da afinação e a conta\n   * do sítio. Assim os números do teste são os do ficheiro. */\n  vm.runInContext(`{\n    const naBarraDoJogo = globalThis.seletor;\n    ${troco('let alvo = naBarraDoJogo;', '\\n      };\\n')}\n    acompanharSeletor();\n  }`, ctx);\n  return ctx.btn.style;\n}\n\nt.secao('ENCONTRAR O SELETOR');\n{\n  const ctx = montar({ '#town_name_area': el({ left: 500, top: 80, width: 200, height: 30, right: 700 }) });\n  t.verifica('encontra o nome da cidade no topo', !!ctx.seletor);\n}\n{\n  /* O jogo pode ter um elemento com o mesmo nome noutro sítio — o painel da\n   * cidade, por exemplo. O que interessa é o do topo. */\n  const ctx = montar({ '#town_name_area': el({ left: 500, top: 600, width: 200, height: 30, right: 700 }) });\n  t.verifica('não aceita um que esteja a meio do ecrã', ctx.seletor === null);\n}\n{\n  const ctx = montar({ '#town_name_area': el({ left: 0, top: 80, width: 1300, height: 30, right: 1300 }) });\n  t.verifica('não aceita um do tamanho do ecrã', ctx.seletor === null);\n}\n{\n  const ctx = montar({});\n  t.verifica('sem seletor à vista, fica sem sítio (e o botão flutua como antes)',\n    ctx.seletor === null);\n}\n{\n  /* Se o primeiro nome não existir, tenta os outros. */\n  const ctx = montar({ '.town_name': el({ left: 500, top: 80, width: 200, height: 30, right: 700 }) });\n  t.verifica('tenta os outros nomes que o jogo usa', !!ctx.seletor);\n}\n\nt.secao('O SÍTIO, MEDIDO NO SELETOR');\n{\n  const ctx = montar({ '#town_name_area': el({ left: 500, top: 80, width: 200, height: 30, right: 700 }) });\n  const s = posicionar(ctx);\n  t.verifica('encosta à esquerda do nome da cidade, com a afinação dele',\n    s.left === '450px', s.left);\n  t.verifica('e um pouco acima do meio dele', s.top === '69px', s.top);\n}\n{\n  /* Numa janela estreita o seletor fica encostado à esquerda: à esquerda dele\n   * não há espaço, e o botão sairia do ecrã. */\n  const ctx = montar({ '#town_name_area': el({ left: 10, top: 80, width: 200, height: 30, right: 210 }) });\n  const s = posicionar(ctx);\n  /* Do outro lado, a afinação tem de afastar na direcção contrária. */\n  t.verifica('sem espaço à esquerda, passa para a direita e afasta-se na mesma',\n    s.left === '232px', s.left);\n}\n{\n  const janela = { innerWidth: 300, innerHeight: 200, addEventListener: () => {} };\n  const ctx = montar({ '#town_name_area': el({ left: 240, top: 80, width: 200, height: 30, right: 440 }) }, janela);\n  const s = posicionar(ctx);\n  t.verifica('nunca fora do ecrã', parseInt(s.left, 10) <= 300 - 28 - 2 && parseInt(s.left, 10) >= 2, s.left);\n}\n{\n  /* O jogo redesenha a barra ao mudar de cidade: se o elemento guardado saiu\n   * da página, procura-se outro em vez de ficar parado num sítio velho. */\n  const ctx = montar({ '#town_name_area': el({ left: 600, top: 80, width: 200, height: 30, right: 800 }) });\n  /* O guardado saiu da página; na página está outro, mais à direita. */\n  ctx.seletor = { isConnected: false,\n    getBoundingClientRect: () => ({ left: 500, top: 80, width: 200, height: 30, right: 700 }) };\n  const s = posicionar(ctx);\n  t.verifica('se o seletor for substituído, procura-o outra vez', s.left === '550px', s.left);\n}\n{\n  /* Escondido (outra vista do jogo): mexer nele punha-o no canto. */\n  const ctx = montar({ '#town_name_area': el({ left: 500, top: 80, width: 200, height: 30, right: 700 }) });\n  posicionar(ctx);\n  ctx.seletor = el({ left: 0, top: 0, width: 0, height: 0, right: 0 });\n  const s = posicionar(ctx);\n  t.verifica('se o seletor estiver escondido, fica onde estava', s.left === '450px', s.left);\n}\n\nt.secao('O ASPECTO');\n{\n  t.verifica('é um círculo de 28 px', /'width:28px', 'height:28px', 'border-radius:50%',/.test(SRC));\n  t.verifica('com o M maior', /font:700 15px\\/1 \"Trebuchet MS\"/.test(SRC));\n  /* Para acertar o sítio no jogo sem esperar por outra versão. */\n  t.verifica('dá para afinar pela consola',\n    /uw\\.__maestroBotao = \\(x, y\\) => \\{/.test(SRC)\n    && /if \\(Number\\.isFinite\\(x\\)\\) AJUSTE_X = Number\\(x\\);/.test(SRC));\n  t.verifica('e vai para o corpo da página, fora das caixas do jogo',\n    /Vai sempre para o corpo da página[\\s\\S]{0,140}document\\.body\\.appendChild\\(btn\\);/.test(SRC));\n}\nt.fim();\n",
 "teste-broker.js": "/* O BROKER: TODOS OS PEDIDOS AO JOGO PASSAM POR AQUI.\n *\n * Corrigi a mesma falha três vezes numa semana, sempre noutro sítio: o\n * `infoDaCidade` com quatro ciclos a pedir ao mapa sem pausa; o botão do apoio\n * a disparar dezenas de pedidos seguidos; a fundação a varrer o mapa e a\n * trazer quarenta erros. Cada correcção foi um remendo local, e o quarto sítio\n * havia de aparecer (18/09).\n *\n *   node ferramentas/teste-broker.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('BROKER DE PEDIDOS');\n\nfunction montar(travado) {\n  const registo = { pedidos: [], horas: [] };\n  const ctx = {\n    uw: {\n      fetch: async (u) => {\n        registo.pedidos.push(String(u));\n        registo.horas.push(Date.now());\n        return { ok: true, status: 200 };\n      },\n      __maestroServidorTravado: () => !!travado,\n    },\n    seErroDeCodigo: () => {},\n    Date, Math, Number, Promise, setTimeout, Object, console,\n  };\n  vm.createContext(ctx);\n  const i = SRC.indexOf('  const PEDIDOS_PAUSA_MIN = 250;');\n  const f = SRC.indexOf('\\n  try {\\n    uw.__maestroPedir', i);\n  const api = vm.runInContext('(() => {\\n' + SRC.slice(i, f)\n    + '\\nreturn { pedir: pedirAoJogo, estado: () => pedidosEstado };\\n})()', ctx);\n  return { api, registo };\n}\n\n(async () => {\n  t.secao('UM DE CADA VEZ');\n  {\n    const m = montar(false);\n    /* Três ao mesmo tempo, como um ciclo faria. */\n    const r = await Promise.all([\n      m.api.pedir('/a', {}, 5), m.api.pedir('/b', {}, 5), m.api.pedir('/c', {}, 5),\n    ]);\n    t.verifica('os três saem', m.registo.pedidos.length === 3, m.registo.pedidos);\n    const intervalos = m.registo.horas.slice(1)\n      .map((h, i) => h - m.registo.horas[i]);\n    t.verifica('e nunca dois ao mesmo tempo',\n      intervalos.every((x) => x >= 200), intervalos);\n  }\n\n  t.secao('PRIORIDADE');\n  {\n    const m = montar(false);\n    /* Um varrimento primeiro, depois a esquiva: a esquiva passa à frente. */\n    const p = [\n      m.api.pedir('/mapa1', {}, 9), m.api.pedir('/mapa2', {}, 9),\n      m.api.pedir('/esquiva', {}, 0),\n    ];\n    await Promise.all(p);\n    /* O primeiro já ia a caminho; dos que esperaram, a esquiva vem à frente. */\n    t.verifica('quem tem pressa passa à frente dos varrimentos',\n      m.registo.pedidos.indexOf('/esquiva') < m.registo.pedidos.indexOf('/mapa2'),\n      m.registo.pedidos);\n  }\n  {\n    const m = montar(false);\n    await Promise.all([\n      m.api.pedir('/primeiro', {}, 5), m.api.pedir('/segundo', {}, 5),\n    ]);\n    t.verifica('com a mesma prioridade, quem chegou primeiro sai primeiro',\n      m.registo.pedidos[0] === '/primeiro', m.registo.pedidos);\n  }\n\n  t.secao('O TRAVÃO');\n  {\n    const m = montar(true);\n    const r = await m.api.pedir('/x', {}, 5);\n    t.verifica('com o servidor travado, o pedido nem sai', m.registo.pedidos.length === 0);\n    t.verifica('... e quem pediu recebe resposta, não fica pendurado',\n      r && r.status === 429 && r.travado === true, r);\n    t.verifica('... e a resposta é legível como qualquer outra',\n      typeof r.text === 'function' && typeof r.json === 'function');\n  }\n\n  t.secao('QUANDO O PEDIDO REBENTA');\n  {\n    const registo = { pedidos: [] };\n    const ctx = {\n      uw: { fetch: async () => { throw new Error('rede em baixo'); },\n        __maestroServidorTravado: () => false },\n      seErroDeCodigo: () => {}, Date, Math, Number, Promise, setTimeout, Object, console,\n    };\n    vm.createContext(ctx);\n    const i = SRC.indexOf('  const PEDIDOS_PAUSA_MIN = 250;');\n    const f = SRC.indexOf('\\n  try {\\n    uw.__maestroPedir', i);\n    const api = vm.runInContext('(() => {\\n' + SRC.slice(i, f)\n      + '\\nreturn { pedir: pedirAoJogo };\\n})()', ctx);\n    const r = await api.pedir('/x', {}, 5);\n    t.verifica('uma falha de rede não deixa ninguém pendurado', !!r && r.ok === false, r);\n    t.verifica('... e diz o que aconteceu', /rede em baixo/.test(r.erro || ''), r);\n  }\n\n  t.secao('CONTAS');\n  {\n    const m = montar(false);\n    await Promise.all([m.api.pedir('/a', {}, 5), m.api.pedir('/b', {}, 5)]);\n    const e = m.api.estado();\n    t.verifica('conta os pedidos feitos', e.feitos === 2, e);\n    t.verifica('e a fila fica vazia no fim', e.naFila === 0, e);\n  }\n\n  t.secao('TODO O CÓDIGO PASSA POR AQUI');\n  {\n    /* O que interessa não é o broker existir: é mais ninguém pedir por fora. */\n    const i = SRC.indexOf('  async function correrFila() {');\n    const f = SRC.indexOf('\\n  try {\\n    uw.__maestroPedir', i);\n    const foraDoBroker = (SRC.slice(0, i) + SRC.slice(f))\n      .match(/await (mUw|uw)\\.fetch\\(/g) || [];\n    t.verifica('não sobrou nenhum pedido directo ao jogo',\n      foraDoBroker.length === 0, foraDoBroker.length + ' sobraram');\n    t.verifica('e há muitos a passar pelo broker',\n      (SRC.match(/await pedirJogo\\(/g) || []).length > 80,\n      (SRC.match(/await pedirJogo\\(/g) || []).length);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-cancelamento.js": "/* CANCELAR UM COMANDO — o jogo diz se o apagou mesmo.\n *\n * A resposta do `cancelCommand` traz `command_deleted` (espia, 11/09). Um\n * `false` explícito é uma recusa silenciosa: sem `error`, passava por\n * cancelado e a tropa seguia à mesma. Onde o campo não vem, fica como estava.\n * O `post` REAL do Encaixe e da Esquiva, e o cancelamento REAL do Apoio.\n *\n *   node ferramentas/teste-cancelamento.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, funcao, PEDIR_JOGO } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('CANCELAR COMANDOS');\n\nfunction ambiente(resposta) {\n  const corpo = JSON.stringify({ json: resposta });\n  return {\n    mUw: {\n      location: { origin: 'https://pt125.grepolis.com' },\n      Game: { csrfToken: 'TOK' },\n      fetch: async () => ({ status: 200, text: async () => corpo, json: async () => JSON.parse(corpo) }),\n    },\n    window: {}, seErroDeCodigo: () => {}, console,\n    lerResposta: async (r) => JSON.parse(await r.text()),\n    aplicarNotificacoes: () => {},\n  };\n}\n\n/* O `post` do Encaixe (o segundo do ficheiro) e o da Esquiva. */\nfunction posts(qual, resposta) {\n  const ini = SRC.indexOf(qual === 'encaixe' ? 'MÓDULO: ENCAIXE DE COMANDOS' : 'MÓDULO: ESQUIVA DE ATAQUES');\n  const a = SRC.indexOf('  async function post(url, payload) {', ini);\n  const txt = PEDIR_JOGO + SRC.slice(a, SRC.indexOf('\\n  }\\n', a) + 4) + '\\npost';\n  const ctx = ambiente(resposta);\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx)('https://x', {});\n}\n\n/* O cancelamento do Apoio devolve true/false. */\nfunction apoio(resposta) {\n  const txt = PEDIR_JOGO\n    + funcao(SRC, '  async function cancelarOuRetirar(mov, alvoId) {') + '\\ncancelarOuRetirar';\n  const ctx = ambiente(resposta);\n  ctx.registarEnvio = () => {};\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx)({ command_id: 7, home_town_id: 111 }, 999);\n}\n\n(async () => {\n  const CASOS = [\n    ['o jogo apagou o comando', { success: 'O comando foi cancelado.', command_deleted: true }, true],\n    /* Cancelar tropa a caminho transforma o comando num regresso: o jogo\n     * responde `success` com `command_deleted: false`. É sucesso. */\n    ['tropa a caminho: vira regresso (success + command_deleted false)',\n      { success: 'O comando foi cancelado.', command_deleted: false }, true],\n    ['recusa silenciosa (command_deleted false SEM success)', { command_deleted: false }, false],\n    ['resposta sem o campo: fica como estava', { success: 'O comando foi cancelado.' }, true],\n    ['erro do jogo', { error: 'O comando não existe.' }, false],\n  ];\n  for (const [nome, resp, esperado] of CASOS) {\n    for (const qual of ['encaixe', 'esquiva']) {\n      const r = await posts(qual, resp);\n      t.verifica(`${qual}: ${nome}`, r.ok === esperado, r);\n    }\n    const r2 = await apoio(resp);\n    t.verifica(`apoio: ${nome}`, r2 === esperado, r2);\n  }\n  {\n    const r = await posts('encaixe', { command_deleted: false });\n    t.verifica('e diz porquê', /não apagou o comando nem confirmou/.test(r.msg), r.msg);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-captcha.js": "/* CAPTCHA NO ECRÃ — o núcleo pára o ciclo E avisa no Discord.\n *\n * O troço REAL do ciclo (tick) e o `avisarCaptcha` REAL, com o relógio\n * simulado. Com o ciclo parado param os módulos que avisavam; é o núcleo que\n * tem de avisar — logo, e depois de meia em meia hora.\n *\n *   node ferramentas/teste-captcha.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('CAPTCHA NO ECRÃ');\n\nasync function simular(passos) {\n  let agora = 1_800_000_000_000;\n  let captcha = null;\n  const discord = [], registo = [], loja = {};\n  const ctx = {\n    uw: { Game: { player_name: 'MultiX', world_id: 'pt126' },\n      __maestroAvisarDiscord: async (tipo, a) => { discord.push({ tipo, campos: a.campos }); } },\n    localStorage: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = String(v); } },\n    log: (m, x) => registo.push(x), captchaNoEcra: () => captcha,\n    naoTrocarDeCidade: false,\n  };\n  ctx.Date = new Proxy(Date, { get: (tt, p) => (p === 'now' ? () => agora : tt[p]) });\n  vm.createContext(ctx);\n  const txt = tira(SRC, \"  const CAPTCHA_AVISO_KEY = 'grepoMaestro_captchaAvisado_v1';\", 'try { uw.__maestroAvisarCaptcha = avisarCaptcha; } catch (e) {}')\n    + '\\nlet captchaNoEcraDesde = 0, captchaAvisadoEm = 0, captchaIgnorarAte = 0;\\nlet naoTrocarDeCidade = false;\\nasync function passo() {\\n'\n    + tira(SRC, '    const vistoNoEcra = (Date.now() < captchaIgnorarAte) ? null : captchaNoEcra();',\n      \"        log('core', '▶️ O captcha saiu do ecrã — a recolha pode continuar.');\\n      }\\n    }\\n\")\n    + \"  return 'segue';\\n}\\npasso\";\n  const passo = vm.runInContext(txt, ctx);\n  const out = [];\n  for (const p of passos) {\n    agora += (p.min || 0) * 60000;\n    captcha = p.captcha ? { desc: 'iframe 300×150 em 400,300' } : null;\n    const r = await passo();\n    await new Promise((res) => setImmediate(res));\n    out.push({ parado: r !== 'segue', discord: discord.length });\n  }\n  return { out, discord, registo };\n}\n\n(async () => {\n  /* Passagens: sem captcha · aparece · +10 min · +55 · +20 (passa a hora\n   * desde o aviso) · sai. */\n  const d = await simular([{ min: 0 }, { min: 1, captcha: true }, { min: 10, captcha: true },\n    { min: 55, captcha: true }, { min: 20, captcha: true }, { min: 3 }]);\n\n  /* O CAPTCHA JÁ NÃO PÁRA O MAESTRO INTEIRO (16/09).\n   *\n   * Quem fica bloqueado é a recolha das aldeias, que se suspende sozinha. A\n   * construção, o apoio e a esquiva não têm culpa — uma esquiva perdida por\n   * causa de um captcha das aldeias é um mau negócio. */\n  t.verifica('o ciclo continua, mesmo com o captcha no ecrã',\n    d.out.every((p) => !p.parado), d.out);\n  t.verifica('mas trava a troca de cidade enquanto ele lá estiver',\n    /if \\(naoTrocarDeCidade\\) return false;/.test(SRC));\n\n  /* UM MINUTO ANTES DE AVISAR (17/09).\n   *\n   * O aviso saía assim que o captcha aparecia — e quem está a jogar resolve-o\n   * em segundos, ficando o Discord cheio de avisos de coisas já resolvidas. */\n  t.verifica('no primeiro minuto não avisa ninguém', d.out[1].discord === 0, d.out);\n  t.verifica('passado o minuto, avisa', d.out[2].discord === 1, d.out);\n  t.verifica('... e não repete a cada passagem', d.out[3].discord === 1, d.out);\n  t.verifica('... mas repete ao fim de uma hora', d.discord.length >= 2, d.discord.length);\n  t.verifica('a recolha suspende-se logo, sem esperar pelo aviso',\n    /captchaNoEcraDesde = Date\\.now\\(\\);\\s*\\n\\s*captchaAvisadoEm = 0;/.test(SRC));\n\n  t.verifica('o registo diz o que ficou suspenso e quando voltou',\n    d.registo.some((x) => /a recolha fica suspensa/.test(x))\n    && d.registo.some((x) => /a recolha pode continuar/.test(x)), d.registo);\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-colonizador.js": "/* DETECTAR COLONIZADOR — sem a hora de partida.\n *\n * Os ataques dos outros vêm SEMPRE com `started_at: 0` (confirmado em jogo,\n * 12/09), por isso a viagem é estimada e a velocidade sai errada — 37 numa\n * leitura em que o limite do colonizador era 11,5. O que decide sem precisar\n * da partida é o tempo que FALTA: se ainda faltam T horas para percorrer D, a\n * velocidade não pode passar de D/T.\n *\n * As velocidades do jogo já vêm com o factor do mundo (pt126, ×3: colonizador\n * 9 = 3×3, birreme 45 = 15×3), por isso a comparação é na mesma escala.\n *\n *   node ferramentas/teste-colonizador.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, tira } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('COLONIZADOR');\n\nfunction montar() {\n  const ctx = {\n    uw: { GameData: { powers: { unit_movement_boost: { meta_defaults: { percent: 30 } } }, units: {\n      colonize_ship: { speed: 9, is_naval: true },\n      bireme: { speed: 45, is_naval: true },\n      small_transporter: { speed: 45, is_naval: true },\n      attack_ship: { speed: 60, is_naval: true },\n      sword: { speed: 20 },\n    } } },\n    Math, Number, Object,\n    localStorage: { getItem: () => null },\n  };\n  vm.createContext(ctx);\n  /* Do início das constantes até ao fim do `pareceColonizadorNC`. */\n  const a = SRC.indexOf('  const FOLGA_MEDICAO_NC =');\n  const b = SRC.indexOf('  try {\\n    uw.__maestroNC = {', a);\n  return vm.runInContext(SRC.slice(a, b)\n    + '\\n({ parece: pareceColonizadorNC, limite: limiteColonizador })', ctx);\n}\n\n(async () => {\n  const api = montar();\n  /* Todos os bónus juntos: cartografia, farol, navegar, feitiço e 4 sereias. */\n  const TECTO = 9 * 1.10 * 1.15 * 1.10 * 1.30 * Math.pow(1.02, 4);\n  t.verifica('o tecto do colonizador junta cartografia, farol, navegar, feitiço e sereias',\n    Math.abs(api.limite() - TECTO) < 0.05, { limite: api.limite(), esperado: TECTO });\n  {\n    const r = api.parece(9, false);\n    t.verifica('velocidade igual à do colonizador: é colonizador, com certeza', r.nc && r.certo, r);\n  }\n  {\n    const r = api.parece(45, false);\n    t.verifica('velocidade de birreme: não é colonizador', !r.nc, r);\n  }\n  {\n    /* O caso real: velocidade estimada alta (37), mas o tempo que falta prova\n     * que não pode andar a mais de 10. */\n    const r = api.parece(37, false, 10);\n    t.verifica('o que falta da viagem prova colonizador, mesmo com a estimativa alta',\n      r.nc && r.certo && /já não dá para mais nada/.test(r.porque), r);\n  }\n  {\n    const r = api.parece(10, false, 50);\n    t.verifica('10 é a velocidade do colonizador com cartografia: é colonizador, com certeza',\n      r.nc && r.certo, r);\n  }\n  {\n    /* Abaixo do limite, mas sem bater certo com nenhuma unidade nem com os\n     * bónus conhecidos: suspeita, não certeza. */\n    const r = api.parece(6, false);\n    t.verifica('lento de mais para tudo menos o colonizador: suspeita', r.nc && !r.certo, r);\n  }\n  {\n    const r = api.parece(0, false);\n    t.verifica('sem velocidade nenhuma: não afirma nada', !r.nc && !r.certo, r);\n  }\n  /* O ELMO DA INVISIBILIDADE esconde os primeiros 10% da viagem, e nada na\n   * resposta do jogo o denuncia nos ataques dos outros: a velocidade medida\n   * vem ~11% inflada. */\n  {\n    /* Acima do tecto e fora da folga de medição, mas dentro da margem do\n     * elmo (tecto ÷ 0,9). */\n    const r = api.parece(TECTO * 1.10, false);\n    t.verifica('acima do limite mas dentro da margem do elmo: suspeita, não exclusão',\n      r.nc && !r.certo && /elmo/.test(r.porque), r);\n  }\n  {\n    const r = api.parece(TECTO * 1.5, false);\n    t.verifica('bem acima da margem do elmo: não é colonizador', !r.nc && r.certo, r);\n  }\n  {\n    /* O máximo pelo tempo que falta SÓ SERVE PARA ACUSAR: um máximo alto não\n     * prova nada, porque a velocidade real pode ser qualquer uma abaixo. */\n    const r = api.parece(9, false, 999);\n    t.verifica('máximo alto não desfaz uma certeza medida', r.nc && r.certo, r);\n  }\n  /* O FEITIÇO DE MOVIMENTO (+30%, lido do jogo) entra nas combinações. */\n  {\n    /* O \"navegar\" (+10%) só acelera o colonizador: uma velocidade que só ele\n     * explica tem de ser reconhecida. */\n    const r = api.parece(9 * 1.10, false);\n    t.verifica('velocidade que só o navegar explica: é colonizador', r.nc && r.certo, r);\n  }\n  {\n    /* 9 × 1,30 = 11,7: um colonizador só com o feitiço. */\n    const r = api.parece(11.7, false);\n    t.verifica('velocidade que só o feitiço explica: é colonizador, com certeza',\n      r.nc && r.certo && /colonizador/.test(r.porque), r);\n  }\n  {\n    /* 9 × 1,10 × 1,15 × 1,30 = 14,8: tudo junto. */\n    const r = api.parece(TECTO, false);\n    t.verifica('colonizador com tudo: continua a ser apanhado', r.nc, r);\n  }\n  {\n    const r = api.parece(45, false);\n    t.verifica('birreme continua fora de suspeita, mesmo com a folga maior', !r.nc, r);\n  }\n  /* O VISTO DO MUNDO OLIMPO acrescenta o grande templo (+15%). */\n  {\n    const comOlimpo = (() => {\n      const ctx2 = {\n        uw: { GameData: { units: { colonize_ship: { speed: 9, is_naval: true }, bireme: { speed: 45, is_naval: true } },\n          powers: { unit_movement_boost: { meta_defaults: { percent: 30 } } } } },\n        Math, Number, Object, localStorage: { getItem: () => '1' },\n      };\n      vm.createContext(ctx2);\n      const a = SRC.indexOf('  const FOLGA_MEDICAO_NC =');\n      const b = SRC.indexOf('  try {\\n    uw.__maestroNC = {', a);\n      return vm.runInContext(SRC.slice(a, b) + '\\n({ limite: limiteColonizador, parece: pareceColonizadorNC })', ctx2);\n    })();\n    t.verifica('mundo Olimpo: o tecto sobe 15%',\n      Math.abs(comOlimpo.limite() - TECTO * 1.15) < 0.05,\n      { olimpo: comOlimpo.limite(), normal: TECTO });\n    t.verifica('... e uma velocidade que só o templo explica passa a ser apanhada',\n      comOlimpo.parece(TECTO * 1.14, false).nc && !api.parece(TECTO * 1.14, false).nc);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-colonizadores-revoltas.js": "/* APOIO (revoltas), FUNDAÇÃO e EXPANSÃO — a visão geral pelo núcleo.\n *\n * Apoio: cópia partilhada. Fundação e Expansão: sempre fresca, porque um\n * colonizador enviado agora tem de contar já. E \"não consegui ler\" nunca é\n * \"nenhum colonizador a caminho\": a fundação não funda, a barreira não deixa\n * sair nenhum.\n *\n *   node ferramentas/teste-colonizadores-revoltas.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { AGORA_S, vm, tira, funcao, jogo, carregarNucleo, semAdministrador, correr, ligar, lista, ERRO, LIMITADO,\n  igual, PEDIR_JOGO } = S;\nconst SRC = S.ficheiroDoMaestro();\n\nconst t = S.verificador('APOIO, FUNDAÇÃO, EXPANSÃO');\n\nasync function apoio(j) {\n  const seg = tira(SRC, '            const temAdm = (() => {', 'const visaoOk = !!vg.ok;');\n  const porque = tira(SRC, \"              const porque = !temAdm ? 'esta conta não tem Administrador'\", ';\\n');\n  const ctx = { mUw: j.win, window: j.win, console };\n  vm.createContext(ctx);\n  return vm.runInContext(PEDIR_JOGO + `(async () => {\\n${seg}\\n${porque}\\nreturn { cmdsLidos, visaoOk, porque }; })()`, ctx);\n}\nasync function fundacao(j) {\n  const f = tira(SRC, \"  let razaoColonizadores = '';\", '\\n    return out;\\n  }\\n');\n  const ctx = { mUw: j.win, window: j.win, console, seErroDeCodigo: () => {}, coordenadasDoLinkDestino: () => null };\n  vm.createContext(ctx);\n  const r = await vm.runInContext(f + '\\nilhasComColonizadorAcaminho(111)', ctx);\n  return { r, razao: vm.runInContext('razaoColonizadores', ctx) };\n}\nfunction expansao(j) {\n  const txt = tira(SRC, '  const jogo = () => (typeof unsafeWindow', '\\n')\n    + tira(SRC, '  let colonizacoesQuando = 0;', '\\n')\n    + funcao(SRC, '  async function refrescarColonizacoes() {')\n    + tira(SRC, '  function podeFundarNaIlha(uw, ctx, x, y) {', \"\\n    return { pode: true, porque: '' };\\n  }\\n\")\n    + '\\n({ refrescar: refrescarColonizacoes, pode: (x, y) => podeFundarNaIlha(window, '\n    + '{ getMyTowns: () => [{ id: 111 }, { id: 222 }] }, x, y) })';\n  const loja = {};\n  const ctx = { window: j.win, console, seErroDeCodigo: () => {},\n    localStorage: { getItem: (k) => loja[k] || null, setItem: (k, v) => { loja[k] = v; } } };\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx);\n}\n\nconst REVOLTAS = [\n  { id: 'revolt_901', type: 'revolt', started_at: AGORA_S + 3000, origin_town_id: 9001, destination_town_id: 222, arrival_at: AGORA_S + 9000 },\n  { id: 902, type: 'attack', started_at: 0, origin_town_id: 9002, destination_town_id: 111, arrival_at: AGORA_S + 500 },\n];\nconst COLONO = { id: 'colonization_5120', type: 'colonization', origin_town_id: 111, island_x: 365, island_y: 460,\n  number_on_island: 1, arrival_at: AGORA_S + 4000 };\nconst COLONO_FEITO = Object.assign({}, COLONO, { id: 'colonization_5121', island_x: 300, island_y: 300,\n  colonization_finished_at: AGORA_S - 10 });\n\n(async () => {\n  t.secao('APOIO — revoltas');\n  {\n    const j = jogo({ respostas: [lista(REVOLTAS)] }); carregarNucleo(SRC, j);\n    const d = await apoio(j);\n    t.verifica('leitura boa: a lista toda', d.visaoOk && d.cmdsLidos.length === 2, d);\n  }\n  {\n    const j = jogo({ respostas: [ERRO] }); carregarNucleo(SRC, j);\n    const d = await apoio(j);\n    t.verifica('erro do jogo: leitura falhada (não é \"nenhuma revolta\"), e diz porquê', !d.visaoOk && d.cmdsLidos === null\n      && d.porque === 'Ocorreu um erro.', d);\n  }\n  {\n    const j = jogo({ respostas: [LIMITADO] }); carregarNucleo(SRC, j);\n    let travou = 0; j.win.__maestroTravar = () => { travou++; };\n    const d = await apoio(j);\n    t.verifica('429: leitura falhada, e o núcleo trava', !d.visaoOk && travou === 1, { d, travou });\n  }\n  {\n    const j = jogo({ respostas: [lista(REVOLTAS)] }); carregarNucleo(SRC, j); semAdministrador(j);\n    const d = await apoio(j);\n    t.verifica('sem Administrador: nenhum pedido, e diz porquê', !d.visaoOk && j.pedidosVG() === 0 && /não tem Administrador/.test(d.porque), d);\n  }\n  {\n    const j = jogo({ respostas: [lista(REVOLTAS)] }); carregarNucleo(SRC, j);\n    await j.win.__maestroVisaoGeral();\n    const d = await apoio(j);\n    t.verifica('com uma cópia recente: usa-a, sem pedido novo', d.visaoOk && j.pedidosVG() === 1, j.pedidosVG());\n  }\n\n  t.secao('FUNDAÇÃO — colonizadores em viagem');\n  {\n    const j = jogo({ respostas: [lista([COLONO, COLONO_FEITO])] }); carregarNucleo(SRC, j);\n    const d = await fundacao(j);\n    t.verifica('\"365:460\", como quem chama procura; o que já fundou fica de fora', d.r.has('365:460') && d.r.size === 1, [...d.r]);\n  }\n  {\n    const j = jogo({ respostas: [lista([]), lista([COLONO])] }); carregarNucleo(SRC, j);\n    await j.win.__maestroVisaoGeral();\n    const d = await fundacao(j);\n    t.verifica('com uma cópia de antes do envio: vai ao servidor e vê o colonizador', d.r && d.r.has('365:460') && j.pedidosVG() === 2,\n      { r: d.r && [...d.r], pedidos: j.pedidosVG() });\n  }\n  {\n    const j = jogo({ respostas: [ERRO] }); carregarNucleo(SRC, j);\n    const d = await fundacao(j);\n    t.verifica('leitura falhada: null (não funda nesta passagem), com a razão', d.r === null && d.razao === 'Ocorreu um erro.', d);\n  }\n  {\n    const j = jogo({ respostas: [lista([COLONO])] }); carregarNucleo(SRC, j); semAdministrador(j);\n    const d = await fundacao(j);\n    t.verifica('sem Administrador: como sempre (vazio), sem pedido', d.r && d.r.size === 0 && j.pedidosVG() === 0, d);\n  }\n\n  t.secao('EXPANSÃO — a lista e a barreira');\n  {\n    const j = jogo({ respostas: [lista([COLONO, COLONO_FEITO])] }); carregarNucleo(SRC, j);\n    const e = expansao(j); await e.refrescar();\n    t.verifica('a lista dos que vão a caminho', igual(j.win.__maestroColonizacoesEmCurso.map((x) => x.id), ['colonization_5120']),\n      j.win.__maestroColonizacoesEmCurso);\n    t.verifica('a barreira trava a ilha com colonizador e deixa as outras', !e.pode(365, 460).pode && e.pode(500, 500).pode,\n      [e.pode(365, 460), e.pode(500, 500)]);\n    await e.refrescar();\n    t.verifica('não volta a perguntar antes de um minuto', j.pedidosVG() === 1, j.pedidosVG());\n  }\n  {\n    const j = jogo({ respostas: [ERRO, lista([])] }); carregarNucleo(SRC, j);\n    const e = expansao(j); await e.refrescar();\n    const p = e.pode(365, 460);\n    t.verifica('leitura falhada: a barreira não deixa sair nenhum, e diz porquê', p.pode === false\n      && /não consegui ler os colonizadores em viagem \\(Ocorreu um erro\\.\\)/.test(p.porque), p);\n    await e.refrescar();\n    t.verifica('... na passagem seguinte volta a ler e, lida, deixa sair', e.pode(500, 500).pode === true && j.pedidosVG() === 2,\n      { p: e.pode(500, 500), pedidos: j.pedidosVG() });\n  }\n  {\n    const j = jogo({ respostas: [lista([COLONO])] }); carregarNucleo(SRC, j); semAdministrador(j);\n    const e = expansao(j); await e.refrescar();\n    t.verifica('sem Administrador: como sempre (lista vazia, a barreira deixa), sem pedido',\n      e.pode(365, 460).pode === true && igual(j.win.__maestroColonizacoesEmCurso, []) && j.pedidosVG() === 0);\n  }\n  {\n    const j = jogo({ respostas: [lista([]), lista([COLONO])] }); carregarNucleo(SRC, j);\n    await j.win.__maestroVisaoGeral();\n    const e = expansao(j); await e.refrescar();\n    t.verifica('com uma cópia de antes do envio: vai ao servidor e trava a ilha', e.pode(365, 460).pode === false && j.pedidosVG() === 2);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-demoras.js": "/* AS DEMORAS QUE O JOGO DÁ — comparar tempo com tempo.\n *\n * A janela de atacar devolve, para o alvo escolhido, quanto demora CADA\n * unidade, já com a distância, a velocidade do mundo e os bónus (visto em\n * jogo, 14/09: espadachim 625 s, colonizador 793 s…). É a única fonte na\n * MESMA ILHA, onde a distância entre ilhas é zero e não há velocidade para\n * medir.\n *\n *   node ferramentas/teste-demoras.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, funcao, PEDIR_JOGO } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('DEMORAS');\n\nfunction montar(resposta) {\n  const pedidos = [];\n  const loja = {};\n  const corpo = JSON.stringify(resposta || {});\n  const ctx = {\n    uw: {\n      location: { origin: 'https://pt126.grepolis.com' }, Game: { csrfToken: 'TOK' },\n      GameData: {\n        units: { sword: { speed: 26.4 }, hoplite: { speed: 19.8 },\n          colonize_ship: { speed: 9, is_naval: true }, bireme: { speed: 49.5, is_naval: true } },\n        powers: { unit_movement_boost: { meta_defaults: { percent: 30 } } },\n      },\n      fetch: async (u) => { pedidos.push(String(u)); return { status: 200, text: async () => corpo }; },\n    },\n    localStorage: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = v; } },\n    servidorTravado: () => false,\n    lerRespostaComum: async (r) => JSON.parse(await r.text()),\n    Math, Number, Object, JSON, Promise, Date, encodeURIComponent,\n  };\n  vm.createContext(ctx);\n  const a = SRC.indexOf('  const FOLGA_MEDICAO_NC =');\n  const b = SRC.indexOf('  try {\\n    uw.__maestroDemoras = {', a);\n  vm.runInContext(PEDIR_JOGO + SRC.slice(a, b) + '\\n({})', ctx);\n  return { ctx, pedidos, loja };\n}\n\n/* A janela real, com os números de 14/09. */\nconst JANELA = { json: { json: { runtime_setup_time: 300, units: {\n  sword: { duration: 625, speed: 26.4 },\n  hoplite: { duration: 734, speed: 19.8 },\n  colonize_ship: { duration: 793, speed: 9 },\n  bireme: { duration: 473, speed: 49.5 },\n} } } };\n\n(async () => {\n  {\n    const m = montar(JANELA);\n    const d = await m.ctx.demorasPara(111, 999);\n    t.verifica('lê as demoras da janela de atacar', d && d.u.colonize_ship === 793 && d.prep === 300, d);\n    t.verifica('... com um pedido só', m.pedidos.length === 1, m.pedidos.length);\n    const d2 = await m.ctx.demorasPara(111, 999);\n    t.verifica('... e não repete o pedido: fica guardado', m.pedidos.length === 1 && d2.u.sword === 625);\n  }\n  {\n    const m = montar(JANELA);\n    const d = await m.ctx.demorasPara(111, 999);\n    const r = m.ctx.unidadesQueExplicamPorTempo(d, 793);\n    t.verifica('uma viagem de 793 s: o colonizador sem bónus explica-a',\n      r.some((x) => x.id === 'colonize_ship'), r.map((x) => x.id));\n  }\n  {\n    const m = montar(JANELA);\n    const d = await m.ctx.demorasPara(111, 999);\n    const r = m.ctx.unidadesQueExplicamPorTempo(d, 625);\n    /* 625 s é o tempo do espadachim — mas um colonizador com cartografia,\n     * farol, navegar e sereias também lá chega. Ambos explicam, logo fica a\n     * dúvida: é o resultado honesto, e o lado seguro. */\n    t.verifica('625 s: o espadachim explica, mas o colonizador com bónus também — fica a dúvida',\n      r.some((x) => x.id === 'sword') && r.some((x) => x.id === 'colonize_ship'), r.map((x) => x.id));\n    t.verifica('... e o espadachim é a explicação mais próxima', r[0].id === 'sword', r[0]);\n  }\n  {\n    /* Colonizador com feitiço: 300 + (793-300)/1,30 = 679 s. */\n    const m = montar(JANELA);\n    const d = await m.ctx.demorasPara(111, 999);\n    const r = m.ctx.unidadesQueExplicamPorTempo(d, 679);\n    t.verifica('colonizador com o feitiço: continua a ser apanhado',\n      r.some((x) => x.id === 'colonize_ship'), r);\n  }\n  {\n    const m = montar(JANELA);\n    const d = await m.ctx.demorasPara(111, 999);\n    const r = m.ctx.unidadesQueExplicamPorTempo(d, 120);\n    t.verifica('depressa de mais para tudo: nada explica', r.length === 0, r);\n  }\n  {\n    const m = montar({ json: { json: { units: {} } } });\n    const d = await m.ctx.demorasPara(111, 999);\n    t.verifica('resposta sem demoras: devolve null (não inventa)', d === null, d);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-deuses-minimo.js": "/* DEUSES — o mínimo do jogo é em HABITANTES.\n *\n * \"Uma tropa de ataque tem de ser constituída pelo menos por 86 habitantes.\"\n * O módulo comparava CONTAGENS: 36 enviados contavam 36, quando valem 3 de\n * população cada (108). Cidades que já cumpriam o mínimo juntavam espadachins\n * à toa e, sem eles, ficavam à espera — visto em jogo (14/09, 34.3 e 34.4).\n *\n *   node ferramentas/teste-deuses-minimo.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('DEUSES — MÍNIMO');\n\n/* O troço real da decisão, com o mínimo, os enviados e os espadachins. */\nfunction decidir({ minimo, quantos, swords }) {\n  const reg = [];\n  const ctx = {\n    mUw: {\n      GameData: { units: { godsent: { population: 3 }, sword: { population: 1 } } },\n      ITowns: { getTown: () => ({ units: () => ({ sword: swords }) }) },\n    },\n    UNIDADE_ENVIADO: 'godsent',\n    minimoAprendido: () => minimo,\n    t: { id: 111, name: 'Cidade' },\n    quantos,\n    ctx: { log: (m) => reg.push(String(m)), logRotina: (m) => reg.push(String(m)) },\n    Math, Number,\n  };\n  vm.createContext(ctx);\n  /* Do comentário até ao fim do bloco do mínimo (o `}` que fecha o `if`). */\n  const i = SRC.indexOf('      /* O MÍNIMO DO JOGO É EM HABITANTES, NÃO EM UNIDADES.');\n  const fim = SRC.indexOf('\\n      /* VÁRIOS ATAQUES EM CURSO SÃO PERMITIDOS.', i);\n  const corpo = SRC.slice(i, fim);\n  /* `continue` só vale dentro de um ciclo: embrulha-se num. */\n  /* `escudoExtra` é `let` dentro do ciclo: leva-se para fora numa variável\n   * do contexto. */\n  vm.runInContext('var resultado = null;\\nfor (let i = 0; i < 1; i++) {\\n' + corpo\n    + '\\n  resultado = escudoExtra;\\n}', ctx);\n  return { escudoExtra: ctx.resultado, reg };\n}\n\n(async () => {\n  {\n    /* O caso real: 36 enviados = 108 habitantes, mínimo 80. Chega de sobra. */\n    const r = decidir({ minimo: 80, quantos: 36, swords: 44 });\n    t.verifica('36 enviados (108 hab.) com mínimo 80: ataca sem espadachins nenhuns',\n      r.escudoExtra === 0 && !r.reg.some((x) => /espero/.test(x)), r);\n  }\n  {\n    /* 20 enviados = 60 habitantes, mínimo 86: faltam 26 espadachins. */\n    const r = decidir({ minimo: 86, quantos: 20, swords: 100 });\n    t.verifica('faltam habitantes: junta exactamente os espadachins precisos',\n      r.escudoExtra === 26 && r.reg.some((x) => /junto 26 espadachins/.test(x)), r);\n  }\n  {\n    const r = decidir({ minimo: 86, quantos: 20, swords: 26 });\n    t.verifica('tem mesmo os que faltam: não guarda nenhum em casa (falhava por um)',\n      r.escudoExtra === 26, r);\n  }\n  {\n    const r = decidir({ minimo: 86, quantos: 5, swords: 10 });\n    t.verifica('nem com tudo chega: espera, e diz os habitantes',\n      r.reg.some((x) => /não chegam ao mínimo de 86 habitantes/.test(x)), r.reg);\n  }\n  {\n    const r = decidir({ minimo: 0, quantos: 5, swords: 0 });\n    t.verifica('sem mínimo aprendido: não mexe em nada', r.escudoExtra === 0, r);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-encaixe-carga.js": "/* ENCAIXE — as composições enchem os barcos até cima.\n *\n * A capacidade saía da tabela base (10 e 26) e ignorava a pesquisa de porões\n * (16 e 32). Com 138 transportes rápidos davam-se 1380 lugares em vez de 2208:\n * as composições levavam menos 293 de tropa (visto em jogo, 13/09). O\n * enchimento REAL do módulo.\n *\n *   node ferramentas/teste-encaixe-carga.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('ENCAIXE — CARGA');\n\n/* A cidade da imagem: 950 espadachins, 965 arqueiros, 481 hoplitas, 138\n * transportes rápidos. */\nconst TENHO = { sword: 950, archer: 965, hoplite: 481, small_transporter: 138 };\nconst GD = {\n  sword: { population: 1 }, archer: { population: 1 }, hoplite: { population: 1 },\n  small_transporter: { is_naval: true, capacity: 10 }, big_transporter: { is_naval: true, capacity: 26 },\n};\n\nfunction encher(carga, poroes, tenho) {\n  const ctx = {\n    gd: GD, tenho: tenho || TENHO, carga,\n    t: { researches: () => ({ attributes: poroes ? { berth: true } : {} }) },\n    seErroDeCodigo: () => {}, Number, Object, Math,\n  };\n  vm.createContext(ctx);\n  vm.runInContext(tira(SRC, '            try {\\n              /* OS PORÕES CONTAM.', '            } catch (e) { seErroDeCodigo(e, \\'Encaixe\\'); }\\n'), ctx);\n  return ctx.carga;\n}\nconst soma = (c) => Object.keys(c).filter((u) => !GD[u].is_naval)\n  .reduce((s, u) => s + (Number(c[u]) || 0) * (GD[u].population || 1), 0);\n\n(async () => {\n  {\n    const c = encher({ small_transporter: 138 }, true);\n    t.verifica('com porões: 138 transportes = 2208 lugares, cheios', soma(c) === 2208, { c, soma: soma(c) });\n    t.verifica('... e sobra hoplitas para os 293 lugares que faltavam',\n      c.sword === 950 && c.archer === 965 && c.hoplite === 293, c);\n  }\n  {\n    const c = encher({ small_transporter: 138 }, false);\n    t.verifica('sem porões: 1380 lugares (era isto que dava sempre)', soma(c) === 1380, soma(c));\n  }\n  {\n    const c = encher({ small_transporter: 138, big_transporter: 1 }, true);\n    t.verifica('com um barco grande: mais 32 lugares', soma(c) === 2240, soma(c));\n  }\n  {\n    const c = encher({ small_transporter: 400 }, true);\n    t.verifica('barcos a mais do que tropa: leva a tropa toda e não inventa',\n      soma(c) === 950 + 965 + 481, { c, soma: soma(c) });\n  }\n  {\n    const c = encher({}, true);\n    t.verifica('sem transportes: não leva tropa nenhuma', soma(c) === 0, c);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-encaixe.js": "/* ENCAIXE — a leitura da visão geral, SEMPRE fresca.\n *\n * O encaixe pergunta a seguir a enviar: uma cópia de há 20 s não tem o comando\n * que acabou de sair. E uma leitura falhada deixa sempre a razão registada\n * (sai na linha [diagnóstico]).\n *\n *   node ferramentas/teste-encaixe.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { AGORA_S, vm, tira, funcao, jogo, carregarNucleo, semAdministrador, correr, ligar, lista, ERRO, LIMITADO,\n  igual, PEDIR_JOGO } = S;\nconst SRC = S.ficheiroDoMaestro();\n\nconst t = S.verificador('ENCAIXE');\n\nfunction encaixe(j) {\n  const ini = SRC.indexOf('MÓDULO: ENCAIXE DE COMANDOS');\n  const marcas = tira(SRC, '  let semAdmAte = 0;', \"  let ultimaRazaoVazio = '';\\n\", 'MÓDULO: ENCAIXE DE COMANDOS');\n  const txt = PEDIR_JOGO + marcas + funcao(SRC, '  async function lerResposta(resposta) {', 'MÓDULO: ENCAIXE DE COMANDOS')\n    + funcao(SRC, \"  async function comandosDoServidor(townId) {\\n    if (semAdministrador())\", 'MÓDULO: ENCAIXE DE COMANDOS')\n    + '\\n({ ler: comandosDoServidor, razao: () => ultimaRazaoVazio })';\n  void ini;\n  const ctx = { mUw: j.win, window: j.win, uw: j.win, seErroDeCodigo: () => {}, console };\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx);\n}\n\nconst CMDS = [\n  { id: 801, type: 'attack_land', own_command: true, started_at: AGORA_S - 5, origin_town_id: 111,\n    destination_town_id: 5555, arrival_at: AGORA_S + 3600, cancelable: true },\n  { id: 802, type: 'attack_land', own_command: true, return: true, started_at: AGORA_S - 900, origin_town_id: 5556,\n    destination_town_id: 111, arrival_at: AGORA_S + 60 },\n  { id: 803, type: 'support', own_command: true, started_at: AGORA_S - 30, origin_town_id: 222,\n    destination_town_id: 5557, arrival_at: AGORA_S + 1200, cancelable: false },\n];\n\n(async () => {\n  for (const [nome, corpo] of [['json.data.commands', { json: { data: { commands: CMDS } } }], ['json.commands', { json: { commands: CMDS } }]]) {\n    const j = jogo({ respostas: [{ corpo }] }); carregarNucleo(SRC, j);\n    const d = await encaixe(j).ler(111);\n    t.verifica(`${nome}: os comandos, sem a volta`, igual(d.map((x) => x.command_id), [801, 803]) && d[0].cancelavel === true, d);\n  }\n  {\n    const j = jogo({ respostas: [lista(CMDS.slice(1)), lista(CMDS)] }); carregarNucleo(SRC, j);\n    const outro = await j.win.__maestroVisaoGeral();\n    const d = await encaixe(j).ler(111);\n    t.verifica('com uma cópia recente sem o comando novo: vai ao servidor e encontra-o',\n      outro.ok && j.pedidosVG() === 2 && d.some((x) => x.command_id === 801), { pedidos: j.pedidosVG(), d });\n    const depois = await j.win.__maestroVisaoGeral();\n    t.verifica('... e a leitura dele passa a ser a cópia dos outros', depois.daCopia && depois.comandos.some((x) => x.id === 801));\n  }\n  {\n    const j = jogo({ respostas: [lista(CMDS)] }); carregarNucleo(SRC, j);\n    const e = encaixe(j); await e.ler(111); await e.ler(111); await e.ler(111);\n    t.verifica('três leituras seguidas depois de enviar → três pedidos (nada vem da cópia)', j.pedidosVG() === 3, j.pedidosVG());\n  }\n  for (const [nome, resp, re] of [['erro do jogo', ERRO, /^Ocorreu um erro\\.$/], ['lista vazia', lista([]), /veio sem comandos/],\n    ['429', LIMITADO, /recusar/], ['resposta sem lista', { corpo: { json: { data: { outra: 1 } } } }, /não traz a lista/]]) {\n    const j = jogo({ respostas: [resp] }); carregarNucleo(SRC, j);\n    const e = encaixe(j); const d = await e.ler(111);\n    t.verifica(`${nome}: lista vazia e a razão registada`, d.length === 0 && re.test(e.razao()), e.razao());\n  }\n  {\n    const j = jogo({ respostas: [{ corpo: { json: { error: 'Necessita do administrador para aceder às visões gerais' } } }] });\n    carregarNucleo(SRC, j);\n    const e = encaixe(j); await e.ler(111); const r1 = e.razao(); await e.ler(111);\n    t.verifica('o servidor diz que falta o Administrador: diz porquê e não volta a pedir', /falta o Administrador/.test(r1)\n      && j.pedidosVG() === 1, { r1, pedidos: j.pedidosVG() });\n  }\n  t.secao('O PAINEL VAI PARA A JANELA CERTA');\n  {\n    /* Procurava-se a primeira janela com campos de unidades — e uma mensagem\n     * do fórum da aliança com tropa também os tem. Com as duas abertas, o\n     * painel foi parar ao post do fórum (16/09). */\n    const i = SRC.indexOf('A JANELA DE ENVIO, NÃO UMA QUALQUER COM UNIDADES');\n    const bloco = SRC.slice(i, i + 1400);\n    t.verifica('o painel distingue a janela pelo botão de atacar/apoiar', i > 0\n      && /\\^\\(atacar\\|apoiar\\|attack\\|support\\)\\$/.test(bloco));\n    t.verifica('... e escolhe entre todas as janelas abertas',\n      /\\[\\.\\.\\.document\\.querySelectorAll\\('\\.gpwindow_content'\\)\\]\\.find\\(ehJanelaDeEnvio\\)/.test(bloco));\n    t.verifica('o tipo de envio é lido DESSA janela, não da primeira',\n      /const txt = String\\(cont\\.textContent \\|\\| ''\\)\\.toLowerCase\\(\\);/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-equipas.js": "/* AS EQUIPAS DOS COLONIZADORES DISTRIBUEM-SE SOZINHAS.\n *\n * A lista de nomes estava escrita no código — a do Rafa. Quem usasse o Maestro\n * noutro grupo, noutro PC e com outro Firebase, ficava de fora e tinha de\n * configurar conta a conta (17/09).\n *\n * Agora a conta principal do perfil multi divide as contas que a frota conhece\n * e publica. Uma divisão só; quem chegar depois entra na equipa mais pequena,\n * sem mexer em quem já lá está.\n *\n *   node ferramentas/teste-equipas.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('EQUIPAS');\n\nconst AGORA = Math.floor(Date.now() / 1000);\n\nfunction montar(frota, equipas) {\n  const guardado = { valor: equipas };\n  const registo = [];\n  const ctx = {\n    WORLD: 'pt126',\n    uw: {\n      __maestroFb: {\n        url: () => 'https://x',\n        ler: async (c) => (c === 'frota/pt126' ? frota : guardado.valor),\n        escrever: async (c, d) => { guardado.valor = d; },\n      },\n    },\n    log: (m, x) => registo.push(x),\n    seErroDeCodigo: () => {},\n    Date, Object, Number, String, console,\n  };\n  vm.createContext(ctx);\n  const i = SRC.indexOf('  const EQUIPAS_KEY = () =>');\n  const f = SRC.indexOf('\\n  try {\\n    uw.__maestroEquipas', i);\n  const api = vm.runInContext('(() => {\\n' + SRC.slice(i, f)\n    + '\\nreturn { ler: equipasPublicadas, distribuir: distribuirEquipas };\\n})()', ctx);\n  return { api, guardado, registo };\n}\n\nconst conta = (nome, perfil, ha) => ({ conta: nome, perfil, quando: AGORA - (ha || 0) });\n\n(async () => {\n  {\n    /* Quatro multis e uma main: a main fica de fora. */\n    const m = montar({\n      a: conta('Alfa', 'multi'), b: conta('Beta', 'multi'),\n      c: conta('Gama', 'multi'), d: conta('Delta', 'multi'),\n      e: conta('AMain', 'main'),\n    }, null);\n    const r = await m.api.distribuir();\n    t.verifica('divide as multis em duas equipas', Object.keys(r).length === 4, r);\n    const a = Object.values(r).filter((x) => x === 'A').length;\n    const b = Object.values(r).filter((x) => x === 'B').length;\n    t.verifica('... metade para cada', a === 2 && b === 2, { a, b });\n    t.verifica('a main fica de fora', !r.AMain, r);\n  }\n  {\n    /* Já há equipas: quem chega entra na mais pequena, sem mexer no resto. */\n    const m = montar({\n      a: conta('Alfa', 'multi'), b: conta('Beta', 'multi'), c: conta('Novo', 'multi'),\n    }, { Alfa: 'A', Beta: 'A' });\n    const r = await m.api.distribuir();\n    t.verifica('quem já tem equipa fica onde estava', r.Alfa === 'A' && r.Beta === 'A', r);\n    t.verifica('o novo entra na equipa mais pequena', r.Novo === 'B', r);\n  }\n  {\n    /* Uma conta calada mantém o lugar mas não conta para o equilíbrio. */\n    const m = montar({\n      a: conta('Alfa', 'multi'), b: conta('Beta', 'multi', 99999),\n      c: conta('Novo', 'multi'),\n    }, { Alfa: 'A', Beta: 'B' });\n    const r = await m.api.distribuir();\n    t.verifica('a conta calada mantém a equipa', r.Beta === 'B', r);\n    t.verifica('... e o novo vai para a equipa com menos contas VIVAS',\n      r.Novo === 'B', r);\n  }\n  {\n    /* Sem multis vivas, não se inventa nada. */\n    const m = montar({ e: conta('AMain', 'main') }, null);\n    const r = await m.api.distribuir();\n    t.verifica('sem multis, não distribui', r === null, r);\n  }\n  {\n    /* Nada mudou: não se reescreve. */\n    const m = montar({ a: conta('Alfa', 'multi') }, { Alfa: 'A' });\n    const antes = m.guardado.valor;\n    await m.api.distribuir();\n    t.verifica('sem contas novas, não mexe no que está publicado',\n      m.guardado.valor === antes, m.guardado.valor);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-esquiva-margem.js": "/* ESQUIVA — a margem tem de chegar para a preparação.\n *\n * Eram 20 s entre a saída e o impacto. Mas entre o temporizador disparar e a\n * tropa sair passam-se segundos a actualizar contadores, carregar a ilha e\n * fazer os envios: numa cidade com três envios foram 36 s e a tropa saiu\n * DEPOIS do impacto (visto em jogo, 14/09, ataque às 11:17:58).\n *\n *   node ferramentas/teste-esquiva-margem.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('ESQUIVA — MARGEM');\nconst ES = 'function makeEsquivaModule(opts)';\n\nfunction montar(guardado) {\n  const loja = guardado == null ? {} : { grepoEsquiva_preparo_v1: String(guardado) };\n  const ctx = {\n    armazem: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = v; } },\n    seErroDeCodigo: () => {}, console, Number, Math,\n    PREPARO_KEY: 'grepoEsquiva_preparo_v1',\n  };\n  vm.createContext(ctx);\n  const api = vm.runInContext(funcao(SRC, '  function preparoConhecido() {', ES)\n    + funcao(SRC, '  function anotarPreparo(segundos) {', ES)\n    + '\\n({ ler: preparoConhecido, anotar: anotarPreparo })', ctx);\n  return { api, loja };\n}\n\n(async () => {\n  {\n    const m = montar(null);\n    t.verifica('sem histórico: não acrescenta margem nenhuma', m.api.ler() === 0);\n  }\n  {\n    const m = montar(null);\n    m.api.anotar(36);\n    t.verifica('uma esquiva que levou 36 s: passa a contar com 36', m.api.ler() === 36, m.api.ler());\n  }\n  {\n    const m = montar(36);\n    m.api.anotar(50);\n    t.verifica('uma mais lenta: sobe já para 50', m.api.ler() === 50, m.api.ler());\n  }\n  {\n    const m = montar(50);\n    m.api.anotar(10);\n    t.verifica('uma rápida: desce devagar, não confia num arranque bom', m.api.ler() > 30 && m.api.ler() < 50, m.api.ler());\n    for (let i = 0; i < 20; i++) m.api.anotar(10);\n    t.verifica('... mas ao fim de muitas rápidas aproxima-se delas', m.api.ler() <= 12, m.api.ler());\n  }\n  {\n    const m = montar(null);\n    m.api.anotar(600);\n    t.verifica('um caso absurdo fica travado nos 3 min', m.api.ler() === 180, m.api.ler());\n  }\n  {\n    const m = montar(null);\n    m.api.anotar(-5);\n    t.verifica('valor sem sentido não estraga nada', m.api.ler() === 0, m.api.ler());\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-farm-revolta.js": "/* AS CIDADES EM REVOLTA FICAM DE FORA DO FARM DE FAVORES.\n *\n * O farm ataca as multis para gerar favor. Se uma está em revolta, está a\n * receber apoio das outras dezanove — e atacá-la mata essa tropa e os enviados\n * divinos que lá vão (17/09).\n *\n * Sai de fora quem cumpre as DUAS coisas: em revolta E na lista de apoio.\n *\n *   node ferramentas/teste-farm-revolta.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('FARM E REVOLTAS');\n\nconst AGORA = Math.floor(Date.now() / 1000);\n\nfunction montar(lista) {\n  const ctx = {\n    mWorld: 'pt126',\n    mUw: { __maestroFb: { url: () => 'https://x', ler: async () => lista } },\n    seErroDeCodigo: () => {},\n    Date, Number, Object, Set, console,\n  };\n  vm.createContext(ctx);\n  const i = SRC.indexOf('  let emRevoltaEApoiadas = null;');\n  const f = SRC.indexOf('\\n  async function alvosNaIlha', i);\n  return vm.runInContext('(() => {\\n' + SRC.slice(i, f)\n    + '\\nreturn cidadesAPoupar;\\n})()', ctx);\n}\n\n(async () => {\n  {\n    const f = montar({\n      alvos: [500, 600],\n      revoltasAuto: { 500: { ultima: AGORA + 3600 }, 700: { ultima: AGORA + 3600 } },\n    });\n    const r = await f();\n    t.verifica('poupa a cidade em revolta que está na lista', r.has(500), [...r]);\n    t.verifica('... mas não a que está em revolta e não defendo', !r.has(700), [...r]);\n    t.verifica('... nem a que está na lista sem revolta', !r.has(600), [...r]);\n  }\n  {\n    /* Uma revolta que já acabou não conta. */\n    const f = montar({ alvos: [500], revoltasAuto: { 500: { ultima: AGORA - 10 } } });\n    const r = await f();\n    t.verifica('revolta acabada: volta a poder ser atacada', !r.has(500), [...r]);\n  }\n  {\n    const f = montar({});\n    const r = await f();\n    t.verifica('sem revoltas, não se poupa ninguém', r.size === 0);\n  }\n  {\n    /* A leitura vale cinco minutos. */\n    const i = SRC.indexOf('Vale por cinco minutos');\n    t.verifica('a lista não é lida a cada ataque', i > 0\n      && /\\(Date\\.now\\(\\) - emRevoltaLidoEm\\) < 5 \\* 60 \\* 1000/.test(SRC));\n  }\n  {\n    t.verifica('o filtro aplica-se aos alvos da ilha',\n      /\\.filter\\(\\(v\\) => !poupar\\.has\\(Number\\(v\\.id\\)\\)\\);/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-fechar-ilha-mapa.js": "/* FECHAR ILHA — ler a ilha no mapa.\n *\n * A grelha do mapa é de 20: com 10 o servidor devolve outro pedaço e a ilha\n * vinha sem cidade nenhuma — \"20 lugares livres\" numa ilha com 22 cidades\n * (visto em jogo, 12/09, ilha 381:470). E uma leitura falhada não pode contar\n * como ilha vazia. O `estadoDaIlha` REAL.\n *\n *   node ferramentas/teste-fechar-ilha-mapa.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, igual, PEDIR_JOGO } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('FECHAR ILHA — MAPA');\nconst FI = 'function makeFecharIlhaModule(opts)';\n\n/* A ilha 381:470 como o jogo a devolveu: cidades nos lugares 0..20 e 23,\n * mais aldeias sem lugar (nr nulo). Só responde à grelha certa. */\nfunction montar(grelhaBoa, falha) {\n  const pedidos = [];\n  const towns = {};\n  [...Array(21).keys()].concat([23]).forEach((nr, i) => {\n    towns['t' + i] = { x: 381, y: 470, nr, name: 'Cidade ' + nr, player_id: 100 + i, alliance_id: 7 };\n  });\n  for (let i = 0; i < 6; i++) towns['f' + i] = { x: 381, y: 470, nr: null, name: 'Aldeia' };\n  towns['outra'] = { x: 382, y: 470, nr: 3, name: 'De outra ilha' };\n  const mUw = {\n    location: { origin: 'https://pt125.grepolis.com' }, Game: { csrfToken: 'TOK' },\n    fetch: async (url) => {\n      pedidos.push(String(url));\n      if (falha) throw new Error('rede em baixo');\n      const j = JSON.parse(decodeURIComponent((String(url).match(/json=([^&]+)/) || [])[1]));\n      const c = (j.chunks || [])[0] || {};\n      /* O servidor só devolve as cidades quando o bloco é o certo. */\n      const certo = c.x === Math.floor(381 / grelhaBoa) && c.y === Math.floor(470 / grelhaBoa);\n      const corpo = JSON.stringify({ json: { data: { 0: { chunk: c, towns: certo ? towns : {} } } } });\n      return { status: 200, text: async () => corpo, json: async () => JSON.parse(corpo) };\n    },\n  };\n  const ctx = { mUw, LUGARES: 20, seErroDeCodigo: () => {}, console, window: {} };\n  vm.createContext(ctx);\n  const f = vm.runInContext(PEDIR_JOGO + funcao(SRC, '  async function estadoDaIlha(ix, iy, townIdBase) {', FI) + '\\nestadoDaIlha', ctx);\n  return { f, pedidos };\n}\n\n(async () => {\n  {\n    const m = montar(20, false);\n    const r = await m.f(381, 470, 111);\n    t.verifica('pede o bloco da grelha de 20', /%22x%22%3A19/.test(m.pedidos[0]) || /\"x\":19/.test(decodeURIComponent(m.pedidos[0])), m.pedidos[0].slice(0, 120));\n    t.verifica('vê as 22 cidades da ilha (e ignora as de outra ilha)', r.ocupados === 22, r.ocupados);\n    t.verifica('a ilha tem 24 lugares, porque há cidade no 23', r.total === 24, r.total);\n    t.verifica('livres: só o 21 e o 22', igual(r.livres, [21, 22]), r.livres);\n    t.verifica('e diz que leu', r.lido === true);\n  }\n  {\n    const m = montar(10, false);   // se o módulo pedisse com 10, não via nada\n    const r = await m.f(381, 470, 111);\n    t.verifica('com a grelha errada não viria nada — é o erro que isto apanha',\n      r.ocupados === 0 && r.livres.length === 20, { o: r.ocupados, l: r.livres.length });\n  }\n  {\n    const m = montar(20, true);\n    const r = await m.f(381, 470, 111);\n    t.verifica('pedido falhado: diz que NÃO leu (não é ilha vazia)', r.lido === false, r);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-fechar-ilha-vagas.js": "/* FECHAR ILHA — as vagas quem as diz é o jogo.\n *\n * O mapa traz o que a conta viu e não esquece cidades que já lá não estão: na\n * ilha 381:470 dava 22 cidades quando o jogo dizia 9 e 11 vagas (12/09). O\n * `forceUpdate` da colonização devolve `uninhabited_place_count` e propõe um\n * lugar LIVRE, diferente de cada vez. O código REAL.\n *\n *   node ferramentas/teste-fechar-ilha-vagas.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, PEDIR_JOGO } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('FECHAR ILHA — VAGAS');\nconst FI = 'function makeFecharIlhaModule(opts)';\n\n/* A ilha 381:470: 9 cidades, 11 vagas. O jogo propõe os lugares por esta\n * ordem, como fez em jogo (14, 7, 12…). */\nfunction montar(propostas, formato) {\n  const pedidos = [];\n  const mUw = {\n    location: { origin: 'https://pt126.grepolis.com' },\n    Game: { csrfToken: 'TOK', player_id: 2379469 },\n    fetch: async (url, op) => {\n      pedidos.push(JSON.parse(decodeURIComponent(String(op.body).replace('json=', ''))));\n      const lugar = propostas[Math.min(pedidos.length - 1, propostas.length - 1)];\n      const dados = { enough_culture_points: true, target_x: 381, target_y: 470,\n        target_number_on_island: lugar,\n        island_info: { island_id: 55319, uninhabited_place_count: 11,\n          town_list: Array.from({ length: 9 }, (_, i) => ({ id: i, name: 'C' + i })) } };\n      /* O jogo devolve isto de duas maneiras: em models, ou dentro das\n       * notificações, em texto escapado. */\n      /* As três formas vistas em jogo (12/09). */\n      const corpo = formato === 'notificacao'\n        ? JSON.stringify({ json: { t_token: 1, notifications: [{ type: 'backbone',\n          param_str: JSON.stringify({ Colonization: dados }) }] } })\n        : formato === 'notificacao_data'\n          ? JSON.stringify({ json: { t_token: 1, notifications: [\n            { type: 'outra', param_str: '{}' },\n            { type: 'backbone', param_str: JSON.stringify({ Colonization: { data: dados } }) }] } })\n          : JSON.stringify({ json: { models: { Colonization: { data: dados } } } });\n      return { status: 200, text: async () => corpo, json: async () => JSON.parse(corpo) };\n    },\n  };\n  const ctx = { mUw, LUGARES: 20, seErroDeCodigo: () => {}, console, setTimeout, window: {} };\n  vm.createContext(ctx);\n  const txt = PEDIR_JOGO + funcao(SRC, '  async function vagasDaIlha(townId, x, y, lugarSugerido) {', FI)\n    + funcao(SRC, '  async function lugarLivrePorUsar(townId, x, y, jaUsados) {', FI)\n    + '\\n({ vagas: vagasDaIlha, livre: lugarLivrePorUsar })';\n  return { api: vm.runInContext(txt, ctx), pedidos };\n}\n\n(async () => {\n  for (const f of ['models', 'notificacao', 'notificacao_data']) {\n    const m = montar([14], f);\n    const v = await m.api.vagas(111, 381, 470);\n    t.verifica(`resposta em ${f}: 11 vagas, 9 cidades, lugar 14`, v.ok && v.vagas === 11\n      && v.cidades === 9 && v.lugar === 14, v);\n  }\n  {\n    const m = montar([14], 'models');\n    const r = await m.api.livre(111, 381, 470, new Set());\n    t.verifica('nenhum lugar tomado: fica com o que o jogo deu', r.ok && r.lugar === 14\n      && m.pedidos.length === 1, { r, p: m.pedidos.length });\n  }\n  {\n    const m = montar([14, 7, 12], 'models');\n    const r = await m.api.livre(111, 381, 470, new Set([14, 7]));\n    t.verifica('lugares já usados por outras contas: pede outro até dar', r.ok && r.lugar === 12\n      && m.pedidos.length === 3, { r, p: m.pedidos.length });\n  }\n  {\n    const m = montar([14], 'models');\n    const r = await m.api.livre(111, 381, 470, new Set([14]));\n    t.verifica('o jogo insiste no mesmo: desiste e diz quais viu', !r.ok\n      && /só me propôs lugares que outras contas/.test(r.msg), r);\n  }\n  {\n    /* NUNCA se sugere um número: sugerir um ocupado dá \"posição não válida\"\n     * e a conta desistia da ilha (14/09). */\n    const m = montar([14, 7, 12], 'models');\n    await m.api.livre(111, 381, 470, new Set([14, 7]));\n    t.verifica('as tentativas seguintes não sugerem lugar nenhum',\n      m.pedidos.every((p) => !('target_number_on_island' in (p.arguments || {}))),\n      m.pedidos.map((p) => p.arguments));\n  }\n  {\n    const m = montar([14], 'models');\n    const r = await m.api.vagas(111, 381, 470, 9);\n    t.verifica('pode sugerir-se um lugar ao jogo', m.pedidos[0].arguments.target_number_on_island === 9\n      && r.ok, m.pedidos[0].arguments);\n  }\n  {\n    const ctx = { mUw: { location: { origin: 'https://x' }, Game: {},\n      fetch: async () => ({ text: async () => '{\"json\":{\"t_token\":1}}' }) },\n      LUGARES: 20, seErroDeCodigo: () => {}, console, setTimeout, window: {} };\n    vm.createContext(ctx);\n    const f = vm.runInContext(PEDIR_JOGO + funcao(SRC, '  async function vagasDaIlha(townId, x, y, lugarSugerido) {', FI)\n      + '\\nvagasDaIlha', ctx);\n    const v = await f(111, 381, 470);\n    t.verifica('resposta sem a ficha da ilha: diz que não deu (não inventa vagas)', !v.ok, v);\n  }\n  t.secao('O LUGAR 0 É UM LUGAR');\n  {\n    /* Numa ilha vazia o jogo propõe mesmo o número 0 — confirmado com a espia\n     * (15/09: 20 vagas, lugar proposto 0). Cheguei a recusá-lo e a conta\n     * ficava sem fundar. */\n    const m = montar([0], 'models');\n    const v = await m.api.vagas(111, 410, 661);\n    t.verifica('o jogo propõe o lugar 0: aceita-se', v.ok && v.lugar === 0, v);\n    const r = await m.api.livre(111, 410, 661, new Set());\n    t.verifica('... e usa-se para fundar', r.ok && r.lugar === 0, r);\n  }\n  {\n    const m = montar([0], 'models');\n    const r = await m.api.livre(111, 410, 661, new Set([0]));\n    t.verifica('mas se outra conta já o usar, pede-se outro', !r.ok, r);\n  }\n  t.secao('O DONO REPARTE OS LUGARES');\n  {\n    /* Numa ilha VAZIA o jogo propõe sempre o primeiro livre: as vinte contas\n     * recebiam o lugar 0 e ficavam à espera umas das outras (15/09). Mas o\n     * jogo aceita o lugar que se lhe pede — pedi 0, 3, 7 e 19 e devolveu os\n     * mesmos —, por isso o dono volta a repartir. */\n    t.verifica('o plano atribui um lugar a cada conta',\n      /atribuicoes\\[n\\] = \\(i < livres\\.length\\) \\? livres\\[i\\] : -1;/.test(SRC));\n    t.verifica('... a partir dos lugares livres da ilha',\n      /if \\(!ocupados\\.has\\(n2\\)\\) livres\\.push\\(n2\\);/.test(SRC));\n    t.verifica('a conta usa o lugar que lhe deram',\n      /let lugar = Number\\(meuLugar\\);/.test(SRC));\n    t.verifica('... e só pede ao jogo quando não veio nenhum',\n      /if \\(!\\(lugar >= 0\\)\\) \\{/.test(SRC));\n  }\n  t.secao('NINGUÉM PARTE SEM TODOS PODEREM');\n  {\n    /* 17 colonizadores foram para uma ilha que precisava de 20, e três contas\n     * ficaram sem vaga: os 17 ficam lá sem fechar nada (16/09). */\n    const i = SRC.indexOf('NINGUÉM PARTE ENQUANTO TODOS NÃO PUDEREM');\n    const bloco = SRC.slice(i, i + 1600);\n    t.verifica('confirma-se que nenhuma conta do plano está impedida', i > 0\n      && /const impedidas = Object\\.keys\\(plano\\.atribuicoes \\|\\| \\{\\}\\)\\.filter/.test(bloco));\n    t.verifica('... e quem já enviou não conta como impedida',\n      /if \\(plano\\.enviados\\[n2\\]\\) return false;/.test(bloco));\n    t.verifica('... e o plano espera em vez de abortar',\n      /Ninguém parte enquanto todas não puderem/.test(bloco));\n  }\n  {\n    /* Com seis planos na fila, guardam-se seis colonizadores. */\n    const i = SRC.indexOf('UMA VAGA E UM COLONIZADOR POR PLANO EM QUE ESTOU');\n    const bloco = SRC.slice(i, i + 900);\n    t.verifica('a reserva acompanha o número de planos', i > 0\n      && /querNC\\('fecharilha', 60, Math\\.max\\(1, meusPlanos\\)\\)/.test(bloco));\n    t.verifica('... contando só os planos onde esta conta entra',\n      /\\(p2\\.atribuicoes \\|\\| \\{\\}\\)\\[eu\\] !== undefined/.test(bloco));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-fechar-ilha.js": "/* FECHAR ILHA — cada conta escreve só a sua chave.\n *\n * Vinte contas à partida a ler o plano inteiro, mexer na sua parte e gravá-lo\n * inteiro: ganhava a última a gravar. O que cada conta fez (enviei, falhei,\n * desisti, mudei de lugar) vai para a chave dela, e quem lê o plano junta\n * tudo. O código REAL do módulo, com um Firebase de mentira partilhado por\n * várias contas (cada uma com o seu módulo).\n *\n *   node ferramentas/teste-fechar-ilha.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('FECHAR ILHA');\n\n/* Um Firebase de mentira: caminhos com \"/\", cópias à entrada e à saída. */\nfunction firebase() {\n  const raiz = {};\n  const partes = (p) => String(p).split('/').filter(Boolean);\n  const copia = (v) => (v === undefined ? null : JSON.parse(JSON.stringify(v)));\n  return {\n    raiz,\n    url: () => 'https://falso',\n    ler: async (p) => { let n = raiz; for (const k of partes(p)) { if (!n || typeof n !== 'object') return null; n = n[k]; } return copia(n); },\n    escrever: async (p, v) => {\n      const ks = partes(p); let n = raiz;\n      for (const k of ks.slice(0, -1)) { if (!n[k] || typeof n[k] !== 'object') n[k] = {}; n = n[k]; }\n      n[ks[ks.length - 1]] = copia(v); return { ok: true };\n    },\n  };\n}\n\n/* O troço do módulo que lê e grava o plano, para uma conta. */\nfunction conta(fb, nome) {\n  const txt = tira(SRC, '  /* ---------------------- o plano, no Firebase -------------------------- */',\n    '  /* ---------------------- leitura da ilha ------------------------------- */')\n    + '\\n' + tira(SRC, '  const chaveSegura = (ch) =>', ';\\n')\n    + '\\n({ lerPlano, gravarPlano, registarMeu: (p, campos) => registarMeu(p, eu, campos), lerFila, planoActivo })';\n  const ctx = { mWorld: 'pt125', eu: nome, janela: () => ({ __maestroFb: fb }), seErroDeCodigo: () => {}, console };\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx);\n}\n\nconst PLANO = { chave: '365:460', x: 365, y: 460, estado: 'lancar', criadoPor: 'Dono',\n  atribuicoes: { A: 1, B: 2, 'Jo.ao': 3, Dono: 4 }, enviados: { Dono: 100 } };\nasync function montar() {\n  const fb = firebase();\n  await fb.escrever('fecharIlhaFila/pt125', { planos: [JSON.parse(JSON.stringify(PLANO))], parada: false });\n  return fb;\n}\n\n(async () => {\n  {\n    /* A MANEIRA ANTIGA, com o código de agora: ler, mexer, gravar tudo. */\n    const fb = await montar();\n    const a = conta(fb, 'A'); const dono = conta(fb, 'Dono');\n    const pa = await a.lerPlano(); const pd = await dono.lerPlano();\n    pa.enviados.A = 200; await a.gravarPlano(pa);\n    pd.estado = 'feito'; await dono.gravarPlano(pd);\n    const fim = (await fb.ler('fecharIlhaFila/pt125')).planos[0];\n    t.verifica('a maneira antiga perde o envio de uma conta (é por isto que mudou)', !fim.enviados.A, fim.enviados);\n  }\n  {\n    const fb = await montar();\n    const a = conta(fb, 'A'); const dono = conta(fb, 'Dono'); const outra = conta(fb, 'B');\n    const pa = await a.lerPlano(); const pd = await dono.lerPlano();\n    await a.registarMeu(pa, { enviado: 200, lugar: 1 });\n    pd.estado = 'feito'; await dono.gravarPlano(pd);\n    const visto = await outra.lerPlano() || (await outra.lerFila()).planos[0];\n    const fila = (await fb.ler('fecharIlhaFila/pt125')).planos[0];\n    t.verifica('agora: o envio da conta fica, e o estado do dono também', fila.estado === 'feito'\n      && (await fb.ler('fecharIlhaEnvios/pt125/365_460/A')).enviado === 200, { fila, visto });\n  }\n  {\n    /* Ordem inversa: o dono grava primeiro, a conta depois. */\n    const fb = await montar();\n    const a = conta(fb, 'A'); const dono = conta(fb, 'Dono'); const outra = conta(fb, 'B');\n    const pa = await a.lerPlano(); const pd = await dono.lerPlano();\n    pd.estado = 'preparar'; pd.marca = 'do dono'; await dono.gravarPlano(pd);\n    await a.registarMeu(pa, { falhou: 'sem vaga' });\n    const fila = (await fb.ler('fecharIlhaFila/pt125')).planos[0];\n    t.verifica('a conta já não desfaz o que o dono gravou', fila.marca === 'do dono' && fila.estado === 'preparar', fila);\n    const p = await outra.lerPlano();\n    t.verifica('... e quem lê vê a falha da conta', p && p.falhados && p.falhados.A === 'sem vaga', p && p.falhados);\n  }\n  {\n    const fb = await montar();\n    const b = conta(fb, 'B'); const dono = conta(fb, 'Dono');\n    await b.registarMeu(await b.lerPlano(), { falhou: '4 tentativas', lugar: 7 });\n    const pd = await dono.lerPlano();\n    t.verifica('o lugar que a conta usou entra no plano de quem lê', pd.atribuicoes.B === 7, pd.atribuicoes);\n    pd.atribuicoes.C = pd.atribuicoes.B; delete pd.atribuicoes.B; await dono.gravarPlano(pd);\n    const p2 = await dono.lerPlano();\n    t.verifica('se o dono passar o lugar a outra conta, ganha o dono', p2.atribuicoes.B === undefined && p2.atribuicoes.C === 7, p2.atribuicoes);\n  }\n  {\n    const fb = await montar();\n    const a = conta(fb, 'A');\n    const p = await a.lerPlano();\n    await a.registarMeu(p, { tentativas: 2 });\n    await a.registarMeu(p, { enviado: 300 });\n    const rec = await fb.ler('fecharIlhaEnvios/pt125/365_460/A');\n    t.verifica('o registo da conta junta o que já lá estava (tentativas e envio)', rec.tentativas === 2 && rec.enviado === 300, rec);\n  }\n  {\n    const fb = await montar();\n    const j = conta(fb, 'Jo.ao'); const dono = conta(fb, 'Dono');\n    await j.registarMeu(await j.lerPlano(), { enviado: 400 });\n    const pd = await dono.lerPlano();\n    t.verifica('nome com ponto: a chave fica segura e o envio vai para o nome certo', pd.enviados['Jo.ao'] === 400\n      && (await fb.ler('fecharIlhaEnvios/pt125/365_460/Jo_ao')).conta === 'Jo.ao', pd.enviados);\n  }\n  /* A FILA LIMPA TEM DE FICAR LIMPA. */\n  {\n    const fb = firebase();\n    /* Como o Firebase faz: uma lista vazia não se guarda. */\n    const escreverReal = fb.escrever;\n    fb.escrever = async (p, v) => {\n      const c = JSON.parse(JSON.stringify(v || {}));\n      if (c && Array.isArray(c.planos) && !c.planos.length) delete c.planos;\n      return escreverReal(p, c);\n    };\n    await fb.escrever('fecharIlha/pt125', { chave: '100:100', atribuicoes: { A: 0 }, estado: 'preparar' });\n    const c = conta(fb, 'A');\n    const antes = await c.lerFila();\n    t.verifica('sem fila nenhuma: aproveita o plano do formato antigo', antes.planos.length === 1, antes);\n    await fb.escrever('fecharIlhaFila/pt125', { planos: [], parada: false });\n    const dep = await c.lerFila();\n    t.verifica('fila gravada vazia: fica vazia (não ressuscita o plano antigo)', dep.planos.length === 0, dep);\n  }\n  /* UMA DESISTÊNCIA POR TENTATIVAS CADUCA. */\n  {\n    const fb = await montar();\n    const a = conta(fb, 'A');\n    const p = await a.lerPlano();\n    await a.registarMeu(p, { falhou: '4 tentativas sem sucesso (posição não válida)', tentativas: 4 });\n    const p2 = await a.lerPlano();\n    t.verifica('a falha fica registada', p2.falhados.A === '4 tentativas sem sucesso (posição não válida)', p2.falhados);\n    await a.registarMeu(p2, { falhou: '', tentativas: 0 });\n    const p3 = await a.lerPlano();\n    t.verifica('uma falha vazia apaga a desistência', !p3.falhados || !p3.falhados.A, p3.falhados);\n    t.verifica('... e o registo da conta continua lá para o resto',\n      !!(await fb.ler('fecharIlhaEnvios/pt125/365_460/A')), await fb.ler('fecharIlhaEnvios/pt125/365_460/A'));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-feiticos-purificar.js": "/* FEITIÇOS — purificar antes de repetir, sem deitar fora o que é meu.\n *\n * A Ira de Zeus falhou num ataque que já tinha feitiço e o jogo respondeu\n * \"Ocorreu um erro interno!\" — sem dizer porquê (visto em jogo, 15/09). A\n * purificação resolve, e é barata ao lado do que a Ira faz.\n *\n * Mas a purificação limpa os feitiços ACTIVOS, sejam de quem forem: se já lá\n * estiver um dos meus que fica activo — a Saudade, por exemplo — purificar\n * seria deitá-lo fora. A Ira e a tempestade não ficam activas (confirmado\n * contigo, 15/09).\n *\n *   node ferramentas/teste-feiticos-purificar.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('FEITIÇOS — PURIFICAR');\nconst FE = 'function makeFeiticosModule(opts)';\n\nfunction api() {\n  const ctx = { console, String, Number, Object };\n  vm.createContext(ctx);\n  const i = SRC.indexOf('  const FICAM_ACTIVOS = [');\n  const f = SRC.indexOf('\\n  function nomeDoFeitico(id) {', i);\n  return vm.runInContext('(() => {\\n' + SRC.slice(i, f)\n    + '\\nreturn { fica: feiticoFicaActivo, lista: FICAM_ACTIVOS };\\n})()', ctx);\n}\n\n(async () => {\n  const a = api();\n  {\n    /* Os oito que ficam activos, pelos nomes que o jogo usa. */\n    for (const [id, nome] of [\n      ['ares_army', 'Exército de Ares'], ['bloodlust', 'Sede de Sangue'],\n      ['fair_wind', 'Vento favorável'], ['desire', 'Saudade'],\n      ['strength_of_heroes', 'Poder heroico'], ['resurrection', 'Retorno do mundo dos mortos'],\n      ['cap_of_invisibility', 'Elmo da invisibilidade'], ['effort_of_the_huntress', 'Alvo da caçadora'],\n    ]) {\n      t.verifica(`${nome} fica activo`, a.fica(id) === true, id);\n    }\n  }\n  {\n    t.verifica('a Ira de Zeus NÃO fica activa', a.fica('transformation') === false);\n    t.verifica('a tempestade no mar também não', a.fica('sea_storm') === false);\n    t.verifica('a purificação não conta', a.fica('cleanse') === false);\n  }\n  {\n    /* O \"erro interno\" passa a contar como ocupado — é o que o jogo\n     * respondeu. */\n    const ctx = { console };\n    vm.createContext(ctx);\n    const i = SRC.indexOf(\"        ocupado: /j[áa] foi lan[çc]ado\");\n    const bloco = SRC.slice(i, i + 220);\n    /* Cheguei a pôr o \"erro interno\" como alvo ocupado, e estava errado:\n     * purificou-se, o alvo estava limpo, e a Ira falhou na mesma. Era o\n     * identificador do comando (15/09). */\n    t.verifica('\"erro interno\" NÃO conta como ocupado', !/erro interno/.test(bloco), bloco.slice(0, 120));\n  }\n  {\n    t.verifica('não se purifica por cima de um feitiço meu',\n      /não purifico para não o deitar fora/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-fundacao-mapa.js": "/* FUNDAÇÃO — procurar ilhas sem levar 429.\n *\n * A procura pedia um bloco do mapa de cada vez, em rajada: ao guardar a\n * configuração saíram dezenas de pedidos seguidos, o servidor respondeu 429 a\n * quase todos, e cada 429 pára o maestro dois minutos (visto em jogo, 14/09:\n * 40 erros em segundos). O `get_chunks` aceita uma lista. O `pedirBlocos` REAL.\n *\n *   node ferramentas/teste-fundacao-mapa.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, PEDIR_JOGO } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('FUNDAÇÃO — MAPA');\nconst FU = 'function makeFundacaoModule(opts)';\n\nfunction montar(travadoAoFim) {\n  const pedidos = [];\n  let travado = false;\n  const ctx = {\n    mUw: {\n      location: { origin: 'https://pt125.grepolis.com' }, Game: { csrfToken: 'TOK' },\n      ITowns: { towns: { 111: {} } },\n      fetch: async (url) => {\n        const j = JSON.parse(decodeURIComponent((String(url).match(/json=([^&]+)/) || [])[1]));\n        pedidos.push(j.chunks.length);\n        if (travadoAoFim && pedidos.length >= travadoAoFim) travado = true;\n        const data = {};\n        j.chunks.forEach((c, i) => { data[i] = { chunk: c, islands: [{ x: c.x * 20, y: c.y * 20, id: 1 }] }; });\n        const corpo = JSON.stringify({ json: { data } });\n        return { status: 200, text: async () => corpo, json: async () => JSON.parse(corpo) };\n      },\n    },\n    window: { __maestroServidorTravado: () => travado },\n    lerResposta: async (r) => JSON.parse(await r.text()),\n    seErroDeCodigo: () => {}, console, setTimeout,\n  };\n  vm.createContext(ctx);\n  const f = vm.runInContext(PEDIR_JOGO + funcao(SRC, '  function servidorTravadoAgora() {', FU)\n    + funcao(SRC, '  async function pedirBlocos(lista, townIdBase) {', FU) + '\\npedirBlocos', ctx);\n  return { f, pedidos };\n}\n\nconst blocos = (n) => Array.from({ length: n }, (_, i) => ({ x: i, y: i }));\n\n(async () => {\n  {\n    const m = montar(0);\n    const r = await m.f(blocos(25), 111);\n    t.verifica('25 blocos → 5 pedidos de 6, não 25', m.pedidos.length === 5, m.pedidos);\n    t.verifica('... e devolve os 25 blocos', r.length === 25, r.length);\n  }\n  {\n    const m = montar(0);\n    await m.f(blocos(4), 111);\n    t.verifica('poucos blocos: um pedido só', m.pedidos.length === 1 && m.pedidos[0] === 4, m.pedidos);\n  }\n  {\n    /* O servidor começa a recusar ao segundo pedido. */\n    const m = montar(2);\n    const r = await m.f(blocos(30), 111);\n    t.verifica('servidor a recusar: pára em vez de insistir', m.pedidos.length === 2, m.pedidos.length);\n    t.verifica('... e devolve o que já tinha', r.length === 12, r.length);\n  }\n  {\n    const m = montar(0);\n    const r = await m.f([], 111);\n    t.verifica('nada a pedir: nenhum pedido', m.pedidos.length === 0 && r.length === 0);\n  }\n  /* A PROCURA TEM DE PODER IR MAIS LONGE. */\n  {\n    const pedidos = [];\n    const ctx = {\n      mUw: { location: { origin: 'https://x' }, Game: { csrfToken: 'T' }, ITowns: { towns: { 111: {} } },\n        fetch: async (url) => {\n          const j = JSON.parse(decodeURIComponent((String(url).match(/json=([^&]+)/) || [])[1]));\n          j.chunks.forEach((c) => pedidos.push(`${c.x}:${c.y}`));\n          const data = {};\n          /* Só há ilhas a partir do anel 5 — perto do centro está tudo tomado. */\n          j.chunks.forEach((c, i) => {\n            const anel = Math.max(Math.abs(c.x - 10), Math.abs(c.y - 10));\n            data[i] = { islands: anel >= 5 ? [{ x: c.x * 20, y: c.y * 20, id: anel }] : [] };\n          });\n          const corpo = JSON.stringify({ json: { data } });\n          return { status: 200, text: async () => corpo, json: async () => JSON.parse(corpo) };\n        } },\n      window: { __maestroServidorTravado: () => false },\n      lerResposta: async (r) => JSON.parse(await r.text()),\n      CHUNK: 20, oceanoDe: () => 55, seErroDeCodigo: () => {}, console, setTimeout,\n    };\n    vm.createContext(ctx);\n    const f = vm.runInContext(PEDIR_JOGO + funcao(SRC, '  function servidorTravadoAgora() {', FU)\n      + funcao(SRC, '  async function pedirBlocos(lista, townIdBase) {', FU)\n      + funcao(SRC, '  async function ilhasPertoDe(centro, oceanos, townIdBase, minimo, anelDe, anelAte) {', FU)\n      + '\\nilhasPertoDe', ctx);\n    const centro = { x: 200, y: 200 };\n    const perto = await f(centro, [], 111, 24, 1, 4);\n    t.verifica('até ao anel 4 não há nada (é o caso de 14/09)', perto.length === 0, perto.length);\n    const longe = await f(centro, [], 111, 24, 5, 8);\n    t.verifica('do anel 5 ao 8 já aparecem ilhas', longe.length > 0, longe.length);\n    t.verifica('... e não se repetem blocos dentro do mesmo degrau',\n      new Set(pedidos).size === pedidos.length, { pedidos: pedidos.length, únicos: new Set(pedidos).size });\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-interacoes-novas.js": "/* AS PEÇAS NOVAS NÃO SE ESTRAGAM UMAS ÀS OUTRAS.\n *\n * Num dia entraram o broker, a ligação aberta, o partir cercos e o reforço\n * partilhado — e várias mexem no mesmo sítio. Este ficheiro guarda as três\n * interacções que estavam erradas quando se foi ver (18/09).\n *\n *   node ferramentas/teste-interacoes-novas.js maestro.user.js\n */\nconst S = require('./simulador');\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('INTERACÇÕES');\n\n(async () => {\n  t.secao('O BROKER E O ENCAIXE');\n  {\n    /* O broker impõe uma pausa entre pedidos — é o que evita as rajadas. Mas\n     * o Encaixe existe para acertar ao segundo: um envio que espera 600 ms na\n     * fila chega tarde e o trabalho todo dele fica perdido. */\n    t.verifica('há uma via sem fila para quem acerta ao segundo',\n      /O QUE ACERTA AO SEGUNDO NÃO ESPERA/.test(SRC)\n      && /if \\(prioridade === -1\\) \\{/.test(SRC));\n    t.verifica('... e o encaixe usa-a',\n      /if \\(p\\) return p\\(url, opcoes, -1\\);/.test(SRC));\n    t.verifica('a via sem fila não espera nem verifica a pausa',\n      /pedidosEstado\\.feitos\\+\\+;\\s*\\n\\s*ultimoPedidoEm = Date\\.now\\(\\);\\s*\\n\\s*try \\{ return uw\\.fetch/.test(SRC));\n    t.verifica('e é a ÚNICA excepção — mais ninguém usa a prioridade -1',\n      (SRC.match(/, -1\\);/g) || []).length === 1,\n      (SRC.match(/, -1\\);/g) || []).length + ' sítios');\n  }\n\n  t.secao('O REFORÇO E O PARTIR CERCOS');\n  {\n    /* Os dois reagiam ao mesmo colonizador: o reforço enchia a cidade de\n     * tropa e o partir cercos mandava as vinte contas atacá-la. Ou a defesa\n     * aguentava e os faróis batiam na tropa que acabámos de lá pôr, ou caía e\n     * perdeu-se tropa a mais. */\n    t.verifica('num mundo de cerco, o reforço não trata de colonizadores',\n      /NUM MUNDO DE CERCO, UM COLONIZADOR É OUTRO CASO/.test(SRC)\n      && /ataques = ataques\\.filter\\(\\(x\\) => !\\/takeover\\/i\\.test\\(String\\(x\\.tipo \\|\\| x\\.type \\|\\| ''\\)\\)\\);/.test(SRC));\n    t.verifica('... e diz porquê no registo',\n      /ficam para o \"Partir cercos\"/.test(SRC));\n    t.verifica('o tipo do ataque é guardado, senão não havia como distinguir',\n      /tipo: String\\(x\\.type \\|\\| ''\\)/.test(SRC));\n    t.verifica('... também no caminho sem Administrador',\n      /out\\.set\\(chaveDe\\(0, alvo, chega\\), \\{ alvo, chega, tipo, semHora: !chega \\}\\);/.test(SRC));\n    t.verifica('e nos mundos de revolta nada disto se aplica',\n      /Nos mundos de revolta isto não se aplica/.test(SRC));\n  }\n\n  t.secao('A LIGAÇÃO ABERTA E O TIPO DO MUNDO');\n  {\n    /* Há uma ligação por conta. Nos mundos de cerco ficava presa à lista do\n     * apoio, que lá nem corre. */\n    t.verifica('a ligação vai para o que aquele mundo usa',\n      /const caminho = deCerco \\? `cercos\\/\\$\\{WORLD\\}` : `apoio\\/\\$\\{WORLD\\}`;/.test(SRC));\n    t.verifica('... e acorda o módulo certo de cada lado',\n      /if \\(deCerco\\) \\{\\s*\\n\\s*acordar\\('partircerco', 0\\);/.test(SRC));\n  }\n\n  t.secao('O QUE JÁ ESTAVA CERTO');\n  {\n    t.verifica('o apoio e o partir cercos nunca correm no mesmo mundo',\n      /tipoDeMundo: 'revolta',/.test(SRC) && /tipoDeMundo: 'cerco',/.test(SRC));\n    t.verifica('o vigia acorda o partir cercos só com colonizadores',\n      /if \\(novos\\.some\\(\\(a\\) => \\/takeover\\/i\\.test\\(String\\(a\\.type \\|\\| ''\\)\\)\\)\\) \\{/.test(SRC));\n    t.verifica('e o reforço partilhado manda apoio, não ataque',\n      /tipo: 'support',/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-leitores.js": "/* FEITIÇOS, DEUSES, REFORÇO — a visão geral pelo leitor do núcleo.\n *\n * O que tem de ser: a lista certa das duas chaves; \"não consegui ler\" nunca é\n * \"não há nada\" (o reforço não traz tropa às cegas, o farm não ataca sem saber\n * o favor a caminho); sem Administrador não se pede; os três juntos fazem um\n * pedido só.\n *\n *   node ferramentas/teste-leitores.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { AGORA_S, vm, tira, funcao, jogo, carregarNucleo, semAdministrador, correr, ligar, lista, ERRO, LIMITADO,\n  igual, PEDIR_JOGO } = S;\nconst SRC = S.ficheiroDoMaestro();\n\nconst t = S.verificador('FEITIÇOS, DEUSES, REFORÇO');\n\nconst COMANDOS = [\n  { id: 1, type: 'attack', origin_town_id: 900, origin_town_name: 'Inimiga', destination_town_id: 111,\n    destination_town_name: 'A', arrival_at: AGORA_S + 3600 },\n  { id: 2, type: 'attack', origin_town_id: 901, destination_town_id: 222, arrival_at: AGORA_S + 7200 },\n  { id: 3, type: 'attack', return: true, origin_town_id: 902, destination_town_id: 111, arrival_at: AGORA_S + 60 },\n  { id: 4, type: 'attack', origin_town_id: 333, destination_town_id: 111, arrival_at: AGORA_S + 100 },\n  { id: 5, type: 'support', origin_town_id: 903, destination_town_id: 111, arrival_at: AGORA_S + 50 },\n  { id: 6, type: 'attack', origin_town_id: 904, destination_town_id: 555, arrival_at: AGORA_S + 50 },\n  { id: 7, type: 'attack', origin_town_id: 111, destination_town_id: 700, godsent: 10, arrival_at: AGORA_S + 900 },\n  { id: 8, type: 'attack', origin_town_id: 222, destination_town_id: 701, godsent: 4, cmd_return: true, arrival_at: AGORA_S + 900 },\n  { id: 9, type: 'attack', origin_town_id: 950, destination_town_id: 702, godsent: 20, arrival_at: AGORA_S + 900 },\n];\nconst MOVIMENTOS = {\n  m1: { attributes: { id: 50, type: 'attack', target_town_id: 222, home_town_id: 905, town_name_origin: 'SóModelo',\n    town_name_destination: 'B', arrival_at: AGORA_S + 500 } },\n  m2: { attributes: { id: 51, type: 'attack', target_town_id: 111, home_town_id: 900, town_name_origin: 'Inimiga',\n    town_name_destination: 'A', arrival_at: AGORA_S + 3600 } },\n};\n\nasync function feiticos(j) {\n  const txt = funcao(SRC, '  async function ataquesContraMim() {\\n    /* SEM REPETIDOS');\n  const ctx = { mUw: j.win, window: j.win, seErroDeCodigo: () => {},\n    armazem: { getItem: (k) => (k === 'grepoEsquiva_cidadesGrupo_v1' ? JSON.stringify({ ids: [333] }) : null) } };\n  vm.createContext(ctx);\n  const f = vm.runInContext(PEDIR_JOGO + \"let razaoVisaoGeral = '';\\n\" + txt + '\\n({ f: ataquesContraMim, razao: () => razaoVisaoGeral })', ctx);\n  return { lista: await f.f(), razao: f.razao() };\n}\n\nasync function reforco(j, passagens) {\n  const ctx = { window: j.win, localStorage: j.localStorage, seErroDeCodigo: () => {}, console };\n  vm.createContext(ctx);\n  const mod = vm.runInContext(S.fabrica(SRC, 'makeReforcoModule') + '\\nmakeReforcoModule({ intervaloMin: 2 })', ctx);\n  const reg = { ecra: [], rotina: [] };\n  const c = { uw: j.win, log: (m) => reg.ecra.push(m), logRotina: (m) => reg.rotina.push(m),\n    sleep: async () => {}, rand: () => 0, getMyTowns: () => [{ id: 111 }, { id: 222 }] };\n  for (let i = 0; i < (passagens || 1); i++) await mod.run(c);\n  return reg;\n}\nconst reforcoLigado = (j) => {\n  j.localStorage.setItem('grepoReforco_cfg_v1', JSON.stringify({ ativo: true }));\n  j.localStorage.setItem('grepoReforco_envios_v1', JSON.stringify({\n    k1: { origem: 111, destino: 222, impacto: AGORA_S - 600, carga: { sword: 100 } } }));\n};\nconst BLOCO = { u1: { attributes: { id: 4242, home_town_id: 111, current_town_id: 222, sword: 100 } } };\nconst sendBacks = (j) => j.pedidos.filter((u) => /send_back/.test(u)).length;\n\nasync function deuses(j) {\n  const chamadas = { emCasa: 0 };\n  const ctx = { mUw: j.win, window: j.win, localStorage: j.localStorage, seErroDeCodigo: () => {},\n    favorPorDeus: () => ({ zeus: 10 }), deusDa: (id) => ({ 111: 'zeus', 222: 'zeus' }[id] || null),\n    pedidoDe: () => null, NOMES: { zeus: 'Zeus' }, chavePorPerfil: (k) => k,\n    enviadosEmCasa: () => { chamadas.emCasa++; return 0; },\n    escudoDisponivel: () => 0, alvosNaIlha: async () => [], proximoAlvo: () => null,\n    enviarAtaque: async () => ({ ok: true }), ilhaDa: () => ({ x: 1, y: 1 }),\n    minimoAprendido: () => 0, anotarMinimo: () => {}, recusaNormal: () => false, firebaseUrl: () => '' };\n  vm.createContext(ctx);\n  const f = vm.runInContext('let farmFalhasVisao = 0;\\n' + funcao(SRC, '  async function farmarFavor(ctx, c, towns) {')\n    + '\\nfarmarFavor', ctx);\n  const reg = { ecra: [], rotina: [] };\n  await f({ log: (m) => reg.ecra.push(m), logRotina: (m) => reg.rotina.push(m),\n    getMyTowns: () => [{ id: 111 }, { id: 222 }], sleep: async () => {}, rand: () => 0 },\n  { multis: ['multi1'], cidadesFarm: { 111: true }, favorParaAtacar: 100, favorPorEnviado: 5 }, [{ id: 111, name: 'A' }]);\n  return { reg, chamadas };\n}\n\n(async () => {\n  t.secao('FEITIÇOS — lista do painel');\n  for (const [nome, resp] of [['json.data.commands', lista(COMANDOS)], ['json.commands', { corpo: { json: { commands: COMANDOS } } }]]) {\n    const j = jogo({ respostas: [resp], movimentos: MOVIMENTOS }); carregarNucleo(SRC, j);\n    const r = await feiticos(j);\n    /* O identificador do SERVIDOR manda: é o único que o `cast` dos feitiços\n     * aceita. O dos modelos (números enormes) dá \"erro interno\" (15/09). */\n    t.verifica(`${nome}: 3 ataques contra mim, sem repetidos nem os do meu grupo`,\n      r.lista.length === 3 && r.razao === '', r);\n    t.verifica(`${nome}: o comando que veio das duas fontes fica com o id do servidor`,\n      r.lista.some((x) => x.cid === 1 && x.doServidor === true), r.lista.map((x) => x.cid));\n    t.verifica(`${nome}: o que só os modelos têm fica marcado como sem id do servidor`,\n      r.lista.some((x) => x.cid === 50 && x.doServidor === false), r.lista);\n  }\n  {\n    const j = jogo({ respostas: [ERRO], movimentos: MOVIMENTOS }); carregarNucleo(SRC, j);\n    const r = await feiticos(j);\n    t.verifica('leitura falhada: ficam os dos modelos, e a razão para o painel', r.lista.length === 2\n      && r.razao === 'Ocorreu um erro.', r);\n  }\n  {\n    const j = jogo({ respostas: [lista(COMANDOS)], movimentos: MOVIMENTOS, semAdm: true }); carregarNucleo(SRC, j);\n    const r = await feiticos(j);\n    t.verifica('sem Administrador: nenhum pedido, ficam os modelos', j.pedidosVG() === 0 && r.lista.length === 2\n      && r.razao === 'sem Administrador', r);\n  }\n\n  t.secao('REFORÇO');\n  {\n    const j = jogo({ respostas: [lista(COMANDOS)], units: BLOCO }); carregarNucleo(SRC, j); reforcoLigado(j);\n    const r = await reforco(j);\n    t.verifica('há outro ataque à cidade: a tropa fica', sendBacks(j) === 0\n      && r.rotina.some((m) => /a tropa fica em 222/.test(m)), r);\n  }\n  {\n    const j = jogo({ respostas: [lista(COMANDOS.filter((x) => x.destination_town_id !== 222))], units: BLOCO });\n    carregarNucleo(SRC, j); reforcoLigado(j);\n    const r = await reforco(j);\n    t.verifica('acabaram os ataques: traz a tropa de volta', sendBacks(j) === 1\n      && r.ecra.some((m) => /acabaram os ataques/.test(m)), r);\n    t.verifica('... e o envio de volta esquece a cópia da visão geral',\n      j.win.__maestroVisaoGeralEstado().copia === 'nenhuma', j.win.__maestroVisaoGeralEstado());\n  }\n  {\n    const j = jogo({ respostas: [ERRO], units: BLOCO }); carregarNucleo(SRC, j); reforcoLigado(j);\n    const r = await reforco(j, 3);\n    t.verifica('leitura falhada: não traz nada', sendBacks(j) === 0, r);\n    t.verifica('... avisa no ecrã uma vez, com a razão', r.ecra.length === 1\n      && /não consegui ler a visão geral \\(Ocorreu um erro\\.\\)/.test(r.ecra[0]), r.ecra);\n    t.verifica('... as repetições vão para a rotina', r.rotina.filter((m) => /não consegui ler/.test(m)).length === 2, r.rotina);\n    t.verifica('... e o registo do envio fica', !!JSON.parse(j.localStorage.getItem('grepoReforco_envios_v1')).k1);\n  }\n  {\n    /* SEM ADMINISTRADOR não há visão geral — mas a página diz quais das\n     * minhas cidades têm ataques a chegar, e isso chega para reforçar. */\n    const j = jogo({ respostas: [lista(COMANDOS)], units: BLOCO, semAdm: true }); carregarNucleo(SRC, j); reforcoLigado(j);\n    const r = await reforco(j);\n    /* Sem Administrador não se pede a visão geral; a recolha passa a\n     * cumprir-se pela hora marcada no envio (7400). */\n    t.verifica('sem Administrador: não pede a visão geral', j.pedidosVG() === 0, j.pedidosVG());\n    t.verifica('... e a tropa cuja hora já passou volta para casa',\n      sendBacks(j) === 1, { sb: sendBacks(j), r });\n  }\n  {\n    const j = jogo({ respostas: [lista(COMANDOS)], units: BLOCO, semAdm: true,\n      attack: [{ town_id: 222, incoming: 1 }] });\n    carregarNucleo(SRC, j); reforcoLigado(j);\n    const r = await reforco(j);\n    t.verifica('sem Administrador, com a página a marcar um ataque: já trabalha',\n      j.pedidosVG() === 0 && r.rotina.concat(r.ecra).some((m) => /sem Administrador/.test(m)),\n      { rotina: r.rotina, ecra: r.ecra });\n  }\n\n  t.secao('DEUSES — favor que vem a caminho');\n  {\n    const j = jogo({ respostas: [lista(COMANDOS)] }); carregarNucleo(SRC, j);\n    const r = await deuses(j);\n    t.verifica('conta só os enviados que vão (Zeus +50) e segue para os ataques',\n      r.reg.rotina.includes('Farm: já vem a caminho Zeus +50.') && r.chamadas.emCasa === 1, r);\n  }\n  {\n    const j = jogo({ respostas: [ERRO] }); carregarNucleo(SRC, j);\n    const r = await deuses(j);\n    t.verifica('leitura falhada: não ataca, e diz porquê', r.chamadas.emCasa === 0\n      && /não consegui ler a visão geral \\(Ocorreu um erro\\.\\)/.test(r.reg.ecra[0] || ''), r);\n  }\n  {\n    const j = jogo({ respostas: [lista(COMANDOS)], semAdm: true }); carregarNucleo(SRC, j);\n    const r = await deuses(j);\n    t.verifica('sem Administrador: fica como sempre (ataca), sem pedido', r.chamadas.emCasa === 1 && j.pedidosVG() === 0, r);\n  }\n\n  t.secao('OS TRÊS JUNTOS');\n  {\n    const j = jogo({ respostas: [lista(COMANDOS)], movimentos: MOVIMENTOS }); carregarNucleo(SRC, j);\n    await deuses(j); await feiticos(j);\n    j.localStorage.setItem('grepoReforco_cfg_v1', JSON.stringify({ ativo: true }));\n    await reforco(j);\n    t.verifica('deuses + feitiços + reforço seguidos → 1 pedido à visão geral', j.pedidosVG() === 1, j.pedidosVG());\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-ligacao-aberta.js": "/* LIGAÇÃO ABERTA AO FIREBASE.\n *\n * Uma conta só sabia de uma mudança quando ia perguntar — na passagem do\n * módulo, até dois minutos depois. O Firebase sabe avisar: mantém uma ligação\n * aberta e manda o que mudou (18/09).\n *\n * A ligação NÃO substitui a leitura: só diz \"há coisa nova\", e quem recebe vai\n * ler como sempre. Se falhar ou repetir, o pior que acontece é uma leitura a\n * mais.\n *\n *   node ferramentas/teste-ligacao-aberta.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('LIGAÇÃO ABERTA');\n\n/* Um EventSource de mentira, para se poder provocar tudo. */\nfunction fazerEventSource(registo) {\n  return class {\n    constructor(url) {\n      this.url = url;\n      this.ouvintes = {};\n      registo.abertas.push(url);\n      this.fechado = false;\n    }\n    addEventListener(nome, fn) { (this.ouvintes[nome] = this.ouvintes[nome] || []).push(fn); }\n    close() { this.fechado = true; registo.fechadas.push(this.url); }\n    /* provocar */\n    disparar(nome, dados) {\n      for (const fn of (this.ouvintes[nome] || [])) fn({ data: JSON.stringify(dados) });\n    }\n    erro() { if (this.onerror) this.onerror(); }\n    aberta() { if (this.onopen) this.onopen(); }\n  };\n}\n\nfunction montar(comEventSource) {\n  const registo = { abertas: [], fechadas: [], log: [] };\n  const criadas = [];\n  const ES = fazerEventSource(registo);\n  const ctx = {\n    uw: comEventSource\n      ? { EventSource: function (u) { const e = new ES(u); criadas.push(e); return e; } }\n      : {},\n    firebaseUrl: () => 'https://x.firebasedatabase.app',\n    log: (m, x) => registo.log.push(x),\n    seErroDeCodigo: () => {},\n    Date, Map, Object, String, JSON, console,\n  };\n  if (comEventSource) ctx.uw.EventSource.prototype = ES.prototype;\n  vm.createContext(ctx);\n  const i = SRC.indexOf('  const LIGACOES_MAX = 1;');\n  const f = SRC.indexOf('\\n  try {\\n    uw.__maestroLigacao', i);\n  const api = vm.runInContext('(() => {\\n' + SRC.slice(i, f)\n    + '\\nreturn { abrir: ligacaoAberta, fechar: fecharLigacoes, estado: () => ligacoesEstado };\\n})()', ctx);\n  return { api, registo, criadas };\n}\n\n(async () => {\n  t.secao('ABRIR');\n  {\n    const m = montar(true);\n    const avisos = [];\n    const r = m.api.abrir('apoio/pt126', (x) => avisos.push(x));\n    t.verifica('abre a ligação ao caminho certo',\n      m.registo.abertas[0] === 'https://x.firebasedatabase.app/apoio/pt126.json', m.registo.abertas);\n    t.verifica('e devolve o estado', !!r);\n  }\n  {\n    const m = montar(false);\n    t.verifica('sem EventSource no navegador, não rebenta',\n      m.api.abrir('apoio/pt126', () => {}) === null);\n  }\n  {\n    const m = montar(true);\n    m.api.abrir('a', () => {});\n    const segunda = m.api.abrir('b', () => {});\n    t.verifica('respeita o limite de ligações', segunda === null, m.registo.abertas);\n    t.verifica('... e diz porquê', m.registo.log.some((x) => /limite/.test(x)), m.registo.log);\n  }\n  {\n    const m = montar(true);\n    m.api.abrir('a', () => {});\n    const outra = m.api.abrir('a', () => {});\n    t.verifica('não abre duas vezes o mesmo caminho', m.registo.abertas.length === 1);\n  }\n\n  t.secao('RECEBER');\n  {\n    const m = montar(true);\n    const avisos = [];\n    m.api.abrir('apoio/pt126', (x) => avisos.push(x));\n    const es = m.criadas[0];\n\n    /* A primeira mensagem é o estado actual, não uma mudança. */\n    es.disparar('put', { path: '/', data: { alvos: [1, 2] } });\n    t.verifica('a primeira mensagem não conta como mudança', avisos.length === 0, avisos);\n\n    es.disparar('put', { path: '/alvos', data: [1, 2, 3] });\n    t.verifica('a segunda já avisa', avisos.length === 1, avisos);\n    t.verifica('... e diz o caminho e o tipo',\n      avisos[0].tipo === 'put' && avisos[0].caminho === '/alvos', avisos[0]);\n\n    es.disparar('patch', { path: '/x', data: { y: 1 } });\n    t.verifica('também avisa nas alterações parciais', avisos.length === 2, avisos);\n  }\n  {\n    const m = montar(true);\n    const avisos = [];\n    m.api.abrir('a', (x) => avisos.push(x));\n    const es = m.criadas[0];\n    es.disparar('put', { path: '/', data: null });\n    es.disparar('keep-alive', {});\n    t.verifica('o keep-alive não avisa ninguém', avisos.length === 0);\n  }\n  {\n    const m = montar(true);\n    const avisos = [];\n    m.api.abrir('a', (x) => avisos.push(x));\n    const es = m.criadas[0];\n    es.disparar('put', { path: '/', data: null });\n    for (const fn of (es.ouvintes.put || [])) fn({ data: 'isto não é json' });\n    t.verifica('uma mensagem estragada não rebenta nem avisa', avisos.length === 0);\n  }\n\n  t.secao('QUANDO CORRE MAL');\n  {\n    const m = montar(true);\n    m.api.abrir('a', () => {});\n    const es = m.criadas[0];\n    for (let i = 0; i < 9; i++) es.erro();\n    t.verifica('aguenta falhas sem desistir', !es.fechado, m.api.estado());\n    es.erro();\n    t.verifica('ao fim de dez desiste', es.fechado, m.api.estado());\n    t.verifica('... e diz que continua a ler como antes',\n      m.registo.log.some((x) => /continua a ler como antes/.test(x)), m.registo.log);\n  }\n  {\n    const m = montar(true);\n    m.api.abrir('a', () => {});\n    const es = m.criadas[0];\n    es.disparar('cancel', {});\n    t.verifica('se o servidor cancelar, fecha-se', es.fechado);\n    t.verifica('... e deixa de contar como aberta', m.api.estado().abertas === 0, m.api.estado());\n  }\n  {\n    const m = montar(true);\n    m.api.abrir('a', () => {});\n    m.api.fechar();\n    t.verifica('o fechar fecha tudo', m.registo.fechadas.length === 1 && m.api.estado().abertas === 0);\n  }\n\n  t.secao('O QUE A LIGAÇÃO NÃO FAZ');\n  {\n    t.verifica('não substitui a leitura — quem recebe vai ler',\n      /O QUE ISTO NÃO É: não substitui a leitura/.test(SRC));\n    t.verifica('o aviso acorda o módulo, não decide nada',\n      /acordar\\('apoio', 0\\);/.test(SRC) && /acordar\\('partircerco', 0\\);/.test(SRC));\n    /* Há uma ligação por conta, e deve ser gasta no que aquele mundo usa: nos\n     * de revolta é a lista do apoio; nos de cerco o apoio nem corre (18/09). */\n    t.verifica('e o caminho depende do tipo do mundo',\n      /const caminho = deCerco \\? `cercos\\/\\$\\{WORLD\\}` : `apoio\\/\\$\\{WORLD\\}`;/.test(SRC));\n    t.verifica('e o orçamento de ligações está escrito',\n      /O ORÇAMENTO DE LIGAÇÕES/.test(SRC) && /const LIGACOES_MAX = 1;/.test(SRC));\n  }\n  t.secao('O PAINEL MOSTRA O ESTADO');\n  {\n    t.verifica('há um sítio no painel da frota',\n      /<div id=\"frota-ligacao\"/.test(SRC));\n    t.verifica('diz quando está ligada e quantos avisos recebeu',\n      /\\$\\{e\\.avisos\\} aviso\\(s\\) recebido\\(s\\)/.test(SRC));\n    t.verifica('... e quando não está, explica que não se perde nada',\n      /o Maestro lê como sempre/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-mapa-mundo.js": "/* O MAPA DO MUNDO, PELOS FICHEIROS DO SERVIDOR.\n *\n * O servidor publica o mundo inteiro em ficheiros de texto sem autenticação\n * (confirmado no pt126, 17/09): 5809 cidades com dono, ilha e LUGAR NA ILHA;\n * 917 jogadores com aliança; 117878 ilhas com os LUGARES LIVRES.\n *\n * São um pedido por hora a um ficheiro estático — não passam pela API do jogo\n * nem contam para o travão dos pedidos. As sentinelas deixam de precisar de um\n * pedido por ilha, que com 48 ilhas dava 429.\n *\n *   node ferramentas/teste-mapa-mundo.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, PEDIR_JOGO } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('MAPA DO MUNDO');\n\n/* Linhas reais do pt126. */\nconst TOWNS = [\n  '7397,2379469,35.1,390,500,16,12957',      // minha\n  '35,2379469,55.1,499,507,0,13257',         // minha, LUGAR 0\n  '9215,1923767,34.003,359,469,8,1423',      // de outro\n  '9050,2440228,CANTABRIA,525,441,16,1461',  // de outro\n  '5000,1923767,vizinha,499,507,4,900',      // aliado, na mesma ilha que a 55.1\n].join('\\n');\nconst PLAYERS = [\n  '2379469,Shad0wRA,126,50000,1,67',\n  '1923767,Jomaras,126,30000,2,40',\n  '2440228,Estranho,,1000,300,2',\n].join('\\n');\nconst ALLIANCES = ['126,Berimbau+de+Xoxota,798039,120,17,12'].join('\\n');\nconst ISLANDS = ['1,499,507,4,3,stone,iron', '2,390,500,27,0,iron,stone'].join('\\n');\n\nfunction nucleo(falhar) {\n  const loja = {};\n  const ctx = {\n    WORLD: 'pt126',\n    uw: {\n      Game: { player_id: 2379469 },\n      fetch: async (u) => {\n        if (falhar) return { ok: false };\n        const f = String(u).match(/data\\/(\\w+)\\.txt/)[1];\n        const m = { towns: TOWNS, players: PLAYERS, alliances: ALLIANCES, islands: ISLANDS }[f];\n        return { ok: true, text: async () => m };\n      },\n    },\n    localStorage: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = v; } },\n    Date, JSON, Number, Object, String, Promise, console, decodeURIComponent,\n  };\n  vm.createContext(ctx);\n  const i = SRC.indexOf('  const MAPA_KEY =');\n  const f = SRC.indexOf('\\n  try {\\n    uw.__maestroMapa', i);\n  return vm.runInContext('(() => {' + PEDIR_JOGO + '\\n' + SRC.slice(i, f)\n    + '\\nreturn { ler: buscarMapaDoMundo };\\n})()', ctx);\n}\n\n(async () => {\n  const api = nucleo(false);\n  const m = await api.ler();\n  {\n    t.verifica('lê as cidades todas', m && m.nCidades === 5, m && m.nCidades);\n    t.verifica('e os jogadores', m.nJogadores === 3, m.nJogadores);\n  }\n  {\n    const naIlha = m.porIlha['499:507'] || [];\n    t.verifica('agrupa as cidades por ilha', naIlha.length === 2, naIlha.length);\n    const minha = naIlha.find((c) => c.id === 35);\n    t.verifica('o LUGAR 0 é lido como 0, não como vazio', minha && minha.lugar === 0, minha);\n  }\n  {\n    const j = m.jogadores[1923767];\n    t.verifica('cada jogador traz a aliança', j && j.alianca === 126, j);\n    t.verifica('e o nome da aliança resolve-se',\n      (m.aliancas[126] || {}).nome === 'Berimbau de Xoxota', m.aliancas[126]);\n    t.verifica('quem não tem aliança fica a zero', m.jogadores[2440228].alianca === 0);\n  }\n  {\n    t.verifica('as ilhas trazem os lugares livres',\n      m.ilhas['499:507'].livres === 3 && m.ilhas['390:500'].livres === 0, m.ilhas['499:507']);\n  }\n  {\n    /* Os nomes vêm com + no lugar dos espaços. */\n    t.verifica('os nomes são descodificados',\n      m.aliancas[126].nome.indexOf('+') < 0, m.aliancas[126].nome);\n  }\n  {\n    const api2 = nucleo(true);\n    const r = await api2.ler();\n    t.verifica('se os ficheiros falharem, não se inventa nada', r === null, r);\n  }\n  {\n    /* A segunda leitura vem da memória: um pedido por hora. */\n    let pedidos = 0;\n    const antes = m.quando;\n    const m2 = await api.ler();\n    t.verifica('a segunda leitura não vai buscar outra vez', m2.quando === antes);\n  }\n  t.secao('QUEM USA O MAPA');\n  {\n    t.verifica('as sentinelas, para saber quem é aliado em cada ilha',\n      /m\\.porIlha\\[coords\\.x \\+ ':' \\+ coords\\.y\\]/.test(SRC)\n      && /if \\(!nomeAl \\|\\| !amigas\\.has\\(nomeAl\\)\\) continue;/.test(SRC));\n    t.verifica('o fechar ilha, para saber que lugares estão ocupados',\n      /if \\(Number\\.isFinite\\(c\\.lugar\\)\\) ocupados\\.add\\(Number\\(c\\.lugar\\)\\);/.test(SRC));\n    t.verifica('... e calcula o total pelas cidades mais os livres',\n      /const total = cidades\\.length \\+ Number\\(ilha\\.livres\\);/.test(SRC));\n    t.verifica('a fundação, para os lugares livres de cada ilha',\n      /const livres = Number\\(ilha\\.livres\\) \\|\\| 0;[\\s\\S]{0,400}doFicheiro: true/.test(SRC));\n    t.verifica('todos mantêm a leitura do mapa como reserva',\n      (SRC.match(/action=get_chunks/g) || []).length >= 3);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-mapa-pedidos.js": "/* OS PEDIDOS AO MAPA TÊM PAUSA E TRAVÃO.\n *\n * O `infoDaCidade` tinha quatro ciclos a pedir blocos do mapa, nenhum com\n * pausa nem a olhar para o travão do servidor. Com 63 cidades, um clique no\n * botão \"actualizar\" do Apoio disparava dezenas de pedidos seguidos e o\n * servidor recusava ao oitavo (visto em jogo, 16/09).\n *\n *   node ferramentas/teste-mapa-pedidos.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, PEDIR_JOGO } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('PEDIDOS AO MAPA');\n\nfunction api(travado) {\n  const pedidos = [];\n  const ctx = {\n    mUw: {\n      location: { origin: 'https://x' }, Game: { csrfToken: 'T' },\n      fetch: async (u) => { pedidos.push(String(u)); return { status: 200, text: async () => '{}' }; },\n    },\n    lerResposta: async () => ({ json: { data: { 0: { towns: {} } } } }),\n    servidorTravadoAgora: () => travado,\n    Math, Number, JSON, Promise, setTimeout, encodeURIComponent, console,\n  };\n  vm.createContext(ctx);\n  const i = SRC.indexOf('  let pedidosAoMapa = 0;');\n  const f = SRC.indexOf('\\n  async function infoDaCidade(', i);\n  const fn = vm.runInContext('(() => {' + PEDIR_JOGO + '\\n' + SRC.slice(i, f)\n    + '\\nreturn { pedir: pedirBlocoDoMapa, quantos: () => pedidosAoMapa, zerar: () => { pedidosAoMapa = 0; } };\\n})()', ctx);\n  return { fn, pedidos };\n}\n\n(async () => {\n  {\n    const a = api(false);\n    const r = await a.fn.pedir(1, 1, 35);\n    t.verifica('um pedido normal passa', !!r && a.pedidos.length === 1);\n  }\n  {\n    const a = api(true);\n    const r = await a.fn.pedir(1, 1, 35);\n    t.verifica('com o servidor travado não se pede nada', r === null && a.pedidos.length === 0);\n  }\n  {\n    const a = api(false);\n    for (let i = 0; i < 15; i++) await a.fn.pedir(i, i, 35);\n    t.verifica('há um tecto de pedidos por chamada', a.pedidos.length === 12, a.pedidos.length);\n  }\n  {\n    const a = api(false);\n    const t0 = Date.now();\n    await a.fn.pedir(1, 1, 35);\n    await a.fn.pedir(2, 2, 35);\n    const demorou = Date.now() - t0;\n    t.verifica('entre pedidos há uma pausa de pelo menos meio segundo', demorou >= 600, demorou + 'ms');\n  }\n  {\n    /* Todos os ciclos do infoDaCidade passam por aqui: não sobra nenhum\n     * pedido solto ao mapa dentro da função. */\n    const i = SRC.indexOf('  async function infoDaCidade(');\n    const linhas = SRC.slice(i).split('\\n');\n    let fim = 0;\n    for (let k = 1; k < linhas.length; k++) { if (linhas[k] === '  }') { fim = k; break; } }\n    const corpo = linhas.slice(0, fim).join('\\n');\n    t.verifica('nenhum pedido ao mapa fora do travão',\n      !/get_chunks/.test(corpo), (corpo.match(/get_chunks/g) || []).length + ' soltos');\n    t.verifica('... e os ciclos param quando o travão diz que chega',\n      (corpo.match(/if \\(!bloco\\) break;/g) || []).length >= 2);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-mesma-ilha-nc.js": "/* MESMA ILHA — não dá para medir, logo avisa-se.\n *\n * A velocidade calcula-se com a distância entre ILHAS; na mesma ilha é zero e\n * não há nada para medir. O código assumia que um colonizador não vinha da\n * própria ilha — e vem: uma conquista dentro da ilha foi anunciada como\n * \"tropa terrestre a pé\" (visto em jogo, 14/09, 45.1, de 494:506 para\n * 494:506). O `classificar` e o `pareceNC` REAIS.\n *\n *   node ferramentas/teste-mesma-ilha-nc.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('MESMA ILHA');\n\nfunction alertas() {\n  const ctx = {\n    uw: { GameData: { units: { colonize_ship: { speed: 9, is_naval: true }, bireme: { speed: 45, is_naval: true } },\n      powers: { unit_movement_boost: { meta_defaults: { percent: 30 } } } } },\n    seErroDeCodigo: () => {}, console, Math, Number, Object,\n  };\n  vm.createContext(ctx);\n  const a = SRC.indexOf('  const FOLGA_MEDICAO_NC =');\n  const b = SRC.indexOf('  try {\\n    uw.__maestroNC = {', a);\n  return vm.runInContext(SRC.slice(a, b)\n    + funcao(SRC, '  function classificar(vel, mesmaIlha) {') + '\\nclassificar', ctx);\n}\n\n/* `demoras` = o que o jogo já disse sobre este par de cidades (ou null, se\n * ainda não se sabe). */\nfunction esquiva(mesmaIlha, demoras, durou) {\n  const pedidos = [];\n  const ctx = {\n    mUw: {}, seErroDeCodigo: () => {}, console, Math, Number, Promise,\n    coordsOrigem: () => ({ x: 494, y: 506 }),\n    primeiraVezQueVi: () => ({ quando: 9000 - (durou || 0), novo: false }),\n    vistoNoArranque: () => false, agoraJogo: () => 2000,\n    tempoPreparacao: () => 0, rotina: () => {},\n    pareceColonizadorNC: () => ({ nc: false }),\n    ilhaDe: () => null,\n    window: { __maestroDemoras: {\n      guardadas: () => demoras || null,\n      ler: async () => { pedidos.push(1); return demoras || null; },\n      explicam: (d, seg) => (d && d.explicam ? d.explicam(seg) : []),\n    } },\n  };\n  vm.createContext(ctx);\n  const f = vm.runInContext(funcao(SRC, '  function mesmaIlhaTrazNC(a, alvo) {')\n    + funcao(SRC, '  function pareceNC(a, alvo, c) {') + '\\npareceNC', ctx);\n  const alvo = mesmaIlha ? { ix: 494, iy: 506 } : { ix: 500, iy: 500 };\n  return { r: f({ arrival_at: 9000, home_town_id: 1, target_town_id: 2 }, alvo, { K: 100 }), pedidos };\n}\n\n(async () => {\n  const cl = alertas();\n  {\n    const r = cl(18, true);\n    t.verifica('mesma ilha: diz que não dá para medir e marca como possível colonizador',\n      r.nc === true && r.grave === true && !r.certo && /mesma ilha/i.test(r.cat), r);\n  }\n  {\n    const r = cl(45, false);\n    t.verifica('entre ilhas continua a distinguir: birreme não é colonizador', !r.nc, r);\n  }\n  {\n    const r = cl(9, false);\n    t.verifica('entre ilhas, velocidade de colonizador: acusa', r.nc, r);\n  }\n  {\n    const x = esquiva(true, null, 800);\n    t.verifica('mesma ilha sem demoras sabidas: assume o pior e vai pedi-las',\n      x.r === true && x.pedidos.length === 1, x);\n  }\n  {\n    /* Já se sabe: 800 s só é explicado pelo colonizador. */\n    const dem = { explicam: () => [{ id: 'colonize_ship', bonus: 'sem bónus' }] };\n    t.verifica('mesma ilha, demora de colonizador: acusa', esquiva(true, dem, 800).r === true);\n  }\n  {\n    const dem = { explicam: () => [{ id: 'sword', bonus: 'sem bónus' }] };\n    t.verifica('mesma ilha, demora de tropa a pé: já NÃO acusa', esquiva(true, dem, 620).r === false);\n  }\n  {\n    const dem = { explicam: () => [] };\n    t.verifica('nada explica o tempo: assume o pior', esquiva(true, dem, 100).r === true);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-multis-sem-admin.js": "/* AS MULTIS SEM ADMINISTRADOR.\n *\n * Sem Administrador a visão geral devolve zero comandos. A esquiva sabia que\n * havia ataque (a colecção `Attack` marca a cidade) mas não tinha a hora nem a\n * origem, e nunca agia — custou tropa num farm atrás do outro (15/09). Os\n * movimentos da página trazem esses ataques com a hora certa.\n *\n * E o reforço não deve defender contra as PRÓPRIAS contas: cada enviado do\n * farm morreria contra a tropa que ele lá pôs.\n *\n *   node ferramentas/teste-multis-sem-admin.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('MULTIS SEM ADMINISTRADOR');\n\n(async () => {\n  {\n    const i = SRC.indexOf('        if (!cmds.length && /sem Administrador/i.test(');\n    const bloco = SRC.slice(i, i + 1800);\n    t.verifica('a esquiva tem caminho para quando falta o Administrador', i > 0);\n    t.verifica('... e só o usa nas cidades que a página marca como atacadas',\n      /Number\\(m\\.target_town_id\\) === Number\\(tid\\)/.test(bloco), bloco.slice(0, 120));\n    t.verifica('... só conta movimentos que ainda não chegaram',\n      /Number\\(m\\.arrival_at\\) > agoraJogo\\(\\)/.test(bloco));\n    t.verifica('... e usa a hora do próprio movimento',\n      /arrival_at: Number\\(m\\.arrival_at\\)/.test(bloco));\n  }\n  {\n    const i = SRC.indexOf('NÃO SE DEFENDE DE SI PRÓPRIO');\n    const bloco = SRC.slice(i, i + 1800);\n    t.verifica('o reforço sabe quem são as minhas contas', i > 0 && /frota\\/\\$\\{mWorld\\}/.test(bloco));\n    t.verifica('... e tira da lista os ataques que vêm delas',\n      /minhasContas\\.has\\(quem\\)/.test(bloco), bloco.slice(0, 150));\n    t.verifica('... sem mexer em nada quando não consegue saber quem são',\n      /if \\(minhasContas\\) \\{/.test(bloco));\n  }\n  {\n    /* O campo ausente ou vazio não serve; o número 0 serve, e o jogo\n     * propõe-no mesmo numa ilha vazia (15/09). */\n    const i = SRC.indexOf('      /* O LUGAR 0 É UM LUGAR.');\n    const bloco = SRC.slice(i, i + 1200);\n    t.verifica('o fechar ilha não aceita um lugar que o jogo não deu', i > 0\n      && /o jogo não disse que lugar usar/.test(bloco));\n    t.verifica('... mas aceita o lugar 0', /lugar < 0/.test(bloco) && !/lugar === 0/.test(bloco));\n  }\n  {\n    /* A partilha do recrutamento foi DESFEITA: usava um perfil que não existe\n     * e punha a main e as multis no mesmo caminho — os alvos da main foram\n     * substituídos pelos das multis (15/09). */\n    t.verifica('os alvos de recrutamento voltam a ser locais',\n      SRC.indexOf('caminhoFbRecruta') < 0, 'ainda há caminho partilhado');\n    const i = SRC.indexOf('     * ============ A PARTILHA PELO FIREBASE FOI DESFEITA');\n    t.verifica('... e fica escrito porquê, para não se repetir',\n      SRC.indexOf('A PARTILHA PELO FIREBASE FOI DESFEITA') > 0);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-nucleo.js": "/* NÚCLEO — o leitor da visão geral (`__maestroVisaoGeral`): o código REAL,\n * tirado do maestro.user.js, contra um jogo simulado. Cópia, `fresca`,\n * esquecer, pedidos ao mesmo tempo, 429, erros, sem Administrador.\n *\n *   node ferramentas/teste-nucleo.js maestro.user.js\n */\nconst fs = require('fs');\nconst vm = require('vm');\n\nconst ficheiro = process.argv[2] || 'maestro.user.js';\nconst src = fs.readFileSync(ficheiro, 'utf8');\n\nconst ini = src.indexOf('  async function lerRespostaComum(resposta) {');\nconst fim = src.indexOf('  /* ============ AVISO DE VERIFICAÇÃO DE BOT');\nif (ini < 0 || fim < 0 || fim < ini) throw new Error('não encontrei o bloco do núcleo');\n/* O `pedirJogo` vive ao nível do núcleo, antes deste bloco — desde que todos\n * os pedidos passam pelo broker (18/09). */\nconst bloco = `\nfunction pedirJogo(url, opcoes) { return uw.fetch(url, opcoes); }\n` + src.slice(ini, fim);\n\nlet falhas = 0;\nlet n = 0;\nfunction verifica(nome, cond, extra) {\n  n++;\n  if (cond) console.log('  ok  ', nome);\n  else { falhas++; console.log('  FALHA', nome, extra !== undefined ? JSON.stringify(extra) : ''); }\n}\n\n/* Um jogo novo para cada cenário. `respostas` é uma fila: cada pedido tira a\n * primeira. Cada resposta: { status, corpo (objecto ou texto), atraso (ms) }. */\nfunction montar(opcoes) {\n  const op = opcoes || {};\n  const pedidos = [];\n  const caixa = [];\n  const captchas = [];\n  const travoes = [];\n  const respostas = (op.respostas || []).slice();\n  let agora = 1_000_000;\n  const premium = op.premium === undefined ? { k: { attributes: { curator: 9e9 } } } : op.premium;\n\n  const uw = {\n    location: { origin: 'https://pt125.grepolis.com' },\n    Game: { csrfToken: 'TOK', townId: 999 },\n    ITowns: { towns: op.semCidades ? {} : { 111: {}, 222: {} } },\n    MM: { getModels: () => ({ PremiumFeatures: premium }) },\n    fetch: async (url, o) => {\n      pedidos.push({ url, o });\n      const r = respostas.shift() || { status: 200, corpo: { json: { commands: [] } } };\n      if (r.lanca) throw new Error(r.lanca);\n      if (r.atraso) await new Promise((res) => setTimeout(res, r.atraso));\n      const texto = typeof r.corpo === 'string' ? r.corpo : JSON.stringify(r.corpo);\n      return { status: r.status || 200, text: async () => texto };\n    },\n  };\n\n  const ctx = {\n    uw,\n    Date: Object.assign(function () {}, { now: () => agora }),\n    JSON, Object, Array, Number, String, Math, Promise, Error, encodeURIComponent,\n    setTimeout,\n    temAdministrador: () => !!(op.temAdm !== false),\n    servidorTravado: () => !!op.travado,\n    avisarCaptcha: async (onde) => { captchas.push(onde); },\n    guardarNaCaixa: (m, t) => { caixa.push(t); },\n    seErroDeCodigo: () => {},\n    log: () => {},\n  };\n  /* `Date` falso só com o `now`; o resto (new Date) não é usado no leitor,\n   * excepto no estado — aí vai o verdadeiro. */\n  ctx.Date = new Proxy(Date, { get: (t, p) => (p === 'now' ? () => agora : t[p]) });\n  vm.createContext(ctx);\n  /* O leitor comum chama `uw.__maestroTravar` no 429. */\n  uw.__maestroTravar = (min) => travoes.push(min);\n  vm.runInContext(bloco, ctx);\n  return {\n    uw, pedidos, caixa, captchas, travoes,\n    avancar: (ms) => { agora += ms; },\n    vg: (o) => uw.__maestroVisaoGeral(o),\n    esquecer: () => uw.__maestroVisaoGeralEsquecer(),\n    estado: () => uw.__maestroVisaoGeralEstado(),\n  };\n}\n\nconst LISTA = [\n  { id: 1, type: 'attack', origin_town_id: 5, destination_town_id: 111, arrival_at: 2000 },\n  { id: 2, type: 'support', origin_town_id: 111, destination_town_id: 7, arrival_at: 3000 },\n];\nconst ok = (lista) => ({ status: 200, corpo: { json: { commands: lista } } });\nconst okData = (lista) => ({ status: 200, corpo: { json: { data: { commands: lista } } } });\n\n(async () => {\n  console.log('\\nLEITURA');\n  {\n    const j = montar({ respostas: [ok(LISTA)] });\n    const r = await j.vg();\n    verifica('json.commands → ok com a lista', r.ok && r.comandos.length === 2 && r.razao === '', r);\n    const u = j.pedidos[0].url;\n    verifica('pedido: GET à command_overview, primeira cidade, token, json',\n      /\\/game\\/town_overviews\\?town_id=111&action=command_overview&h=TOK&json=/.test(u)\n      && !(j.pedidos[0].o || {}).method, u);\n    verifica('pedido com x-requested-with e credenciais',\n      j.pedidos[0].o.headers['x-requested-with'] === 'XMLHttpRequest'\n      && j.pedidos[0].o.credentials === 'include');\n  }\n  {\n    const j = montar({ respostas: [okData(LISTA)] });\n    const r = await j.vg();\n    verifica('json.data.commands → ok com a lista', r.ok && r.comandos.length === 2, r);\n  }\n  {\n    const j = montar({ respostas: [ok([])] });\n    const r = await j.vg();\n    verifica('lista vazia de verdade → ok com []', r.ok && Array.isArray(r.comandos) && r.comandos.length === 0, r);\n  }\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: { json: { outra: 1 } } }] });\n    const r = await j.vg();\n    verifica('resposta sem lista → ok:false, comandos null, diz as chaves',\n      !r.ok && r.comandos === null && /não traz a lista.*outra/.test(r.razao), r);\n    verifica('... e fica na caixa da rotina', j.caixa.length === 1, j.caixa);\n  }\n  {\n    const j = montar({ semCidades: true, respostas: [ok(LISTA)] });\n    const r = await j.vg();\n    verifica('sem ITowns → usa Game.townId', r.ok && /town_id=999&/.test(j.pedidos[0].url), j.pedidos[0]);\n  }\n\n  console.log('\\nFALHAS');\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: { json: { error: 'Algo correu mal' } } }] });\n    const r = await j.vg();\n    verifica('erro do jogo → ok:false com a razão', !r.ok && r.comandos === null && r.razao === 'Algo correu mal', r);\n  }\n  {\n    const j = montar({ respostas: [{ status: 429, corpo: '' }] });\n    const r = await j.vg();\n    verifica('429 → ok:false e o núcleo trava', !r.ok && /recusar/.test(r.razao) && j.travoes.length === 1, r);\n  }\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: '<html>erro</html>' }] });\n    const r = await j.vg();\n    verifica('página de erro → ok:false', !r.ok && /página de erro/.test(r.razao), r);\n  }\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: '' }] });\n    const r = await j.vg();\n    verifica('resposta vazia → ok:false', !r.ok && /não respondeu/.test(r.razao), r);\n  }\n  {\n    const j = montar({ respostas: [{ lanca: 'NetworkError' }] });\n    const r = await j.vg();\n    verifica('fetch rebenta → ok:false', !r.ok && /pedido falhou: NetworkError/.test(r.razao), r);\n  }\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: { json: { error: 'backend_requested_verification' } } }] });\n    const r = await j.vg();\n    verifica('verificação de bot → ok:false e avisa', !r.ok && /verificação/.test(r.razao)\n      && j.captchas.length === 1, { r, captchas: j.captchas });\n  }\n  {\n    const j = montar({ travado: true, respostas: [ok(LISTA)] });\n    const r = await j.vg();\n    verifica('servidor travado → ok:false SEM pedido', !r.ok && j.pedidos.length === 0 && /limitar/.test(r.razao), r);\n  }\n\n  console.log('\\nADMINISTRADOR');\n  {\n    const j = montar({ temAdm: false, respostas: [ok(LISTA)] });\n    const r = await j.vg();\n    verifica('sem Administrador → ok:false SEM pedido', !r.ok && r.razao === 'sem Administrador'\n      && j.pedidos.length === 0, r);\n    verifica('... calado (nada na caixa)', j.caixa.length === 0, j.caixa);\n  }\n  {\n    const j = montar({ premium: {}, temAdm: false, respostas: [ok(LISTA)] });\n    const r = await j.vg();\n    verifica('modelo das assinaturas por carregar → pede e decide o servidor',\n      r.ok && j.pedidos.length === 1, r);\n  }\n  {\n    const j = montar({ respostas: [\n      { status: 200, corpo: { json: { error: 'Necessita do administrador para aceder às visões gerais' } } },\n      ok(LISTA)] });\n    const r1 = await j.vg();\n    const r2 = await j.vg({ fresca: true });\n    verifica('servidor diz \"administrador\" → ok:false', !r1.ok && r1.razao === 'sem Administrador', r1);\n    verifica('... e não volta a pedir durante 30 min (nem com fresca)', !r2.ok && j.pedidos.length === 1, r2);\n    j.avancar(31 * 60 * 1000);\n    const r3 = await j.vg();\n    verifica('... passados 30 min volta a pedir', r3.ok && j.pedidos.length === 2, r3);\n  }\n\n  console.log('\\nCÓPIA PARTILHADA');\n  {\n    const j = montar({ respostas: [ok(LISTA), ok(LISTA.slice(0, 1))] });\n    const r1 = await j.vg();\n    j.avancar(10 * 1000);\n    const r2 = await j.vg();\n    verifica('dentro de 20 s → da cópia, sem pedido', r2.ok && r2.daCopia && j.pedidos.length === 1, r2);\n    verifica('... com a hora da leitura original', r2.quando === r1.quando);\n    j.avancar(11 * 1000);\n    const r3 = await j.vg();\n    verifica('passados 20 s → pedido novo', !r3.daCopia && j.pedidos.length === 2 && r3.comandos.length === 1, r3);\n  }\n  {\n    const j = montar({ respostas: [ok(LISTA), ok(LISTA.slice(0, 1))] });\n    await j.vg();\n    const r = await j.vg({ fresca: true });\n    verifica('fresca → salta a cópia', j.pedidos.length === 2 && r.comandos.length === 1 && !r.daCopia, r);\n    const r2 = await j.vg();\n    verifica('... e a leitura fresca passa a ser a cópia', r2.daCopia && r2.comandos.length === 1, r2);\n  }\n  {\n    const j = montar({ respostas: [ok(LISTA), ok(LISTA.slice(0, 1))] });\n    await j.vg();\n    j.esquecer();\n    const r = await j.vg();\n    verifica('esquecer → o pedido seguinte vai ao servidor', j.pedidos.length === 2 && !r.daCopia, r);\n  }\n  {\n    const j = montar({ respostas: [ok(LISTA)] });\n    const a = await j.vg();\n    a.comandos[0].type = 'MEXIDO';\n    a.comandos.push({ id: 99 });\n    const b = await j.vg();\n    verifica('cada módulo recebe a sua cópia (mexer numa não mexe na outra)',\n      b.comandos.length === 2 && b.comandos[0].type === 'attack', b.comandos);\n  }\n  {\n    const j = montar({ respostas: [ok(LISTA)] });\n    const r = await j.vg();\n    j.avancar(5000);\n    const e = j.estado();\n    verifica('estado na consola', e.pedidos === 1 && /2 comando\\(s\\), de há 5 s/.test(e.copia)\n      && e.administrador === 'sim', e);\n    void r;\n  }\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: { json: { error: 'x' } } }, ok(LISTA)] });\n    await j.vg();\n    const r = await j.vg();\n    verifica('uma falha não fica como cópia (o seguinte pede de novo)', r.ok && j.pedidos.length === 2, r);\n  }\n\n  console.log('\\nPEDIDOS AO MESMO TEMPO');\n  {\n    const j = montar({ respostas: [{ ...ok(LISTA), atraso: 30 }] });\n    const [a, b, c] = await Promise.all([j.vg(), j.vg(), j.vg()]);\n    verifica('três pedidos ao mesmo tempo → um só pedido ao servidor',\n      j.pedidos.length === 1 && a.ok && b.ok && c.ok, j.pedidos.length);\n    verifica('... o primeiro fez o pedido, os outros partilharam',\n      !a.daCopia && b.daCopia && c.daCopia && j.estado().partilhados === 2, j.estado());\n    verifica('... e cada um com a sua cópia', a.comandos !== b.comandos && b.comandos !== c.comandos);\n  }\n  {\n    const j = montar({ respostas: [{ ...ok(LISTA), atraso: 30 }, ok(LISTA)] });\n    const pa = j.vg();\n    const pb = j.vg({ fresca: true });\n    await Promise.all([pa, pb]);\n    verifica('fresca não aproveita um pedido já a caminho', j.pedidos.length === 2, j.pedidos.length);\n  }\n  {\n    /* Envio a meio de uma leitura: a lista que vem pode não ter o envio. */\n    const j = montar({ respostas: [{ ...ok(LISTA), atraso: 30 }, ok(LISTA.slice(0, 1))] });\n    const pa = j.vg();\n    await new Promise((r) => setTimeout(r, 5));\n    j.esquecer();                                    // um módulo mandou tropa\n    const pb = j.vg();                               // pede depois do envio\n    const [a, b] = await Promise.all([pa, pb]);\n    verifica('esquecer a meio: quem pediu antes recebe a lista antiga', a.ok && a.comandos.length === 2, a);\n    verifica('... quem pediu depois NÃO partilha o pedido antigo', j.pedidos.length === 2\n      && b.comandos.length === 1, { pedidos: j.pedidos.length, b });\n    const c = await j.vg();\n    verifica('... e a cópia que fica é a nova', c.daCopia && c.comandos.length === 1, c);\n  }\n  {\n    const j = montar({ respostas: [{ ...ok(LISTA), atraso: 30 }] });\n    const pa = j.vg();\n    await new Promise((r) => setTimeout(r, 5));\n    j.esquecer();\n    await pa;\n    const e = j.estado();\n    verifica('esquecer a meio: a resposta antiga não fica como cópia', e.copia === 'nenhuma', e);\n  }\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: { json: { error: 'x' } }, atraso: 20 }] });\n    const [a, b] = await Promise.all([j.vg(), j.vg()]);\n    verifica('falha partilhada → os dois recebem ok:false', !a.ok && !b.ok && j.pedidos.length === 1);\n  }\n\n  console.log(`\\n${n - falhas}/${n} verificações passaram.`);\n  process.exit(falhas ? 1 : 0);\n})();\n",
 "teste-ordem-retirada.js": "/* ORDEM DE RETIRADA MARCADA AO ENVIAR, E TECTO DE 14 HORAS.\n *\n * A retirada dependia de LER — a visão geral e a Ágora. Quando a leitura\n * falha, a tropa ficava no alvo indefinidamente (visto em jogo, 15/09). A\n * ordem marca-se no envio: um minuto depois do impacto. E um alvo não fica na\n * lista mais do que uma revolta pode durar: 7 h + 7 h = 14 h.\n *\n *   node ferramentas/teste-ordem-retirada.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('ORDEM DE RETIRADA');\nconst AP = 'function makeApoioModule(opts)';\n\n/* O tecto das 14 h, com o relógio na mão. */\nfunction tecto(entradas, agoraMs) {\n  const loja = { grepoApoio_entradaAlvo_v1: JSON.stringify(entradas || {}) };\n  const ctx = {\n    armazem: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = v; } },\n    seErroDeCodigo: () => {}, console, Math, Number, Object, JSON, Set,\n    Date: new Proxy(Date, { get: (o, p) => (p === 'now' ? () => agoraMs : o[p]) }),\n  };\n  vm.createContext(ctx);\n  /* Do TECTO até ao fim do `alvosPassadosDoTecto`. */\n  const a = SRC.indexOf('  const TECTO_ALVO_MS = 14 * 3600 * 1000;');\n  const b = SRC.indexOf('\\n  function faltaRepor(alvoId) {', a);\n  const api = vm.runInContext('(() => {\\n' + SRC.slice(a, b)\n    + '\\nreturn { marcar: marcarEntrada, passados: alvosPassadosDoTecto, ver: lerEntradas };\\n})()', ctx);\n  return { api, loja };\n}\n\nconst H = 3600 * 1000;\n\n(async () => {\n  const agora = 1000 * H;\n  {\n    const m = tecto({}, agora);\n    m.api.marcar([111, 222]);\n    t.verifica('um alvo novo fica marcado com a hora de entrada',\n      Object.keys(m.api.ver()).length === 2, m.api.ver());\n    t.verifica('acabado de entrar: não passa do tecto', m.api.passados([111, 222]).length === 0);\n  }\n  {\n    const m = tecto({ 111: agora - 13 * H, 222: agora - 15 * H }, agora);\n    t.verifica('13 h fica, 15 h sai', igual(m.api.passados([111, 222]), [222]), m.api.passados([111, 222]));\n  }\n  {\n    const m = tecto({ 111: agora - 20 * H }, agora);\n    m.api.marcar([222]);\n    t.verifica('um alvo tirado da lista deixa de ser contado',\n      !m.api.ver()[111] && !!m.api.ver()[222], m.api.ver());\n  }\n  {\n    const m = tecto({ 111: agora - 2 * H }, agora);\n    m.api.marcar([111]);\n    t.verifica('marcar de novo não reinicia o relógio', m.api.ver()[111] === agora - 2 * H, m.api.ver());\n  }\n  t.secao('REFORÇO — A HORA MARCADA AO ENVIAR');\n  {\n    /* O registo do envio passa a levar `retirarAs` = impacto + 1 min. */\n    const i = SRC.indexOf('        const impactoNovo = Math.max(');\n    t.verifica('o envio guarda a hora da retirada', i > 0 && /retirarAs: impactoNovo \\? impactoNovo \\+ 60 : 0/.test(SRC.slice(i, i + 1400)));\n  }\n  {\n    const i = SRC.indexOf('      const horaOrdem = Number(e.retirarAs)');\n    t.verifica('a retirada usa essa hora, com recurso ao impacto nos envios antigos',\n      i > 0 && /\\|\\| \\(Number\\(e\\.impacto\\) \\? Number\\(e\\.impacto\\) \\+ 60 : 0\\)/.test(SRC.slice(i, i + 200)));\n  }\n  {\n    const i = SRC.indexOf('      if (aindaAtacadas.has(Number(e.destino))) {');\n    const bloco = SRC.slice(i, i + 700);\n    t.verifica('outro ataque à mesma cidade adia a ordem em vez de a cancelar',\n      /e\\.retirarAs = proximo \\+ 60/.test(bloco), bloco.slice(0, 200));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-painel-relatorios.js": "/* PAINEL DOS RELATÓRIOS — o botão Guardar.\n *\n * O visto dos transportes nunca esteve no HTML, e o `.checked` de um campo\n * que não existe rebentava o Guardar inteiro: não se guardava nada, nem o\n * resto. O painel REAL, desenhado num DOM de mentira.\n *\n *   node ferramentas/teste-painel-relatorios.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('PAINEL DOS RELATÓRIOS');\n\n/* Um DOM só com o que o painel usa: ids, checked, value e onclick. */\nfunction dom(html) {\n  const els = {};\n  const re = /id=\\\\?\"([a-z-]+)\\\\?\"([^>]*)/g;\n  let m;\n  while ((m = re.exec(html))) {\n    const resto = m[2] || '';\n    els[m[1]] = { checked: / checked/.test(resto), value: (resto.match(/value=\\\\?\"([^\"\\\\]*)/) || [])[1] || '' };\n  }\n  return { querySelector: (s) => els[s.replace('#', '')] || null, els };\n}\n\nfunction painel(cfgInicial) {\n  const loja = { 'grepoRelatorios_cfg_v1': JSON.stringify(cfgInicial || {}) };\n  const guardado = [];\n  /* O módulo inteiro, com o `armazem` e o `normalizar` que ele espera. */\n  const txt = S.fabrica(SRC, 'makeRelatoriosModule')\n    + \"\\nmakeRelatoriosModule({ intervaloMin: 60 })\";\n  const ctx = {\n    window: { __maestroArmazem: {\n      getItem: (k) => (k in loja ? loja[k] : null),\n      setItem: (k, v) => { loja[k] = v; try { guardado.push(JSON.parse(v)); } catch (e) {} },\n    } },\n    localStorage: { getItem: () => null, setItem: () => {} },\n    seErroDeCodigo: () => {}, console,\n  };\n  vm.createContext(ctx);\n  return { mod: vm.runInContext(txt, ctx), guardado, loja };\n}\n\n(async () => {\n  let p;\n  try { p = painel({ ativo: true, apoios: true, transportes: false, ler: true, lerMax: 7 }); }\n  catch (e) { console.error('não consegui montar o painel:', e.message); process.exit(2); }\n\n  /* Desenhar o painel: recolhe-se o HTML que ele produz. */\n  let html = '';\n  const container = {\n    set innerHTML(v) { html = v; Object.assign(this, dom(v)); },\n    get innerHTML() { return html; },\n    querySelector: () => null,\n  };\n  p.mod.painel(container, { log: () => {}, uw: {} });\n\n  t.verifica('o painel tem o visto dos transportes', !!container.querySelector('#rel-transp'),\n    Object.keys(container.els || {}));\n  t.verifica('... e o visto de ler os relatórios', !!container.querySelector('#rel-ler'));\n\n  const g = container.querySelector('#rel-guardar');\n  t.verifica('o botão Guardar existe', !!g);\n  if (g && g.onclick) {\n    let rebentou = '';\n    try { g.onclick(); } catch (e) { rebentou = e.message; }\n    t.verifica('Guardar não rebenta', !rebentou, rebentou);\n    const ultimo = p.guardado[p.guardado.length - 1] || {};\n    t.verifica('... e guarda o que estava no painel', ultimo.ativo === true && ultimo.apoios === true\n      && ultimo.ler === true && ultimo.lerMax === 7, ultimo);\n  }\n\n  /* Um painel a que falte um campo (versão antiga do HTML, ou outro tema). */\n  const c2 = { innerHTML: '', querySelector: (s) => (s === '#rel-guardar' ? c2.__g : null) };\n  c2.__g = {};\n  try {\n    p.mod.painel(c2, { log: () => {}, uw: {} });\n    let rebentou2 = '';\n    if (c2.__g.onclick) { try { c2.__g.onclick(); } catch (e) { rebentou2 = e.message; } }\n    t.verifica('com os campos todos em falta, Guardar continua sem rebentar', !rebentou2, rebentou2);\n  } catch (e) { t.verifica('com os campos todos em falta, Guardar continua sem rebentar', false, e.message); }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-painel.js": "/* O PAINEL — o que ocupa espaço e o que não precisa de lá estar.\n *\n * A lista do estado tinha os vinte e dois módulos, um por linha, e enchia meio\n * painel com \"Auto-construção, 6 min\" — que não diz nada. E a configuração que\n * se mexe uma vez por conta estava toda aberta (16/09).\n *\n *   node ferramentas/teste-painel.js maestro.user.js\n */\nconst S = require('./simulador');\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('PAINEL');\n\n(async () => {\n  {\n    const i = SRC.indexOf('SÓ O QUE ESTÁ A CORRER E O QUE ESTÁ ATRASADO');\n    const bloco = SRC.slice(i, i + 2000);\n    t.verifica('a lista do estado mostra o que corre e o que está atrasado', i > 0\n      && /ligados\\.filter\\(\\(m\\) => \\(modState\\[m\\.id\\] \\|\\| \\{\\}\\)\\.aCorrer \\|\\| atrasado\\(m\\)\\)/.test(bloco));\n    t.verifica('... conta o resto numa linha só',\n      /\\$\\{emDia\\} módulo\\(s\\) em dia/.test(bloco));\n    t.verifica('... e atrasado é ter passado da hora por mais de um minuto',\n      /\\(Date\\.now\\(\\) - st\\.proximaExec\\) > 60 \\* 1000/.test(bloco));\n  }\n  {\n    t.verifica('a configuração de perfil e partilha está numa secção fechada',\n      /<summary style=\"cursor:pointer;font-size:11px;font-weight:600\">perfil e partilha<\\/summary>/.test(SRC));\n    t.verifica('a caixa do Gist saiu do painel',\n      !/maestro-gist-id/.test(SRC) && !/maestro-gist-guardar/.test(SRC));\n    t.verifica('... mas a leitura do Gist fica como reserva',\n      /api\\.github\\.com\\/gists/.test(SRC));\n  }\n  {\n    const i = SRC.indexOf('<div id=\"maestro-modulos\"></div>');\n    const bloco = SRC.slice(i - 9000, i);\n    t.verifica('as secções do painel abrem e fecham todas',\n      (bloco.match(/<details/g) || []).length === (bloco.match(/<\\/details>/g) || []).length,\n      (bloco.match(/<details/g) || []).length + ' vs ' + (bloco.match(/<\\/details>/g) || []).length);\n  }\n  t.secao('O BOTÃO E O FECHAR');\n  {\n    /* Metido dentro da caixa do retrato, o botão ficava por trás da moldura:\n     * existia, tinha tamanho e estava visível, mas não se via (18/09). */\n    /* Primeiro foi uma barra a flutuar por cima do mapa; depois um botão com\n     * o nome, que ficou escondido por trás da moldura do retrato. O que\n     * faltava era parecer parte do jogo: um círculo pequeno com um M, no\n     * espaço livre à esquerda do retrato (18/09). */\n    /* Quatro sítios até acertar: a flutuar por cima do mapa, dentro da caixa\n     * do retrato (por trás da moldura), ao lado do retrato (espaço do\n     * DIO-Tools) e fixo em coordenadas escritas à mão — pequeno e no sítio\n     * errado. Agora encosta ao nome da cidade e é maior; onde exactamente,\n     * está no teste-botao-seletor (18/09). */\n    t.verifica('é um círculo com um M, ao lado do nome da cidade',\n      /UM CÍRCULO, COMO OS DO JOGO/.test(SRC)\n      && /AO LADO DO SELETOR DE CIDADE/.test(SRC)\n      && /'width:28px', 'height:28px', 'border-radius:50%',/.test(SRC));\n    t.verifica('... com um M e não o nome todo',\n      /btn\\.innerHTML = '<span id=\"maestro-btn-luz\"><\\/span><span>M<\\/span>';/.test(SRC));\n    t.verifica('... e fixo: arrastá-lo punha-o fora do ecrã',\n      /if \\(naBarraDoJogo\\) return;\\s*\\n\\s*aArrastar = true; moveu = false;/.test(SRC));\n    t.verifica('a luz do estado passa a ser o anel à volta',\n      /if \\(naBarraDoJogo\\) el\\.style\\.borderColor = cor;/.test(SRC));\n    /* Dentro das caixas do jogo já ficou escondido duas vezes: por trás da\n     * moldura do retrato, e por baixo de um painel do DIO-Tools. */\n    t.verifica('... e não depende de nenhum contentor do jogo',\n      /Vai sempre para o corpo da página/.test(SRC)\n      && /document\\.body\\.appendChild\\(btn\\);/.test(SRC));\n  }\n  {\n    /* O painel tapa meio ecrã e só fechava carregando outra vez no botão —\n     * que às vezes fica por baixo dele (18/09). */\n    t.verifica('o Esc fecha o painel',\n      /if \\(ev\\.key !== 'Escape'\\) return;/.test(SRC));\n    t.verifica('... mas não enquanto se escreve num campo',\n      /if \\(act && \\/\\^\\(INPUT\\|TEXTAREA\\|SELECT\\)\\$\\/\\.test\\(act\\.tagName\\)\\) return;/.test(SRC));\n    t.verifica('clicar fora também fecha',\n      /if \\(pn\\.contains\\(ev\\.target\\) \\|\\| btn\\.contains\\(ev\\.target\\)\\) return;/.test(SRC));\n    t.verifica('... e o clique que abre não o fecha logo a seguir',\n      /try \\{ ev\\.stopPropagation\\(\\); \\} catch \\(e\\) \\{\\}/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-partilha.js": "/* A PARTILHA PELO NOME DO FICHEIRO.\n *\n * O Gist separava a main das multis pelo NOME: `recrutamento-templates-main-pt126`\n * contra `-multi-pt126`. Na 7600 mandei tudo para um caminho construído a\n * partir de uma chave de perfil que não existe, e a main ficou com os alvos\n * das multis (15/09).\n *\n * Isto prova o que tem de ser verdade: com a mesma configuração, a main e a\n * multi vão a sítios DIFERENTES.\n *\n *   node ferramentas/teste-partilha.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('PARTILHA');\n\n/* O `ficheiroGist` real do recrutamento, com o perfil que o painel guarda. */\nfunction nomeDoFicheiro(perfil, mundo) {\n  const loja = { grepoMaestro_modulos_v1: JSON.stringify({ perfil }) };\n  const ctx = {\n    armazem: { getItem: (k) => (k in loja ? loja[k] : null) },\n    GIST: { filename: 'recrutamento-templates.json' },\n    mWorld: mundo, seErroDeCodigo: () => {}, console, String, JSON,\n  };\n  vm.createContext(ctx);\n  return vm.runInContext(funcao(SRC, '  function ficheiroGist() {', 'function makeRecrutamentoModule(opts)')\n    + '\\nficheiroGist()', ctx);\n}\n\n/* A chave do Firebase a partir desse nome. */\nfunction chave(nome) {\n  const ctx = { String, console };\n  vm.createContext(ctx);\n  const i = SRC.indexOf('  function chaveGistNoFirebase(nomeFicheiro) {');\n  const f = SRC.indexOf('\\n  }\\n', i) + 4;\n  return vm.runInContext(SRC.slice(i, f) + '\\nchaveGistNoFirebase(' + JSON.stringify(nome) + ')', ctx);\n}\n\n(async () => {\n  const main = nomeDoFicheiro('main', 'pt126');\n  const multi = nomeDoFicheiro('multi', 'pt126');\n  t.verifica('a main tem o seu ficheiro', main === 'recrutamento-templates-main-pt126.json', main);\n  t.verifica('as multis têm outro', multi === 'recrutamento-templates-multi-pt126.json', multi);\n  t.verifica('E SÃO DIFERENTES — foi isto que falhou na 7600', main !== multi);\n\n  const km = chave(main), kx = chave(multi);\n  t.verifica('a chave do Firebase mantém a separação', km !== kx, { km, kx });\n  t.verifica('... e é a mesma que a cópia usou', km === 'gist/recrutamento-templates-main-pt126', km);\n\n  const outro = nomeDoFicheiro('main', 'pt127');\n  t.verifica('mundos diferentes também não se misturam', chave(outro) !== km, chave(outro));\n\n  t.verifica('o recrutamento lê do Firebase antes do Gist',\n    SRC.indexOf('PRIMEIRO O FIREBASE, COM O NOME DO FICHEIRO') > 0);\n  t.verifica('... e grava lá com a mesma chave',\n    /const r = await p\\.escrever\\(ficheiroGist\\(\\), t\\);/.test(SRC));\n  t.secao('OS OUTROS MÓDULOS');\n  {\n    const liga = (marca) => SRC.indexOf(marca) > 0;\n    t.verifica('construção lê do Firebase',\n      (SRC.match(/const d = await p\\.ler\\(ficheiroGist\\(\\)\\)/g) || []).length >= 4);\n    t.verifica('e grava lá',\n      (SRC.match(/await p\\.escrever\\(ficheiroGist\\(\\)/g) || []).length >= 4);\n    t.verifica('os colonos usam o nome deles', liga('const d = await p.ler(FICHEIRO());'));\n    t.verifica('o perfil também', liga('if (p) dadosFb = await p.ler(ficheiroPerfil(nome));'));\n    t.verifica('... e o que vem do Firebase segue o mesmo caminho de aplicação',\n      liga('let conteudoFb = null;') && liga('if (dadosFb) conteudoFb = JSON.stringify(dadosFb);'));\n  }\n  t.secao('A PRINCIPAL PUBLICA SOZINHA');\n  {\n    /* Exigia o Gist: ao tirar as credenciais, a principal deixou de publicar e\n     * as multis ficaram com as definições antigas (15/09). */\n    const i = SRC.indexOf('A PUBLICAÇÃO NÃO PODE DEPENDER DO GIST');\n    const bloco = SRC.slice(i, i + 2200);\n    t.verifica('publica com Firebase, sem precisar do Gist', i > 0\n      && /if \\(!temFirebase && \\(!GIST_ID_GLOBAL \\|\\| !GIST_TOKEN_GLOBAL\\)\\) return;/.test(bloco));\n    t.verifica('... e só quando alguma definição mudou',\n      /if \\(agora && agora === assinaturaPublicada\\) return;/.test(bloco));\n    t.verifica('... de cinco em cinco minutos, não de meia em meia hora',\n      /\\}, 5 \\* 60 \\* 1000\\);/.test(bloco));\n    t.verifica('buscar o perfil também não precisa do Gist',\n      /if \\(souPrincipal\\(\\) \\|\\| \\(!GIST_ID_GLOBAL && !temFb\\)\\) return;/.test(SRC));\n  }\n  t.secao('O PERFIL VAI COM A DATA');\n  {\n    /* Gravei só as chaves quando passei o perfil para o Firebase (8000). Quem\n     * lê precisa da DATA para saber se é novo: sem ela, a verificação \"isto é\n     * mais recente do que o que já apliquei?\" falhava sempre e o perfil NUNCA\n     * era aplicado — numa multi, a última aplicação foi a 15/09 às 03:58, pelo\n     * Gist (visto em jogo, 16/09). */\n    t.verifica('a gravação leva perfil, mundo, data e chaves',\n      /await p\\.escrever\\(ficheiroPerfil\\(nome\\), \\{\\s*\\n\\s*perfil: nome, mundo: WORLD, quando: Date\\.now\\(\\), chaves,/.test(SRC));\n    t.verifica('... e a leitura aceita os perfis antigos, sem embrulho',\n      /if \\(dadosFb && !dadosFb\\.chaves && Object\\.keys\\(dadosFb\\)\\.some/.test(SRC));\n    t.verifica('a aplicação continua a ignorar o que não é mais recente',\n      /if \\(!r\\.quando \\|\\| r\\.quando <= antes\\) return;/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-partir-cerco.js": "/* PARTIR CERCOS — mundos de cerco.\n *\n * Num mundo de cerco, um ataque com colonizador que vence a defesa deixa a\n * cidade cercada durante sete ou oito horas. Para partir, é preciso limpar a\n * frota que a segura.\n *\n * O módulo não espera pelo cerco: assim que vê um colonizador a caminho,\n * agenda ataques para baterem NO MESMO SEGUNDO do impacto. A razão é uma regra\n * do jogo — ao mesmo segundo, a ordem é a de quem enviou primeiro, e o\n * colonizador já partiu. Bate ele, cria o cerco, e os nossos batem logo a\n * seguir, antes dos apoios que o adversário mandar (desenhado com o Rafa,\n * 18/09).\n *\n *   node ferramentas/teste-partir-cerco.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('PARTIR CERCOS');\nconst PC = 'function makePartirCercoModule(opts)';\n\nconst AGORA = Math.floor(Date.now() / 1000);\n\nfunction montar(movimentos, deRevolta) {\n  const ctx = {\n    mUw: {\n      Game: { player_id: 111, player_name: 'Eu' },\n      ITowns: { towns: { 10: {}, 20: {} }, getTown: (id) => ({ getName: () => 'c' + id }) },\n      MM: {\n        getModels: () => (deRevolta\n          ? { MovementsUnits: movimentos, MovementsRevoltDefender: {} }\n          : { MovementsUnits: movimentos }),\n      },\n    },\n    seErroDeCodigo: () => {},\n    Date, Math, Number, Object, Set, String, console,\n  };\n  vm.createContext(ctx);\n  return vm.runInContext(\n    funcao(SRC, '  function mundoDeCerco() {', PC)\n    + funcao(SRC, '  function colonizadoresAChegar() {', PC)\n    + funcao(SRC, '  function nomeDaCidade(id) {', PC)\n    + '\\n({ cerco: mundoDeCerco, ver: colonizadoresAChegar })', ctx);\n}\n\nconst mov = (tipo, alvo, jogador, chega) => ({\n  attributes: { id: 1, command_id: 99, type: tipo, target_town_id: alvo,\n    player_id: jogador, arrival_at: chega, town_name_origin: 'deles' },\n});\n\n(async () => {\n  t.secao('QUE MUNDO É ESTE');\n  {\n    t.verifica('sem a colecção das revoltas, é de cerco', montar({}, false).cerco() === true);\n    t.verifica('com ela, é de revolta', montar({}, true).cerco() === false);\n  }\n\n  t.secao('QUE COLONIZADORES INTERESSAM');\n  {\n    const a = montar({ x: mov('attack_takeover', 10, 999, AGORA + 3600) }, false);\n    const r = a.ver();\n    t.verifica('um ataque de conquista a uma cidade minha entra', r.length === 1, r);\n    t.verifica('... com a hora do impacto', r[0] && r[0].chega === AGORA + 3600, r[0]);\n  }\n  {\n    const a = montar({ x: mov('attack', 10, 999, AGORA + 3600) }, false);\n    t.verifica('um ataque normal não conta', a.ver().length === 0);\n  }\n  {\n    const a = montar({ x: mov('attack_takeover', 99, 999, AGORA + 3600) }, false);\n    t.verifica('um colonizador para outro jogador não conta', a.ver().length === 0);\n  }\n  {\n    const a = montar({ x: mov('attack_takeover', 10, 111, AGORA + 3600) }, false);\n    t.verifica('o meu próprio colonizador não conta', a.ver().length === 0);\n  }\n  {\n    const a = montar({ x: mov('attack_takeover', 10, 999, AGORA - 10) }, false);\n    t.verifica('um que já bateu não conta', a.ver().length === 0);\n  }\n\n  t.secao('O PLANO');\n  {\n    t.verifica('as cidades ordenam-se da mais próxima à mais distante',\n      /cidades\\.sort\\(\\(a, b\\) => \\(a\\.viagem \\|\\| 1e9\\) - \\(b\\.viagem \\|\\| 1e9\\)\\);/.test(SRC));\n    t.verifica('as que cabem na janela agendam',\n      /const cabe = cid\\.viagem > 0 && \\(cid\\.viagem \\+ 30\\) <= faltam;/.test(SRC));\n    t.verifica('... e as outras vão directas',\n      /if \\(cabe\\) agendar\\.push\\(\\{ \\.\\.\\.cid, leva \\}\\);\\s*\\n\\s*else directos\\.push/.test(SRC));\n    t.verifica('o pacote é repartido até esgotar',\n      /const leva = Math\\.min\\(cid\\.farois, porMandar\\);/.test(SRC));\n    t.verifica('e diz-se quando não chega',\n      /faltaram \\$\\{plano\\.emFalta\\} farol/.test(SRC));\n  }\n\n  t.secao('O AGENDAMENTO');\n  {\n    t.verifica('bate no segundo do impacto, nunca antes',\n      /toleranciaAntes: 0,/.test(SRC) && /SÓ DEPOIS DO IMPACTO/.test(SRC));\n    t.verifica('... com tolerância só para depois',\n      /desvioAntes: Number\\(p\\.toleranciaAntes\\) \\|\\| 0,/.test(SRC));\n    t.verifica('o Encaixe expõe o agendamento a outros módulos',\n      /uwj\\.__maestroAgendarEncaixe = async \\(p\\) => \\{/.test(SRC));\n    t.verifica('... e o cálculo da viagem',\n      /uwj\\.__maestroDuracaoPrevista = \\(origemId, alvoId, unidades\\) => \\{/.test(SRC));\n    t.verifica('... e o envio directo',\n      /uwj\\.__maestroEnviarComando = async \\(origemId, alvoId, unidades, tipo\\) => \\{/.test(SRC));\n  }\n\n  t.secao('O GRUPO');\n  {\n    t.verifica('cada conta publica os colonizadores que lhe vêm',\n      /await fb\\.escrever\\(`\\$\\{caminhoAvisos\\(\\)\\}\\/\\$\\{conta\\}`/.test(SRC));\n    t.verifica('... e lê os das outras',\n      /async function cercosDoGrupo\\(\\)/.test(SRC));\n    t.verifica('publicações velhas não contam',\n      /if \\(!x\\.quando \\|\\| \\(agoraS - Number\\(x\\.quando\\)\\) > 3600\\) continue;/.test(SRC));\n    t.verifica('um cerco já tratado não se repete',\n      /const porFazer = todos\\.filter\\(\\(x\\) => !feitos\\[String\\(x\\.cmd\\)\\]\\);/.test(SRC));\n    t.verifica('e o vigia acorda o módulo quando vê um colonizador',\n      /if \\(novos\\.some\\(\\(a\\) => \\/takeover\\/i\\.test\\(String\\(a\\.type \\|\\| ''\\)\\)\\)\\) \\{/.test(SRC));\n  }\n\n  t.secao('CUIDADOS');\n  {\n    t.verifica('num mundo de revolta o módulo não faz nada',\n      /este mundo é de revolta — não há cercos a partir/.test(SRC));\n    t.verifica('o risco está escrito no painel',\n      /se a defesa aguentar e o colonizador não passar/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-quadro-revoltas.js": "/* O QUADRO DAS REVOLTAS ACTIVAS.\n *\n * Uma mensagem só, mandada pela conta principal, com todas as revoltas do\n * grupo — main e multis. Cada linha diz a cidade, de que conta é, quem a\n * revoltou, quanto falta e quanta tropa já lá está.\n *\n * Só sai quando a lista MUDA: uma revolta nova ou uma que acabou. Sem isso,\n * seria um quadro igual ao anterior de meia em meia hora (17/09).\n *\n *   node ferramentas/teste-quadro-revoltas.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('QUADRO DAS REVOLTAS');\nconst AP = 'function makeApoioModule(opts)';\n\nconst AGORA = Math.floor(Date.now() / 1000);\n\nfunction montar(frota, guardadoInicial) {\n  const loja = { grepoApoio_quadroRevoltas_v1: guardadoInicial || '' };\n  const avisos = [];\n  const ctx = {\n    mWorld: 'pt126',\n    fbLerM: async () => frota,\n    fbUrlM: () => 'https://x',\n    localStorage: {\n      getItem: (k) => (k in loja ? loja[k] : null),\n      setItem: (k, v) => { loja[k] = v; },\n    },\n    seErroDeCodigo: () => {},\n    Date, Math, Number, Object, String, console,\n  };\n  vm.createContext(ctx);\n  const i = SRC.indexOf('  const QUADRO_KEY =');\n  const f = SRC.indexOf('\\n  /* ============ SÓ A CONTA PRINCIPAL TIRA ALVOS', i);\n  const api = vm.runInContext('(() => {\\n' + SRC.slice(i, f)\n    + '\\nreturn { quadro: quadroDasRevoltas };\\n})()', ctx);\n  return { api, avisos, ctx: { avisarDiscord: async (c, m) => avisos.push(m) }, loja };\n}\n\nconst revolta = (nome, quem, emR1, faltaMin) => ({\n  nome, quem: [quem], emR1, ultima: AGORA + faltaMin * 60,\n});\n\n(async () => {\n  {\n    const m = montar({\n      a: { conta: 'Multi1', quando: AGORA, apoio: { alvos: { 500: { u: { sword: 1500, bireme: 500 } } } } },\n    });\n    const r = await m.api.quadro(m.ctx, {\n      revoltasAuto: { 500: revolta('55.6', 'Jomaras', true, 200) },\n    });\n    t.verifica('manda o quadro quando há revolta', r === true && m.avisos.length === 1);\n    const q = m.avisos[0] || {};\n    t.verifica('o título diz quantas são', /1/.test(q.titulo || ''), q.titulo);\n    const linha = (q.campos || [])[0] || {};\n    t.verifica('a linha tem a cidade', /55\\.6/.test(linha.nome || ''), linha);\n    t.verifica('... quem a revoltou', /Jomaras/.test(linha.valor || ''), linha.valor);\n    t.verifica('... a fase e o tempo que falta',\n      /R1/.test(linha.valor || '') && /200 min/.test(linha.valor || ''), linha.valor);\n    t.verifica('... e a tropa que lá está',\n      /2[\\s.,]?000 de tropa/.test(linha.valor || ''), linha.valor);\n  }\n  {\n    /* A mesma lista não se repete. */\n    const m = montar({}, '');\n    const lista = { revoltasAuto: { 500: revolta('55.6', 'X', true, 100) } };\n    await m.api.quadro(m.ctx, lista);\n    const r2 = await m.api.quadro(m.ctx, lista);\n    t.verifica('não repete um quadro igual', r2 === false && m.avisos.length === 1, m.avisos.length);\n  }\n  {\n    /* Uma revolta nova muda a lista. */\n    const m = montar({}, '');\n    await m.api.quadro(m.ctx, { revoltasAuto: { 500: revolta('A', 'X', true, 100) } });\n    await m.api.quadro(m.ctx, {\n      revoltasAuto: { 500: revolta('A', 'X', true, 100), 600: revolta('B', 'Y', false, 50) },\n    });\n    t.verifica('uma revolta nova gera quadro novo', m.avisos.length === 2, m.avisos.length);\n  }\n  {\n    /* Mudar de R1 para R2 também conta. */\n    const m = montar({}, '');\n    await m.api.quadro(m.ctx, { revoltasAuto: { 500: revolta('A', 'X', true, 100) } });\n    await m.api.quadro(m.ctx, { revoltasAuto: { 500: revolta('A', 'X', false, 60) } });\n    t.verifica('passar de R1 a R2 gera quadro novo', m.avisos.length === 2, m.avisos.length);\n  }\n  {\n    /* Acabaram todas: avisa uma vez. */\n    const m = montar({}, '500:R1');\n    const r = await m.api.quadro(m.ctx, { revoltasAuto: {} });\n    t.verifica('quando acabam todas, diz que acabaram',\n      r === true && /Sem revoltas/.test((m.avisos[0] || {}).titulo || ''), m.avisos);\n  }\n  {\n    /* Sem revoltas e sem nada antes: não manda nada. */\n    const m = montar({}, '');\n    const r = await m.api.quadro(m.ctx, { revoltasAuto: {} });\n    t.verifica('sem revoltas e sem histórico: silêncio', m.avisos.length === 0);\n  }\n  t.secao('AS REVOLTAS DAS MULTIS NÃO SE PERDEM');\n  {\n    /* A lista é escrita inteira por quem a grava. Como cada conta só conhece\n     * as revoltas das cidades dela, gravar a lista inteira apagava as das\n     * outras: a main escrevia as duas dela e as três das multis desapareciam\n     * (17/09 — o quadro só mostrava as da main). */\n    t.verifica('cada conta só tira as revoltas das SUAS cidades',\n      /CADA CONTA SÓ TIRA AS REVOLTAS DAS SUAS CIDADES/.test(SRC)\n      && /if \\(minhasCidadesAqui\\.size && !minhasCidadesAqui\\.has\\(Number\\(id\\)\\)\\) continue;/.test(SRC));\n    t.verifica('... e as cidades vêm do próprio jogo',\n      /const minhasCidadesAqui = new Set\\(\\s*\\n\\s*\\(ctx\\.getMyTowns\\(\\) \\|\\| \\[\\]\\)\\.map/.test(SRC));\n  }\n  {\n    /* O bloco dos recursos por feitiço tem de viver ao nível do módulo. */\n    const linhas = SRC.split('\\n');\n    const i = linhas.findIndex((l) => l.includes('async function cumprirPedidosDeRecursos'));\n    let mod = '?';\n    for (let k = i; k >= 0; k--) { if (/^function make/.test(linhas[k])) { mod = linhas[k]; break; } }\n    t.verifica('o cumprirPedidosDeRecursos vive no módulo dos feitiços',\n      /makeFeiticosModule/.test(mod), mod);\n    t.verifica('... e não está dentro de outra função',\n      /^  async function cumprirPedidosDeRecursos/.test(linhas[i] || ''), linhas[i]);\n  }\n  t.secao('UMA REVOLTA PERDIDA VOLTA A ENTRAR');\n  {\n    /* A lista só se gravava quando havia revoltas NOVAS, removidas ou\n     * corrigidas. Uma detectada há horas não é nova — por isso, se o registo\n     * dela se perdesse, nunca mais era reposto. Foi o que aconteceu à 5105 da\n     * MacaquinhoChinês: a conta apoiava a cidade, via a revolta, e o\n     * `revoltasAuto` continuava sem ela (17/09). */\n    const i = SRC.indexOf('UMA REVOLTA QUE SE PERDEU DA LISTA VOLTA A ENTRAR');\n    t.verifica('conta-se o que esta conta vê e não está registado', i > 0\n      && /\\.filter\\(\\(id\\) => !guardadas\\[String\\(id\\)\\]\\)/.test(SRC));\n    t.verifica('... e isso chega para gravar a lista',\n      /if \\(novos\\.length \\|\\| aRetirar\\.length \\|\\| corrigidos\\.length \\|\\| emFalta\\.length\\) \\{/.test(SRC));\n    t.verifica('o registo diz que as repôs', /volto a pô-las/.test(SRC));\n    t.verifica('e a gravação leva TODAS as revoltas vistas, não só as novas',\n      /for \\(const r of revoltas\\) \\{\\s*\\n\\s*auto\\[String\\(r\\.id\\)\\]/.test(SRC));\n  }\n  t.secao('AS MULTIS PUBLICAM AS REVOLTAS DELAS');\n  {\n    /* A lista de alvos tem um dono único — a main — para as contas não se\n     * atropelarem. Mas a detecção corria dentro do bloco da principal, e as\n     * multis nunca a faziam: uma cidade de uma multi em revolta era apoiada,\n     * mas nunca aparecia no registo das revoltas (17/09, a 5105). */\n    const i = SRC.indexOf('AS MULTIS PUBLICAM AS REVOLTAS DELAS');\n    t.verifica('cada conta escreve num sítio só dela', i > 0\n      && /return `revoltasMultis\\/\\$\\{mWorld\\}\\/\\$\\{conta\\}`;/.test(SRC));\n    t.verifica('... só com as cidades dela',\n      /if \\(!id \\|\\| !minhas\\.has\\(id\\)\\) continue;/.test(SRC));\n    t.verifica('... e funciona sem Administrador, pelos modelos',\n      /const r = revoltasPelosModelos\\(agoraS\\);/.test(SRC));\n    t.verifica('escreve-se mesmo quando não há revoltas',\n      /Escreve-se sempre, mesmo vazio/.test(SRC));\n    t.verifica('a main lê o que as outras publicaram',\n      /const dasOutras = await revoltasDasOutrasContas\\(AGORA\\);/.test(SRC));\n    t.verifica('... ignora publicações velhas',\n      /if \\(!x\\.quando \\|\\| \\(agoraS - Number\\(x\\.quando\\)\\) > 6 \\* 3600\\) continue;/.test(SRC));\n    t.verifica('... e junta-as às que vê', /if \\(porCidade\\[id\\]\\) continue;/.test(SRC));\n    {\n      /* A junção estava depois de a lista de revoltas já estar fixada: as\n       * revoltas das multis entravam quando ninguém mais as ia buscar, e o\n       * registo partilhado continuava só com as da main (17/09). */\n      const linhas = SRC.split('\\n');\n      const le = linhas.findIndex((l) => l.includes('const dasOutras = await revoltasDasOutrasContas'));\n      const junta = linhas.findIndex((l) => l.includes('for (const id of Object.keys(dasOutras))'));\n      const fixa = linhas.findIndex((l) => l.includes('const revoltas = Object.keys(porCidade)'));\n      t.verifica('a junção acontece ANTES de a lista fechar',\n        le > 0 && le < junta && junta < fixa, { le: le + 1, junta: junta + 1, fixa: fixa + 1 });\n    }\n    /* A hora calcula-se na chamada: o `AGORA` do bloco da principal só existe\n     * dentro dele, e usá-lo antes rebentava com \"AGORA is not defined\" em\n     * todas as multis (17/09). */\n    t.verifica('todas as contas publicam, a main incluída',\n      /await publicarRevoltasDestaConta\\(ctx, Math\\.floor\\(Date\\.now\\(\\) \\/ 1000\\)\\)/.test(SRC));\n    t.verifica('... com a hora calculada fora do bloco da principal',\n      !/publicarRevoltasDestaConta\\(ctx, AGORA\\)/.test(SRC));\n  }\n  t.secao('O NOME DA CIDADE E A CONTA');\n  {\n    /* No quadro, as cidades das outras contas apareciam pelo número: a main\n     * não as conhece. Mas quem publica conhece-as (17/09). */\n    t.verifica('quem publica vai buscar o nome ao próprio jogo',\n      /O NOME VEM DE QUEM CONHECE A CIDADE/.test(SRC)\n      && /if \\(t && t\\.getName\\) nomeAqui = t\\.getName\\(\\) \\|\\| nomeAqui;/.test(SRC));\n    t.verifica('o quadro lê quem publicou cada revolta',\n      /const pub = \\(await fbLerM\\(`revoltasMultis\\/\\$\\{mWorld\\}`\\)\\) \\|\\| \\{\\};/.test(SRC));\n    t.verifica('... e usa esse nome quando só tem o número',\n      /if \\(n2 && rev\\[id\\] && \\/\\^\\\\d\\+\\$\\/\\.test\\(String\\(rev\\[id\\]\\.nome \\|\\| ''\\)\\)\\) rev\\[id\\]\\.nome = n2;/.test(SRC));\n    t.verifica('... e diz de que conta é a cidade',\n      /const dono = contaDe\\[id\\] \\|\\| donoDe\\[id\\] \\|\\| '';/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-recursos-feiticos.js": "/* RECURSOS POR FEITIÇO, A PEDIDO.\n *\n * Três feitiços dão recursos a QUALQUER cidade — a tua, de uma multi ou de um\n * aliado — e não têm tempo de espera entre lançamentos (valores lidos do jogo,\n * 17/09):\n *\n *   Oferta do oceano          25 favor → 800 madeira   (Poseidon)\n *   Oferta da natureza        30 favor → 650 pedra     (Ártemis)\n *   Tesouros do mundo mortos  30 favor → 500 prata     (Hades)\n *\n * Com vinte contas, 32 de madeira por favor. Conta-se o que cada feitiço dá,\n * por isso ninguém precisa de ver os recursos da cidade.\n *\n *   node ferramentas/teste-recursos-feiticos.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('RECURSOS POR FEITIÇO');\nconst FE = 'function makeFeiticosModule(opts)';\n\nfunction montar(pedidos, favor, deuses, lancaOk) {\n  const guardado = { valor: pedidos };\n  const lancados = [];\n  const registo = [];\n  const ctx = {\n    mWorld: 'pt126',\n    mUw: {\n      __maestroFb: {\n        url: () => 'https://x',\n        ler: async () => guardado.valor,\n        escrever: async (c, d) => { guardado.valor = d; },\n      },\n      ITowns: {\n        getTown: (id) => ({ god: () => deuses[id] || null }),\n      },\n    },\n    favorDe: (d) => Number(favor[d]) || 0,\n    lancar: async (power, alvo, de) => {\n      lancados.push({ power, alvo, de });\n      return lancaOk === false ? { ok: false, msg: 'recusado' } : { ok: true, msg: 'ok' };\n    },\n    log: (x) => registo.push(x),\n    rotina: (x) => registo.push(x),\n    seErroDeCodigo: () => {},\n    Number, Object, String, Date, console,\n  };\n  vm.createContext(ctx);\n  const i = SRC.indexOf('  const RECURSOS_POR_FEITICO = {');\n  /* O bloco vive ao nível do módulo, a seguir ao `lancar`. */\n  const fimCorpo = SRC.indexOf('\\n    if (mexeu) await gravarPedidosDeRecursos(pedidos);', i);\n  const f = SRC.indexOf('\\n  }\\n', fimCorpo) + 4;\n  const api = vm.runInContext('(() => {\\n' + SRC.slice(i, f)\n    + '\\nreturn { cumprir: cumprirPedidosDeRecursos, tabela: RECURSOS_POR_FEITICO };\\n})()', ctx);\n  return { api, guardado, lancados, registo };\n}\n\nconst ctxFalso = { sleep: async () => {}, rand: () => 1 };\nconst towns = [{ id: 1 }, { id: 2 }];\n\n(async () => {\n  {\n    const m = montar({}, {}, {}, true);\n    t.verifica('os valores são os que o jogo diz',\n      m.api.tabela.wood.favor === 25 && m.api.tabela.wood.da === 800\n      && m.api.tabela.stone.da === 650 && m.api.tabela.iron.da === 500, m.api.tabela);\n  }\n  {\n    /* Pedido de madeira, com Poseidon e favor: lança. */\n    const m = montar({ r1: { alvo: 500, nome: 'X', quer: { wood: 2400 }, feito: {} } },\n      { poseidon: 100 }, { 1: 'poseidon' }, true);\n    await m.api.cumprir(ctxFalso, towns);\n    t.verifica('lança o feitiço certo na cidade certa',\n      m.lancados.length === 1 && m.lancados[0].power === 'kingly_gift'\n      && m.lancados[0].alvo === 500, m.lancados);\n    t.verifica('... e desconta o que deu',\n      m.guardado.valor.r1.feito.wood === 800, m.guardado.valor.r1);\n  }\n  {\n    /* Sem favor, não lança. */\n    const m = montar({ r1: { alvo: 500, quer: { wood: 800 }, feito: {} } },\n      { poseidon: 10 }, { 1: 'poseidon' }, true);\n    await m.api.cumprir(ctxFalso, towns);\n    t.verifica('sem favor que chegue, não lança', m.lancados.length === 0);\n  }\n  {\n    /* Sem o deus certo, não lança. */\n    const m = montar({ r1: { alvo: 500, quer: { stone: 650 }, feito: {} } },\n      { artemis: 100 }, { 1: 'poseidon', 2: 'poseidon' }, true);\n    await m.api.cumprir(ctxFalso, towns);\n    t.verifica('sem cidade que venere o deus, não lança', m.lancados.length === 0);\n  }\n  {\n    /* Pedido cumprido: sai da lista. */\n    const m = montar({ r1: { alvo: 500, nome: 'X', quer: { wood: 800 }, feito: { wood: 800 } } },\n      { poseidon: 100 }, { 1: 'poseidon' }, true);\n    await m.api.cumprir(ctxFalso, towns);\n    t.verifica('pedido cumprido sai da lista',\n      !m.guardado.valor.r1 && m.registo.some((x) => /cumprido/.test(x)), m.guardado.valor);\n  }\n  {\n    /* Um por passagem e por conta: as vinte somam depressa. */\n    const m = montar({ r1: { alvo: 500, quer: { wood: 8000, stone: 8000 }, feito: {} } },\n      { poseidon: 500, artemis: 500 }, { 1: 'poseidon', 2: 'artemis' }, true);\n    await m.api.cumprir(ctxFalso, towns);\n    t.verifica('um lançamento por passagem', m.lancados.length === 1, m.lancados);\n  }\n  {\n    /* Sem pedidos, não faz nada. */\n    const m = montar({}, { poseidon: 500 }, { 1: 'poseidon' }, true);\n    const r = await m.api.cumprir(ctxFalso, towns);\n    t.verifica('sem pedido, o módulo não faz nada', r === false && m.lancados.length === 0);\n  }\n  {\n    /* O lançamento falha: não desconta. */\n    const m = montar({ r1: { alvo: 500, quer: { wood: 800 }, feito: {} } },\n      { poseidon: 100 }, { 1: 'poseidon' }, false);\n    await m.api.cumprir(ctxFalso, towns);\n    t.verifica('se o jogo recusar, não se desconta nada',\n      !(m.guardado.valor.r1.feito || {}).wood, m.guardado.valor.r1);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-reforco-agendados.js": "/* REFORÇO — tropa já comprometida não se manda.\n *\n * A esquiva e o encaixe agendam envios: a tropa está em casa, mas já tem\n * destino e hora. Se o reforço a levar, o plano chega à hora e não encontra\n * nada. Uma cidade com envio agendado fica de fora do reforço.\n *\n *   node ferramentas/teste-reforco-agendados.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('REFORÇO — AGENDADOS');\nconst RE = 'function makeReforcoModule(opts)';\n\nfunction montar(esquiva, encaixe, agora) {\n  const loja = {\n    grepoEsquiva_planos_v1: JSON.stringify(esquiva || {}),\n    grepoEncaixe_planos_v1: JSON.stringify(encaixe || {}),\n  };\n  const ctx = {\n    mUw: { Timestamp: { now: () => agora || 1000 } },\n    armazem: { getItem: (k) => (k in loja ? loja[k] : null) },\n    seErroDeCodigo: () => {}, console, Math, Number, Set, Object, JSON, Date,\n  };\n  vm.createContext(ctx);\n  return vm.runInContext(funcao(SRC, '  function cidadesComEnvioAgendado() {', RE)\n    + '\\ncidadesComEnvioAgendado', ctx);\n}\n\n(async () => {\n  {\n    const f = montar({ 'a@1': { townId: 111, S: 1200 } }, {});\n    t.verifica('cidade com plano de esquiva: fica de fora', [...f()].join() === '111', [...f()]);\n  }\n  {\n    const f = montar({}, { 'b@2': { townId: 222, S: 1100 } });\n    t.verifica('cidade com plano de encaixe: também', [...f()].join() === '222', [...f()]);\n  }\n  {\n    const f = montar({ 'a@1': { townId: 111, S: 1200 } }, { 'b@2': { townId: 222, S: 1100 } });\n    t.verifica('os dois módulos somam-se', igual([...f()].sort(), [111, 222]), [...f()]);\n  }\n  {\n    /* Um plano cuja hora passou há mais de uma hora já não prende nada. */\n    const f = montar({ 'velho@1': { townId: 111, S: 1000 - 7200 } }, {}, 1000);\n    t.verifica('plano velho não prende a cidade', [...f()].length === 0, [...f()]);\n  }\n  {\n    const f = montar({}, {});\n    t.verifica('sem planos: nenhuma cidade de fora', [...f()].length === 0);\n  }\n  {\n    const f = montar({ 'x': { S: 1200 } }, {});\n    t.verifica('plano sem cidade: ignora-se em vez de rebentar', [...f()].length === 0);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-reforco-blocos.js": "/* REFORÇO — não dar a tropa por perdida só porque os modelos não a mostram.\n *\n * Os modelos `Units` são incompletos. Uma lista sem o bloco passava por\n * \"morreu no ataque ou foi retirada\": o registo era apagado e a tropa ficava\n * parada no destino para sempre (visto em jogo, 14/09 — quatro cidades de uma\n * vez em 55.9). Agora confirma-se na Ágora da origem. O `blocosEm` REAL.\n *\n *   node ferramentas/teste-reforco-blocos.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('REFORÇO — BLOCOS');\nconst RE = 'function makeReforcoModule(opts)';\n\n/* `modelos`: o que a página tem. `agora`: o que a Ágora responde\n * (null = não consegui ler; lista = o que está fora daquela cidade). */\nfunction montar(modelos, agora) {\n  const pedidos = [];\n  const ctx = {\n    mUw: {\n      MM: { getModels: () => ({ Units: modelos || {} }) },\n      GameData: { units: { sword: {}, archer: {}, hoplite: {}, bireme: {} } },\n      __maestroApoioFora: agora === undefined ? undefined : {\n        daCidade: async (id) => { pedidos.push(id); return agora; },\n      },\n    },\n    seErroDeCodigo: () => {}, console,\n  };\n  vm.createContext(ctx);\n  const f = vm.runInContext(funcao(SRC, '  async function blocosEm(origemId, destinoId) {', RE)\n    + funcao(SRC, '  function blocosPelosModelos(origemId, destinoId) {', RE) + '\\nblocosEm', ctx);\n  return { f, pedidos };\n}\n\nconst MODELO = { m1: { attributes: { id: 417043, home_town_id: 55013, current_town_id: 55009, archer: 559, hoplite: 493 } } };\nconst OUTRO = { m2: { attributes: { id: 999, home_town_id: 55027, current_town_id: 55009, archer: 10 } } };\n\n(async () => {\n  {\n    const m = montar(MODELO);\n    const r = await m.f(55013, 55009);\n    t.verifica('o bloco está nos modelos: usa-o, sem perguntar à Ágora',\n      r.length === 1 && r[0].id === 417043 && igual(r[0].unidades, { archer: 559, hoplite: 493 }), r);\n  }\n  {\n    /* O caso de 14/09: há modelos, mas não o desta origem. */\n    const m = montar(OUTRO, [{ alvoId: 55009, unitsId: 417043, unidades: { archer: 559 } }]);\n    const r = await m.f(55013, 55009);\n    t.verifica('modelos sem o bloco, mas a Ágora tem-no: a tropa ESTÁ lá',\n      r.length === 1 && r[0].id === 417043 && m.pedidos[0] === 55013, { r, p: m.pedidos });\n  }\n  {\n    const m = montar(OUTRO, []);\n    const r = await m.f(55013, 55009);\n    t.verifica('a Ágora responde e não tem nada: aí sim, já não está', igual(r, []), r);\n  }\n  {\n    const m = montar(OUTRO, [{ alvoId: 55018, unitsId: 5, unidades: { sword: 3 } }]);\n    const r = await m.f(55013, 55009);\n    t.verifica('a Ágora só mostra apoio noutra cidade: já não está em 55.9', igual(r, []), r);\n  }\n  {\n    const m = montar(OUTRO, null);\n    const r = await m.f(55013, 55009);\n    t.verifica('a Ágora não conseguiu ler: NÃO SEI (mantém o registo)', r === null, r);\n  }\n  {\n    const m = montar({}, [{ alvoId: 55009, unitsId: 1, unidades: { sword: 1 } }]);\n    const r = await m.f(55013, 55009);\n    t.verifica('modelos por carregar: não sei, sem sequer perguntar', r === null && !m.pedidos.length, { r, p: m.pedidos });\n  }\n  {\n    const m = montar(OUTRO, undefined);\n    const r = await m.f(55013, 55009);\n    t.verifica('sem a Ágora disponível: não sei (não apaga o registo)', r === null, r);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-reforco-partilhado.js": "/* O REFORÇO SOB ATAQUE, PARTILHADO ENTRE AS CONTAS.\n *\n * Cada conta só defendia as suas cidades — e uma multi sozinha raramente tem\n * tropa que chegue. Agora um ataque a qualquer cidade do grupo é defendido por\n * todas (desenhado com o Rafa, 18/09).\n *\n * E o envio passa pelo ENCAIXE, a chegar um segundo antes do impacto: o\n * adversário não tem tempo de ajustar o ataque. Desvio só para antes — tropa\n * que chega depois não defende nada.\n *\n *   node ferramentas/teste-reforco-partilhado.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, PEDIR_JOGO } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('REFORÇO PARTILHADO');\nconst RF = 'function makeReforcoModule(opts)';\n\nconst AGORA = Math.floor(Date.now() / 1000);\n\nfunction montar(publicado, frota) {\n  const escritos = {};\n  const ctx = {\n    mUw: {\n      Game: { world_id: 'pt126', player_name: 'Eu' },\n      __maestroFb: {\n        url: () => 'https://x',\n        ler: async (c) => (/^frota/.test(c) ? frota : publicado),\n        escrever: async (c, d) => { escritos[c] = d; },\n      },\n    },\n    seErroDeCodigo: () => {},\n    Date, Math, Number, Object, String, console,\n  };\n  vm.createContext(ctx);\n  const api = vm.runInContext(PEDIR_JOGO\n    + funcao(SRC, '  async function publicarAtaques(ataques) {', RF)\n    + funcao(SRC, '  async function ataquesDoGrupo() {', RF)\n    + funcao(SRC, '  async function quotaDestaConta(objetivo) {', RF)\n    + \"\\nconst caminhoAtaques = () => `reforcoAtaques/${mUw.Game.world_id}`;\"\n    + '\\n({ publicar: publicarAtaques, ler: ataquesDoGrupo, quota: quotaDestaConta })', ctx);\n  return { api, escritos };\n}\n\n(async () => {\n  t.secao('PUBLICAR');\n  {\n    const m = montar({}, {});\n    await m.api.publicar([{ cid: '7', alvo: 500, alvoNome: '55.1', chega: AGORA + 600 }]);\n    const d = m.escritos['reforcoAtaques/pt126/Eu'];\n    t.verifica('publica os ataques que me chegam', !!d && !!d.ataques['7'], d);\n    t.verifica('... com a cidade, o nome e a hora',\n      d.ataques['7'].alvo === 500 && d.ataques['7'].nome === '55.1'\n      && d.ataques['7'].chega === AGORA + 600, d.ataques['7']);\n    t.verifica('... e diz de que conta é', d.ataques['7'].conta === 'Eu');\n  }\n\n  t.secao('LER OS DOS OUTROS');\n  {\n    const m = montar({\n      Outra: { quando: AGORA, ataques: { 9: { alvo: 800, nome: '34.2', chega: AGORA + 900, conta: 'Outra' } } },\n    }, {});\n    const r = await m.api.ler();\n    t.verifica('lê os ataques das outras contas', r.length === 1, r);\n    t.verifica('... com a conta a que pertencem', r[0].conta === 'Outra', r[0]);\n  }\n  {\n    /* Uma publicação velha não é de confiança: a conta pode ter fechado. */\n    const m = montar({\n      Velha: { quando: AGORA - 7200, ataques: { 9: { alvo: 800, chega: AGORA + 900 } } },\n    }, {});\n    t.verifica('publicações velhas não contam', (await m.api.ler()).length === 0);\n  }\n  {\n    const m = montar({\n      Outra: { quando: AGORA, ataques: { 9: { alvo: 800, chega: AGORA - 10 } } },\n    }, {});\n    t.verifica('um ataque que já bateu não conta', (await m.api.ler()).length === 0);\n  }\n\n  t.secao('A QUOTA');\n  {\n    const frota = {};\n    for (let i = 0; i < 20; i++) frota['c' + i] = { quando: AGORA };\n    const m = montar({}, frota);\n    const q = await m.api.quota({ sword: 4500, bireme: 1000 });\n    t.verifica('o objectivo divide-se pelas contas vivas',\n      q.sword === 225 && q.bireme === 50, q);\n  }\n  {\n    const m = montar({}, { a: { quando: AGORA } });\n    const q = await m.api.quota({ sword: 4500 });\n    t.verifica('com uma conta só, manda-se o objectivo inteiro', q.sword === 4500, q);\n  }\n  {\n    /* Contas caladas não contam para a divisão. */\n    const m = montar({}, { a: { quando: AGORA }, b: { quando: AGORA - 99999 } });\n    const q = await m.api.quota({ sword: 4500 });\n    t.verifica('contas caladas não contam', q.sword === 4500, q);\n  }\n  {\n    const m = montar({}, null);\n    const q = await m.api.quota({ sword: 4500 });\n    t.verifica('sem frota, manda-se tudo — mais vale a mais', q.sword === 4500, q);\n  }\n\n  t.secao('O ENVIO PELO ENCAIXE');\n  {\n    t.verifica('chega antes do impacto, não depois',\n      /const chegadaAlvo = \\(Number\\(a\\.chega\\) \\|\\| 0\\) - \\(Number\\(c\\.segundosAntes\\) \\|\\| 1\\);/.test(SRC));\n    t.verifica('... com desvio só para antes',\n      /toleranciaAntes: Number\\(c\\.toleranciaAntes\\) \\|\\| 3,\\s*\\n\\s*toleranciaDepois: 0,/.test(SRC));\n    t.verifica('vai como apoio, não como ataque',\n      /tipo: 'support',\\s*\\n\\s*chegada: chegadaAlvo,/.test(SRC));\n    t.verifica('sem encaixe, envia-se como antes',\n      /\\} else \\{\\s*\\n\\s*r = await enviarApoio\\(origem\\.id, id, carga\\);\\s*\\n\\s*\\}/.test(SRC));\n    t.verifica('e só se agenda o que ainda chega a tempo',\n      /chegadaAlvo > Math\\.floor\\(Date\\.now\\(\\) \\/ 1000\\) \\+ viagem/.test(SRC));\n  }\n\n  t.secao('O BOTÃO NA BARRA DO JOGO');\n  {\n    /* Onde o botão fica, e o que acontece quando o seletor se mexe ou some,\n     * está agora todo no teste-botao-seletor. Aqui fica só o que este\n     * ficheiro tinha de próprio: que ele existe e não se arrasta (18/09). */\n    t.verifica('procura o nome da cidade para se encostar a ele',\n      /function acharSeletorDeCidade\\(\\) \\{/.test(SRC));\n    t.verifica('na barra não se arrasta nem se restaura posição',\n      /Na barra do jogo não há posição a restaurar nem arrastar/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-relatorios.js": "/* LER RELATÓRIOS — o que o jogo diz em cada um.\n *\n * Formato confirmado em jogo (11/09): o HTML vem em `plain.html`, no topo da\n * resposta; cada tropa é `data-unit_id`/`data-unit_count`; o lado está na\n * classe do bloco à volta; as perdas em `report_losts`; o assunto em\n * `<span class=\"subject\">`. O código REAL do módulo contra relatórios com\n * esse formato.\n *\n *   node ferramentas/teste-relatorios.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('LER RELATÓRIOS');\n\nfunction leitor() {\n  /* Do início do leitor até ao fim do `anotar`: é tudo o que se precisa. */\n  /* Do início do leitor até ao fim do `anotar` — o que não faz pedidos. */\n  const i = SRC.indexOf('  const LIDOS_KEY =');\n  const f = SRC.indexOf('  /* Um relatório: pedir e ler.', i);\n  const txt = SRC.slice(i, f)\n    + '\\n({ lerRelatorio, anotar, ver: () => lerJSON(INIMIGOS_KEY, {}) })';\n  const loja = {};\n  const ctx = { seErroDeCodigo: () => {}, atob: (s) => Buffer.from(s, 'base64').toString('binary'),\n    escape, decodeURIComponent, unescape,\n    armazem: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = v; } } };\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx);\n}\n\nconst bloco = (lado, u, n, perdeu) => `<div class=\"report_side_${lado}_unit\">`\n  + `<div class=\"report_unit unit report_side_${lado} unit_${u} unit_icon40x40 ${u}\" `\n  + `data-unit_id=\"${u}\" data-unit_count=\"${n}\"><span class=\"bold\">${n}</span></div>`\n  + (perdeu != null ? `<span class=\"report_losts\">-${perdeu}</span>` : '') + '</div>';\nconst spy = (u, n) => `<div class=\"report_unit unit unit_${u} spy unit_icon40x40 ${u}\" `\n  + `data-unit_id=\"${u}\" data-unit_count=\"${n}\"></div>`;\nconst b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');\nconst cabecalho = (origem, destino) => `<div id=\"report_sending_town\">`\n  + `<a href=\"#${b64({ id: 421, ix: 502, iy: 512, tp: 'town', name: 'Cidade' })}\" class=\"gp_town_link\">Cidade</a>`\n  + `<a href=\"#${b64({ name: origem, id: 2225917 })}\" class=\"gp_player_link\">${origem}</a></div>`\n  + `<div id=\"report_receiving_town\">`\n  + `<a href=\"#${b64({ name: destino, id: 2379469 })}\" class=\"gp_player_link\">${destino}</a></div>`;\n\n/* Os quatro casos que a espia mostrou. */\nconst ATAQUE = `<span class=\"subject\">126-55-002 (Godfather) está a atacar 45.9</span>`\n  + cabecalho('Godfather', 'Shad0wRA')\n  + bloco('attacker', 'rider', 35, 35)\n  + bloco('defender', 'bireme', 3110, 0) + bloco('defender', 'sword', 4500, 13)\n  + bloco('defender', 'militia', 375, 1);\nconst MEU_ATAQUE = `<span class=\"subject\">55.25 está a atacar 45 - 02 (RJFS23)</span>`\n  + cabecalho('Shad0wRA', 'RJFS23')\n  + bloco('attacker', 'attack_ship', 298, 298) + bloco('defender', 'bireme', 400, 12);\nconst ESPIA_OK = `<span class=\"subject\">55.13 está a espiar 55 - 04 (RJFS23)</span>`\n  + cabecalho('Shad0wRA', 'RJFS23') + spy('sword', 1486) + spy('archer', 1558) + spy('bireme', 90);\nconst ESPIA_MA = `<span class=\"subject\">Espião de 126-55-002 (Godfather) descoberto na cidade 45.9</span>`\n  + cabecalho('Godfather', 'Shad0wRA');\n\n(async () => {\n  const L = leitor();\n  {\n    const d = L.lerRelatorio(ATAQUE);\n    t.verifica('ataque recebido: a tropa do atacante e o que perdeu', igual(d.atacante, { rider: 35 })\n      && igual(d.perdasAtacante, { rider: 35 }), d);\n    t.verifica('... e a defesa, com as perdas', d.defensor.bireme === 3110 && d.defensor.sword === 4500\n      && d.perdasDefensor.sword === 13 && !d.perdasDefensor.bireme, d);\n    t.verifica('... quem ataca e quem é atacado', d.jogadorOrigem === 'Godfather' && d.jogadorDestino === 'Shad0wRA', d);\n  }\n  {\n    const d = L.lerRelatorio(MEU_ATAQUE);\n    t.verifica('ataque meu: o atacante sou eu, o defensor é o outro', d.jogadorOrigem === 'Shad0wRA'\n      && d.jogadorDestino === 'RJFS23' && d.atacante.attack_ship === 298 && d.defensor.bireme === 400, d);\n  }\n  {\n    const d = L.lerRelatorio(ESPIA_OK);\n    t.verifica('espionagem certa: a tropa da cidade espiada', igual(d.espiada, { sword: 1486, archer: 1558, bireme: 90 })\n      && !Object.keys(d.atacante).length, d);\n  }\n  {\n    const d = L.lerRelatorio(ESPIA_MA);\n    t.verifica('espião apanhado: sem tropas, mas com o assunto e os jogadores',\n      !Object.keys(d.espiada).length && /descoberto/.test(d.assunto) && d.jogadorOrigem === 'Godfather', d);\n  }\n  {\n    const L2 = leitor();\n    L2.anotar('Vilão', 'atacou', { sword: 100 }, 1000);\n    L2.anotar('Vilão', 'atacou', { sword: 500, rider: 50 }, 2000);\n    L2.anotar('Vilão', 'atacou', { sword: 10 }, 3000);\n    const j = L2.ver()['Vilão'];\n    t.verifica('guarda a maior força que o jogador já trouxe', igual(j.atacou, { sword: 500, rider: 50 })\n      && j.atacouQuando === 2000, j);\n    t.verifica('... e conta as vezes e a última', j.vezes === 3 && j.ultimo === 3000, j);\n    L2.anotar('Vilão', 'espiado', { hoplite: 900 }, 4000);\n    t.verifica('... o que se lhe viu em casa fica à parte', igual(L2.ver()['Vilão'].espiado, { hoplite: 900 })\n      && igual(L2.ver()['Vilão'].atacou, { sword: 500, rider: 50 }));\n    t.verifica('sem tropas não se anota nada', L2.anotar('Outro', 'atacou', {}, 5000) === false && !L2.ver().Outro);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-reserva-nc.js": "/* UM COLONIZADOR GUARDADO POR CONTA, SEMPRE.\n *\n * A reserva só se marcava quando a conta estava DISPONÍVEL — e estar\n * disponível exige ter colonizador. Se a rotação já os tinha gasto (manda-os\n * de 30 em 30 min), a conta nunca ficava disponível, nunca reservava, e nunca\n * entrava numa ilha. Circular.\n *\n *   node ferramentas/teste-reserva-nc.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('RESERVA DE COLONIZADOR');\n\nfunction nucleo() {\n  const loja = {};\n  const ctx = {\n    localStorage: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = v; } },\n    seErroDeCodigo: () => {}, console, Math, Number, Object, JSON, Date,\n  };\n  vm.createContext(ctx);\n  const a = SRC.indexOf('  const QUER_NC_KEY =');\n  const b = SRC.indexOf('\\n  function pareceErro(msg) {', a);\n  vm.runInContext(SRC.slice(a, b) + '\\n({ querNC, jaNaoQuerNC, reservados: quantosNCReservados })', ctx);\n  return ctx;\n}\n\n(async () => {\n  {\n    const n = nucleo();\n    t.verifica('sem reservas: a rotação dispõe de tudo', n.quantosNCReservados('colonos') === 0);\n  }\n  {\n    const n = nucleo();\n    n.querNC('fecharilha', 60, 1);\n    t.verifica('o fechar ilha guarda um: a rotação vê-o reservado',\n      n.quantosNCReservados('colonos') === 1, n.quantosNCReservados('colonos'));\n    t.verifica('... e a fundação também o respeita (prioridade abaixo)',\n      n.quantosNCReservados('fundacao') === 1);\n    t.verifica('... mas o próprio fechar ilha não se bloqueia a si',\n      n.quantosNCReservados('fecharilha') === 0);\n  }\n  {\n    const n = nucleo();\n    n.querNC('fecharilha', 60, 1);\n    n.querNC('fundacao', 45, 1);\n    t.verifica('fechar ilha e fundação: a rotação vê os dois reservados',\n      n.quantosNCReservados('colonos') === 2);\n  }\n  {\n    const n = nucleo();\n    n.querNC('fecharilha', 60, 1);\n    n.jaNaoQuerNC('fecharilha');\n    t.verifica('módulo desligado: larga o colonizador já',\n      n.quantosNCReservados('colonos') === 0);\n  }\n  {\n    const n = nucleo();\n    n.querNC('fecharilha', -1, 1);   // marca já expirada\n    t.verifica('uma marca expirada não bloqueia nada', n.quantosNCReservados('colonos') === 0);\n  }\n  t.secao('A FUNDAÇÃO RESPEITA O QUE ESTÁ GUARDADO');\n  {\n    /* A reserva travava a rotação mas não a fundação: com um colonizador\n     * guardado para fechar ilha, ela mandou-o fundar noutro sítio (15/09). */\n    t.verifica('a fundação consulta as reservas antes de fundar',\n      /quantosNCReservados\\('fundacao'\\)/.test(SRC.slice(SRC.indexOf('O QUE ESTÁ GUARDADO NÃO SE GASTA'),\n        SRC.indexOf('O QUE ESTÁ GUARDADO NÃO SE GASTA') + 2500)));\n    t.verifica('... e não funda se o único colonizador estiver guardado',\n      /emCasa - guardados < 1/.test(SRC));\n    t.verifica('a última vaga de cidade também fica para o fechar ilha',\n      /sobram <= 1/.test(SRC) && /__maestroFecharIlhaEspera/.test(SRC));\n    t.verifica('... e a marca caduca, para não travar a fundação para sempre',\n      /Date\\.now\\(\\) - espera\\) < 15 \\* 60 \\* 1000/.test(SRC));\n  }\n  t.secao('A ROTAÇÃO DESCONTA MESMO A RESERVA');\n  {\n    /* A reserva era calculada e escrita na rotina — e a seguir mandava-se\n     * tudo. O fechar ilha ficou sem colonizador com a reserva activa\n     * (15/09). */\n    const i = SRC.indexOf('O QUE ESTÁ RESERVADO FICA MESMO EM CASA');\n    const bloco = SRC.slice(i, i + 1600);\n    t.verifica('a rotação guarda o número reservado', i > 0\n      && /let porGuardar = Math\\.max\\(0, Number\\(reservados\\) \\|\\| 0\\);/.test(bloco));\n    t.verifica('... deixando-o em casa antes de mandar o resto',\n      /const fica = Math\\.min\\(porGuardar, temAqui\\);/.test(bloco)\n      && /const n = temAqui - fica;/.test(bloco));\n    t.verifica('... e conta por CONTA, não por cidade',\n      /porGuardar -= fica;/.test(bloco));\n    t.verifica('uma cidade que fica só com os reservados não envia nada',\n      /if \\(n <= 0\\) \\{/.test(bloco) && /estão reservados/.test(bloco));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-revolta-colonizador.js": "/* NUM MUNDO DE REVOLTA, O COLONIZADOR TEM HORA.\n *\n * Só entra na R2. Logo: uma cidade que não está em revolta não pode receber\n * colonizador, e uma que está só dentro da janela da R2.\n *\n * Sem isto, todos os ataques da mesma ilha eram tratados como podendo trazer\n * colonizador — na mesma ilha não há distância e não se mede velocidade\n * (6200) — e a esquiva deixava a tropa em casa \"para o matar\". Numa revolta o\n * adversário ataca da mesma ilha vezes sem conta: nove alarmes seguidos em\n * duas cidades (visto em jogo, 17/09).\n *\n *   node ferramentas/teste-revolta-colonizador.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('REVOLTA E COLONIZADOR');\n\nconst AGORA = 1000000;\n\n/* `defs` = as fases de revolta que o jogo carrega. */\nfunction montar(defs) {\n  const ctx = {\n    mUw: { MM: { getModels: () => (defs === null ? {} : { MovementsRevoltDefender: defs }) } },\n    agoraJogo: () => AGORA,\n    Number, Object, console,\n  };\n  vm.createContext(ctx);\n  const i = SRC.indexOf('      const mundoDeRevolta = (() => {');\n  const f = SRC.indexOf('\\n      let temNC =', i);\n  return vm.runInContext('(() => {\\n' + SRC.slice(i, f).replace(/^ {6}/gm, '')\n    + '\\nreturn { revolta: mundoDeRevolta, janela: janelaDoColonizador };\\n})()', ctx);\n}\n\nconst fase = (alvo, r1) => ({\n  attributes: { target_town_id: alvo, finished_at: AGORA + 3600, arising: r1 },\n});\n\n(async () => {\n  {\n    const a = montar(null);\n    t.verifica('sem a colecção, o mundo é de cerco', a.revolta === false);\n  }\n  {\n    const a = montar({});\n    t.verifica('com a colecção, o mundo é de revolta', a.revolta === true);\n  }\n  {\n    /* A cidade não está em revolta: não pode vir colonizador. */\n    const a = montar({ x: fase(999, false) });\n    t.verifica('cidade sem revolta: o colonizador NÃO pode entrar', a.janela(500) === false);\n  }\n  {\n    /* Em R1: ainda não. */\n    const a = montar({ x: fase(500, true) });\n    t.verifica('cidade em R1: ainda não pode', a.janela(500) === false);\n  }\n  {\n    /* Em R2: pode. */\n    const a = montar({ x: fase(500, false) });\n    t.verifica('cidade em R2: aí sim', a.janela(500) === true);\n  }\n  {\n    /* Duas fases, uma em R1 e outra em R2: basta uma em R2. */\n    const a = montar({ x: fase(500, true), y: fase(500, false) });\n    t.verifica('duas revoltas na mesma cidade: basta uma em R2', a.janela(500) === true);\n  }\n  {\n    /* Uma revolta que já acabou não conta. */\n    const velha = { attributes: { target_town_id: 500, finished_at: AGORA - 10, arising: false } };\n    const a = montar({ x: velha });\n    t.verifica('revolta acabada: não conta', a.janela(500) === false);\n  }\n\n  t.secao('O QUE MUDA NA DECISÃO');\n  {\n    t.verifica('só se desliga a suspeita em mundos de revolta',\n      /if \\(temNC && mundoDeRevolta\\) \\{/.test(SRC));\n    t.verifica('... e só quando a janela diz que não pode',\n      /if \\(pode === false\\) \\{\\s*\\n\\s*temNC = false;/.test(SRC));\n    t.verifica('a mensagem passa a dizer \"PODE trazer\"',\n      /PODE trazer colonizador e não consigo trazer a tropa a tempo/.test(SRC));\n    t.verifica('e a janela de cancelamento vem do jogo',\n      /\\(\\(mUw\\.GameData \\|\\| \\{\\}\\)\\.cancel_times \\|\\| \\{\\}\\)\\.unit_movements/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-revoltas-minhas.js": "/* A REVOLTA QUE EU LANÇO NÃO É PARA APOIAR.\n *\n * O `revoltasPelosModelos` escrevia `destination_town_player_id: eu` — dava o\n * destino como meu fosse de quem fosse. O filtro que exige \"o destino é meu e\n * a origem não\" passava sempre a dar certo por construção.\n *\n * Visto em jogo (17/09): as cidades 55.18 e 45.9, de onde o Rafa lançou\n * revoltas contra o Jomaras, entraram na lista de apoio e as vinte multis\n * mandaram tropa para elas. O aviso dizia \"em revolta por ?\" — o \"?\" era ele.\n *\n *   node ferramentas/teste-revoltas-minhas.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('REVOLTAS — QUEM LANÇOU');\nconst AP = 'function makeApoioModule(opts)';\n\nconst EU = 111;\n\n/* `defs` são as fases de revolta; `takeover` diz quem as lançou. */\nfunction ler(defs, takeover, agora) {\n  const ctx = {\n    mUw: {\n      Game: { player_id: EU },\n      MM: { getModels: () => ({ MovementsRevoltDefender: defs, Takeover: takeover }) },\n    },\n    seErroDeCodigo: () => {}, console, Number, String, Object,\n  };\n  vm.createContext(ctx);\n  const f = vm.runInContext(funcao(SRC, '  function revoltasPelosModelos(agoraS) {', AP)\n    + '\\nrevoltasPelosModelos', ctx);\n  return f(agora);\n}\n\nconst agora = 1000000;\nconst fase = (rid, alvo, dono) => ({\n  attributes: { revolt_id: rid, target_town_id: alvo, finished_at: agora + 3600,\n    started_at: agora - 600, player_id: dono, town_name: 'cidade ' + alvo, arising: false },\n});\nconst quem = (rid, jogador, nome) => ({\n  attributes: { command: { id: rid, type: 'revolt' },\n    origin_town: { player_id: jogador, player_name: nome } },\n});\n\n(async () => {\n  {\n    /* Um adversário revolta uma cidade minha: é para apoiar. */\n    const r = ler({ a: fase(7, 500, EU) }, { t: quem(7, 999, 'Jomaras') }, agora);\n    t.verifica('revolta do adversário numa cidade minha: entra', r.lista.length === 1, r.lista);\n    t.verifica('... com o nome de quem a lançou',\n      r.lista[0] && r.lista[0].origin_player_name === 'Jomaras', r.lista[0]);\n  }\n  {\n    /* Eu revolto uma cidade dele: NÃO é para apoiar. */\n    const r = ler({ a: fase(8, 600, 999) }, { t: quem(8, EU, 'Eu') }, agora);\n    t.verifica('revolta que EU lancei: fica de fora', r.lista.length === 0, r.lista);\n  }\n  {\n    /* Sem saber quem lançou, não se arrisca. */\n    const r = ler({ a: fase(9, 700, EU) }, {}, agora);\n    t.verifica('sem saber quem a lançou: não arrisca', r.lista.length === 0, r.lista);\n  }\n  {\n    const r = ler({ a: fase(10, 800, EU) }, { t: quem(10, 999, 'Jomaras') }, agora + 99999);\n    t.verifica('revolta já acabada: esquecida', r.lista.length === 0, r.lista);\n  }\n  {\n    const r = ler({ a: fase(11, 900, EU) }, { t: quem(11, 999, 'X') }, agora);\n    /* Isto vem da colecção das revoltas em que sou o DEFENSOR: a cidade é\n     * minha, sempre. Na 0700 li o dono do `player_id`, que é o jogador que\n     * REVOLTA — e as revoltas das multis deixaram de chegar à lista\n     * partilhada (17/09: a 5105 da MacaquinhoChinês, revoltada pelo\n     * 2438668). */\n    t.verifica('o dono do destino sou eu, mesmo quando o player_id é do atacante',\n      r.lista[0] && r.lista[0].destination_town_player_id === EU, r.lista[0]);\n  }\n  {\n    /* O caso real: o `player_id` da fase é o do atacante. */\n    const faseComAtacante = {\n      attributes: { revolt_id: 20, target_town_id: 5105, finished_at: agora + 3600,\n        started_at: agora - 600, player_id: 2438668, town_name: '5105', arising: true },\n    };\n    const r = ler({ a: faseComAtacante }, { t: quem(20, 2438668, 'Outro') }, agora);\n    t.verifica('a revolta da própria conta entra na lista', r.lista.length === 1, r.lista);\n    t.verifica('... com o destino marcado como meu',\n      r.lista[0] && r.lista[0].destination_town_player_id === EU, r.lista[0]);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-semantica-leitura.js": "/* TODA A LEITURA DIZ O QUE É.\n *\n * Uma lista vazia pode querer dizer \"não há nada\" ou \"não consegui ler\".\n * Confundi-las custou caro, e sempre da mesma maneira: as sentinelas a\n * concluir \"está a descoberto\" sem saber; o reforço a dar tropa por perdida\n * com modelos incompletos; o apoio a decidir retiradas com números da Ágora\n * de cinco horas antes; a esquiva a tomar falta de dados por ausência de\n * ataque. Quatro módulos, o mesmo buraco (15-17/09).\n *\n * Agora uma leitura traz quando foi feita, se está completa e de onde veio —\n * e há uma regra única: não se age sobre uma leitura incompleta ou velha.\n *\n *   node ferramentas/teste-semantica-leitura.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('SEMÂNTICA DA LEITURA');\n\nfunction api() {\n  const ctx = { Date, Number, console };\n  vm.createContext(ctx);\n  const i = SRC.indexOf('  function leitura(valor, opcoes) {');\n  const f = SRC.indexOf('\\n  try {\\n    uw.__maestroLeitura', i);\n  return vm.runInContext('(() => {\\n' + SRC.slice(i, f)\n    + '\\nreturn { nova: leitura, podeAgir: podeAgirCom, porque: porqueNaoPosso };\\n})()', ctx);\n}\n\n(async () => {\n  const a = api();\n  {\n    const l = a.nova([1, 2, 3]);\n    t.verifica('uma leitura normal traz os dados', l.valor.length === 3 && l.ok);\n    t.verifica('... e diz-se completa por omissão', l.completa === true);\n    t.verifica('... com a hora e a origem', l.quando > 0 && l.origem === 'servidor', l);\n    t.verifica('e pode agir-se com ela', a.podeAgir(l) === true);\n  }\n  {\n    /* O caso que custou caro: lista vazia mas leitura boa. */\n    const l = a.nova([], { completa: true });\n    t.verifica('lista vazia com leitura completa: pode agir-se',\n      a.podeAgir(l) === true && l.valor.length === 0);\n  }\n  {\n    /* E o inverso: lista vazia porque não se conseguiu ler. */\n    const l = a.nova([], { ok: false, completa: false, razao: 'sem Administrador' });\n    t.verifica('lista vazia por falha: NÃO se age', a.podeAgir(l) === false);\n    t.verifica('... e diz-se porquê', /Administrador/.test(a.porque(l)), a.porque(l));\n  }\n  {\n    const l = a.nova([1], { completa: false });\n    t.verifica('leitura incompleta: não se age', a.podeAgir(l) === false);\n    t.verifica('... e diz-se que está incompleta', /incompleta/.test(a.porque(l)), a.porque(l));\n  }\n  {\n    const velha = a.nova([1], { quando: Date.now() - 3600 * 1000 });\n    t.verifica('leitura de há uma hora, com validade de 35 min: não se age',\n      a.podeAgir(velha, 35 * 60 * 1000) === false);\n    t.verifica('... e diz há quanto tempo é', /60 min/.test(a.porque(velha, 35 * 60 * 1000)),\n      a.porque(velha, 35 * 60 * 1000));\n    t.verifica('sem validade pedida, a idade não conta', a.podeAgir(velha) === true);\n  }\n  {\n    t.verifica('sem leitura nenhuma: não se age', a.podeAgir(null) === false);\n  }\n\n  t.secao('QUEM JÁ A USA');\n  {\n    t.verifica('a visão geral diz se está completa e de onde veio',\n      /completa: true,\\s*\\n\\s*origem: daCopia \\? 'copia' : 'servidor',/.test(SRC));\n    t.verifica('... e uma falha marca-se como incompleta',\n      /completa: false, origem: 'servidor',/.test(SRC));\n    t.verifica('as sentinelas perguntam se podem agir',\n      /if \\(l && !l\\.podeAgir\\(daAgora\\)\\) return null;/.test(SRC));\n    t.verifica('... e mantêm a regra antiga se a semântica faltar',\n      /if \\(!l && !frescas\\) return null;/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-sentinelas.js": "/* SENTINELAS — não mandar outra só porque não se viu a que lá está.\n *\n * A leitura da Ágora cobre só ALGUMAS das minhas cidades de cada vez. Uma\n * sentinela enviada de uma cidade por ler não aparece — e concluir daí que a\n * aliada está a descoberto punha lá outra, e outra: apareceram cidades com 15\n * sentinelas (visto em jogo, 13/09). O `tenhoTropaEm` REAL.\n *\n *   node ferramentas/teste-sentinelas.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('SENTINELAS');\nconst SE = 'function makeSentinelasModule(opts)';\n\n/* As minhas cidades são 111 e 222. `porAlvo` é o que a Ágora deu; `lidas` são\n * as minhas cidades que essa leitura cobre; `modelos` é o que a página tem. */\nfunction montar(porAlvo, lidas, modelos) {\n  const ctx = {\n    mUw: {\n      ITowns: { towns: { 111: {}, 222: {} } },\n      MM: { getModels: () => ({ Units: modelos || {} }) },\n      __maestroApoioFora: porAlvo === undefined ? undefined\n        : { porAlvo: () => porAlvo, lidas: () => lidas || [] },\n    },\n    seErroDeCodigo: () => {}, console, Date, Number,\n  };\n  /* A semântica das leituras, que o núcleo expõe: uma leitura diz quando foi\n   * feita, se está completa e de onde veio, e o módulo pergunta se pode agir\n   * com ela (17/09). */\n  ctx.window = {\n    __maestroLeitura: (() => {\n      const i = SRC.indexOf('  function leitura(valor, opcoes) {');\n      const f = SRC.indexOf('\\n  try {\\n    uw.__maestroLeitura', i);\n      const c = {}; vm.createContext(c);\n      return vm.runInContext('(() => {\\n' + SRC.slice(i, f)\n        + '\\nreturn { nova: leitura, podeAgir: podeAgirCom, porque: porqueNaoPosso };\\n})()', c);\n    })(),\n  };\n  vm.createContext(ctx);\n  return vm.runInContext(funcao(SRC, '  function tenhoTropaEm(townId) {', SE)\n    + funcao(SRC, '  function tenhoTropaEmPelosModelos(townId) {', SE) + '\\ntenhoTropaEm', ctx);\n}\n\nconst COM_SENTINELA = { 9001: { unidades: { sword: 3 } } };\nconst MODELO_LA = { u1: { attributes: { id: 1, home_town_id: 111, current_town_id: 9001, sword: 3 } } };\n\n(async () => {\n  {\n    const f = montar(COM_SENTINELA, [111, 222]);\n    t.verifica('a sentinela aparece na leitura: está lá', f(9001) === true);\n  }\n  {\n    const f = montar({}, [111, 222]);\n    t.verifica('leitura completa e sem nada lá: está mesmo a descoberto', f(9001) === false);\n  }\n  {\n    /* A pergunta é sobre a ALIADA, não sobre as minhas cidades: basta haver\n     * leitura fresca. Exigir a conta toda lida parava o módulo (15/09). */\n    const f = montar({}, [111]);\n    t.verifica('leitura fresca de uma cidade minha: já chega para decidir', f(9001) === false);\n  }\n  {\n    const f = montar({}, []);\n    t.verifica('sem nenhuma leitura fresca: não sei', f(9001) === null);\n  }\n  {\n    const f = montar(null, []);\n    t.verifica('sem leitura nenhuma: não sei', f(9001) === null);\n  }\n  {\n    const f = montar(undefined);\n    t.verifica('sem a Ágora sequer: não sei', f(9001) === null);\n  }\n  {\n    const f = montar({}, [111], MODELO_LA);\n    t.verifica('os modelos mostram a tropa lá: chega para dizer que está', f(9001) === true);\n  }\n  {\n    const f = montar(COM_SENTINELA, [111, 222]);\n    t.verifica('outra cidade aliada, essa vazia: está a descoberto', f(9002) === false);\n  }\n  t.secao('AS ALIADAS VÊM DO MAPA DO MUNDO');\n  {\n    /* Era um pedido ao jogo por cada ilha: com 48 ilhas, 48 pedidos a\n     * concorrer com tudo o resto (17/09). */\n    const i = SRC.indexOf('PRIMEIRO OS FICHEIROS DO SERVIDOR');\n    const bloco = SRC.slice(i, i + 1800);\n    t.verifica('as sentinelas lêem o mapa antes de perguntar ao jogo', i > 0\n      && /const m = await api\\.ler\\(\\);/.test(bloco));\n    t.verifica('... procuram a ilha pelas coordenadas',\n      /m\\.porIlha\\[coords\\.x \\+ ':' \\+ coords\\.y\\]/.test(bloco));\n    t.verifica('... saltam as minhas cidades e quem não tem aliança',\n      /if \\(c\\.dono === eu\\) continue;/.test(bloco) && /if \\(!j \\|\\| !j\\.alianca\\) continue;/.test(bloco));\n    t.verifica('... e só contam as alianças amigas',\n      /if \\(!nomeAl \\|\\| !amigas\\.has\\(nomeAl\\)\\) continue;/.test(bloco));\n    t.verifica('se o mapa não trouxer nada, pergunta-se ao jogo como antes',\n      /island_info\\?town_id=/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-silencios.js": "/* ACÇÕES QUE RESPONDEM CALADAS, E ESCRITAS QUE FALHAM EM SILÊNCIO.\n *\n * \"Não veio erro\" contava por feito, e um `catch` vazio à volta de uma\n * escrita perdia definições sem dizer nada. Nenhuma das duas coisas mudava de\n * comportamento — mudavam de visibilidade, que é o primeiro passo para as\n * corrigir com dados.\n *\n *   node ferramentas/teste-silencios.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('SILÊNCIOS');\n\nfunction nucleo() {\n  const caixa = [];\n  const ctx = {\n    uw: {}, guardarNaCaixa: (m, txt) => caixa.push(txt), console, Object, Number, String,\n  };\n  vm.createContext(ctx);\n  const a = SRC.indexOf('  const respostasMudas = {};');\n  const b = SRC.indexOf('\\n  function seErroDeCodigo(e, onde) {', a);\n  vm.runInContext(SRC.slice(a, b), ctx);\n  return { ctx, caixa };\n}\n\n(async () => {\n  {\n    const n = nucleo();\n    n.ctx.anotarRespostaMuda('https://pt126.grepolis.com/game/building_barracks?town_id=1&action=build&h=X');\n    t.verifica('regista a acção que respondeu calada',\n      n.ctx.uw.__maestroRespostasMudas()['building_barracks:build'] === 1,\n      n.ctx.uw.__maestroRespostasMudas());\n    t.verifica('... e deixa uma linha na caixa, uma só',\n      n.caixa.length === 1 && /sem confirmação/.test(n.caixa[0]), n.caixa);\n    n.ctx.anotarRespostaMuda('https://pt126.grepolis.com/game/building_barracks?town_id=1&action=build&h=X');\n    t.verifica('a segunda vez conta mas não repete a linha',\n      n.ctx.uw.__maestroRespostasMudas()['building_barracks:build'] === 2 && n.caixa.length === 1);\n  }\n  {\n    const n = nucleo();\n    n.ctx.anotarRespostaMuda('https://x/game/town_info?action=send_units&h=Y');\n    n.ctx.anotarRespostaMuda('https://x/game/frontend_bridge?action=execute&h=Y');\n    t.verifica('acções diferentes ficam separadas',\n      Object.keys(n.ctx.uw.__maestroRespostasMudas()).length === 2,\n      n.ctx.uw.__maestroRespostasMudas());\n  }\n  {\n    /* Uma escrita que falha por falta de espaço passa a ser reportada. */\n    const vistos = [];\n    const ctx = { log: (m, txt) => vistos.push(txt), errosJaVistos: new Set(), console };\n    vm.createContext(ctx);\n    const i = SRC.indexOf('  function seErroDeCodigo(e, onde) {');\n    const f = SRC.indexOf('\\n  }\\n', i) + 4;\n    vm.runInContext(SRC.slice(i, f) + '\\nseErroDeCodigo', ctx);\n    ctx.seErroDeCodigo(new Error('QuotaExceededError: persistent storage'), 'Apoio');\n    t.verifica('falha a guardar: reportada', vistos.some((x) => /Apoio/.test(x)), vistos);\n    ctx.seErroDeCodigo(new Error('coisa qualquer prevista'), 'Apoio');\n    t.verifica('falha prevista: continua em silêncio', vistos.length === 1, vistos);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-tipo-mundo.js": "/* CADA MÓDULO NO SEU TIPO DE MUNDO.\n *\n * O apoio distribuído só faz sentido onde há revoltas para aguentar; o partir\n * cercos só onde há cercos. Ter os dois na barra em todo o lado confundia, e\n * um deles estava sempre a correr sem ter o que fazer (18/09).\n *\n * O tipo descobre-se no jogo: só os mundos de revolta carregam a colecção\n * `MovementsRevoltDefender` — confirmado no pt126 (tem) e no pt125 (não tem).\n *\n *   node ferramentas/teste-tipo-mundo.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('TIPO DE MUNDO');\n\nfunction montar(deRevolta, mundo) {\n  const ctx = {\n    WORLD: mundo || 'pt126',\n    uw: {\n      /* Um mundo real tem sempre dezenas de modelos carregados; o que\n       * distingue é a presença da colecção das revoltas. */\n      MM: { getModels: () => (deRevolta === null ? null\n        : (deRevolta\n          ? { Town: {}, Units: {}, MovementsRevoltDefender: {} }\n          : { Town: {}, Units: {} })) },\n    },\n    console,\n  };\n  vm.createContext(ctx);\n  /* O `tipoSabido` guarda a resposta: os modelos podem ser recarregados e\n   * ficar por instantes sem a colecção das revoltas, e isso faria um mundo de\n   * revolta parecer de cerco (18/09). */\n  const i = SRC.indexOf('  let tipoSabido = \\'\\';');\n  const f = SRC.indexOf('\\n  try { uw.__maestroTipoDoMundo', i);\n  return vm.runInContext('(() => {\\n' + SRC.slice(i, f)\n    + '\\nreturn { tipo: tipoDoMundo, aplica: modAplicaAoMundo };\\n})()', ctx);\n}\n\n(async () => {\n  t.secao('O TIPO');\n  {\n    t.verifica('com a colecção das revoltas, é de revolta', montar(true).tipo() === 'revolta');\n    t.verifica('sem ela, é de cerco', montar(false).tipo() === 'cerco');\n  }\n\n  t.secao('QUEM CORRE ONDE');\n  {\n    const r = montar(true);\n    t.verifica('num mundo de revolta, o apoio corre',\n      r.aplica({ id: 'apoio', tipoDeMundo: 'revolta' }) === true);\n    t.verifica('... e o partir cercos não',\n      r.aplica({ id: 'partircerco', tipoDeMundo: 'cerco' }) === false);\n  }\n  {\n    const c = montar(false);\n    t.verifica('num mundo de cerco, o partir cercos corre',\n      c.aplica({ id: 'partircerco', tipoDeMundo: 'cerco' }) === true);\n    t.verifica('... e o apoio não',\n      c.aplica({ id: 'apoio', tipoDeMundo: 'revolta' }) === false);\n  }\n  {\n    const r = montar(true);\n    t.verifica('um módulo sem tipo corre em todo o lado',\n      r.aplica({ id: 'construcao' }) === true);\n  }\n  {\n    /* Se não se souber o tipo, mais vale um módulo a mais do que a menos.\n     * Acontece no arranque, antes de o jogo carregar os modelos: devolver\n     * \"cerco\" fazia o apoio desaparecer da barra num mundo de revolta\n     * (apanhado em teste, 18/09). */\n    const x = montar(null);\n    t.verifica('sem modelos, o tipo fica por saber', x.tipo() === '');\n    t.verifica('... e deixa-se passar tudo',\n      x.aplica({ id: 'apoio', tipoDeMundo: 'revolta' }) === true\n      && x.aplica({ id: 'partircerco', tipoDeMundo: 'cerco' }) === true);\n  }\n  {\n    const r = montar(true, 'pt126');\n    t.verifica('a lista de mundos continua a valer',\n      r.aplica({ id: 'x', worlds: ['pt999'] }) === false);\n    t.verifica('... e combina-se com o tipo',\n      r.aplica({ id: 'x', worlds: ['pt126'], tipoDeMundo: 'revolta' }) === true);\n  }\n\n  t.secao('OS MÓDULOS ESTÃO MARCADOS');\n  {\n    t.verifica('o apoio é de revolta',\n      /nome: 'Apoio distribuído',[\\s\\S]{0,400}tipoDeMundo: 'revolta',/.test(SRC));\n    t.verifica('o partir cercos é de cerco',\n      /nome: 'Partir cercos',[\\s\\S]{0,300}tipoDeMundo: 'cerco',/.test(SRC));\n  }\n  t.secao('QUANDO O TIPO SÓ SE SABE DEPOIS');\n  {\n    /* A barra é desenhada no arranque, e nessa altura os modelos ainda não\n     * estão carregados: passavam os módulos todos e ficava o Apoio na barra de\n     * um mundo de cerco. Reabrir o painel não o tirava, porque a lista já\n     * estava feita (18/09). */\n    t.verifica('a barra refaz-se quando o tipo passa a ser conhecido',\n      /O TIPO DO MUNDO SÓ SE SABE DEPOIS DE O JOGO CARREGAR/.test(SRC)\n      && /if \\(tipoDoMundo\\(\\)\\) \\{ clearInterval\\(espreitar\\); desenhar\\(\\); return; \\}/.test(SRC));\n    t.verifica('... e desiste ao fim de um minuto',\n      /if \\(tentativas > 60\\) clearInterval\\(espreitar\\);/.test(SRC));\n    t.verifica('uma vez sabido, não se volta a perguntar',\n      /if \\(tipoSabido\\) return tipoSabido;/.test(SRC)\n      && /tipoSabido = m\\.MovementsRevoltDefender \\? 'revolta' : 'cerco';/.test(SRC));\n  }\n  {\n    /* E a resposta guardada não muda se os modelos desaparecerem. */\n    const a = montar(true);\n    t.verifica('o tipo guardado resiste a uma recarga dos modelos',\n      a.tipo() === 'revolta' && a.tipo() === 'revolta');\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-tropa-fora.js": "/* QUEM MEXE NA TROPA QUE ESTÁ FORA DE CASA.\n *\n * Cinco módulos põem tropa em cidades que não são a de origem — apoio,\n * reforço sob ataque, sentinelas, esquiva e rotação de colonos. Este ficheiro\n * verifica que não se estragam uns aos outros.\n *\n *   node ferramentas/teste-tropa-fora.js maestro.user.js\n */\nconst S = require('./simulador');\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('TROPA FORA DE CASA');\n\nconst entre = (a, b) => {\n  const i = SRC.indexOf(a);\n  return i < 0 ? '' : SRC.slice(i, b ? SRC.indexOf(b, i) : i + 3000);\n};\n\n(async () => {\n  t.secao('O APOIO');\n  {\n    const bloco = entre('O QUE NÃO É DO APOIO NÃO SE MEXE', 'for (const cidade of ondeTenho)');\n    t.verifica('retira de alvos que já não estão na lista', bloco.length > 0);\n    t.verifica('... mas não toca nas sentinelas, que têm registo próprio',\n      (SRC.match(/doSentinelas\\.has\\(onde\\)/g) || []).length === 2\n      && /grepoSentinelas_enviadas_v1/.test(SRC));\n    t.verifica('... nem no reforço sob ataque',\n      (SRC.match(/doReforco\\.has\\(onde\\)/g) || []).length === 2);\n    t.verifica('só as MULTIS retiram o que não está no registo do apoio',\n      (SRC.match(/!enviadoPorMim\\.has\\(onde\\) && !souMulti\\(\\)/g) || []).length === 2);\n    t.verifica('... e quem decide é o perfil',\n      /String\\(esc\\.perfil \\|\\| ''\\)\\.toLowerCase\\(\\) === 'multi'/.test(SRC));\n    t.verifica('... nem nos colonizadores da rotação',\n      /if \\(\\(Number\\(a\\.colonize_ship\\) \\|\\| 0\\) > 0\\) continue;/.test(SRC));\n    t.verifica('... nem nas bases dos colonos',\n      (SRC.match(/doColonos\\.has\\(onde\\)/g) || []).length >= 2);\n  }\n\n  t.secao('O REFORÇO SOB ATAQUE');\n  {\n    t.verifica('não traz um bloco que tenha tropa de outros',\n      /tem em \\$\\{nomeDe\\(e\\.destino\\)\\} mais do que o reforço/.test(SRC));\n    t.verifica('retira pela hora marcada no envio, não por leitura',\n      /const horaOrdem = Number\\(e\\.retirarAs\\)/.test(SRC));\n    t.verifica('e não defende contra as minhas próprias contas',\n      /NÃO SE DEFENDE DE SI PRÓPRIO/.test(SRC));\n  }\n\n  t.secao('AS SENTINELAS');\n  {\n    t.verifica('não aparecem como defesa no painel da frota',\n      /AS SENTINELAS NÃO SÃO DEFESA/.test(SRC) && /\\.filter\\(\\(l\\) => l\\.total >= 10\\)/.test(SRC));\n    t.verifica('só decidem com leitura fresca da Ágora',\n      /const frescas = \\(\\(api\\.lidas && api\\.lidas\\(35 \\* 60 \\* 1000\\)\\) \\|\\| \\[\\]\\)\\.length;/.test(SRC));\n  }\n\n  t.secao('A ESQUIVA E OS COLONOS');\n  {\n    t.verifica('a esquiva não usa cidades com envio agendado do reforço',\n      /TROPA JÁ COMPROMETIDA NÃO SE MANDA/.test(SRC));\n    t.verifica('a rotação de colonos respeita os colonizadores reservados',\n      /O QUE ESTÁ RESERVADO FICA MESMO EM CASA/.test(SRC));\n    t.verifica('e a fundação também',\n      /O QUE ESTÁ GUARDADO NÃO SE GASTA/.test(SRC));\n  }\n  t.secao('OS PEDIDOS E O PAINEL');\n  {\n    /* Um pedido de reforçar para uma cidade que saiu da lista não tem onde ser\n     * entregue, e mantinha as contas a mandar tropa (16/09). */\n    t.verifica('os pedidos de alvos fora da lista apagam-se',\n      /E OS PEDIDOS DE REFORÇAR OU REPOR/.test(SRC)\n      && /if \\(alvoP && !vivos2\\.has\\(alvoP\\)\\) \\{ delete pend\\[k\\]; mexeu2 = true; \\}/.test(SRC));\n    /* O Apoio fala com o Firebase pelo `fbLerM`/`fbEscreverM`. Chamei um\n     * `fb()` que não existe lá e o módulo rebentou (16/09). */\n    t.verifica('... usando o acesso ao Firebase que o Apoio tem',\n      /const pend = \\(await fbLerM\\(fbCaminhoPedidos\\(\\)\\)\\) \\|\\| \\{\\};/.test(SRC)\n      && /await fbEscreverM\\(fbCaminhoPedidos\\(\\), pend\\);/.test(SRC));\n    {\n      const a = SRC.indexOf('function makeApoioModule');\n      const b = SRC.indexOf('\\nfunction make', a + 10);\n      t.verifica('... e não sobra nenhuma chamada a fb() no módulo',\n        !/[^a-zA-Z_.]fb\\(\\)/.test(SRC.slice(a, b).replace(/\\/\\*[\\s\\S]*?\\*\\//g, '')));\n    }\n    t.verifica('o painel da frota separa esta conta da frota inteira',\n      /function htmlInventarioDaConta\\(\\)/.test(SRC)\n      && /caixa\\.innerHTML = \\(qual === 'conta'\\) \\? htmlInventarioDaConta\\(\\) : htmlInventario\\(contas\\);/.test(SRC));\n    t.verifica('... e lembra-se da aba escolhida',\n      /localStorage\\.setItem\\('grepoFrota_aba_v1', qual\\)/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-vigia-mudo.js": "/* VIGIA — um módulo que corre e não faz nada.\n *\n * A frota já dizia quando cada módulo correu; correr não é fazer. A recolha a\n * render zero e o fechar ilha a ver vagas a mais passaram horas a correr sem\n * produzir nada e ninguém deu por isso (12/09). O núcleo passa a marcar a hora\n * de cada linha de ECRÃ (as de rotina não contam) e o vigia avisa.\n *\n *   node ferramentas/teste-vigia-mudo.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('VIGIA — MÓDULO MUDO');\n\n/* A marcação no núcleo. */\nfunction nucleo() {\n  const loja = {};\n  const ctx = {\n    localStorage: { getItem: (k) => loja[k] || null, setItem: (k, v) => { loja[k] = v; } },\n    setInterval: () => 0, uw: {}, seErroDeCodigo: () => {},\n  };\n  vm.createContext(ctx);\n  vm.runInContext(tira(SRC, '  /* A última vez que cada módulo fez alguma coisa', '  const MODULES = [];'), ctx);\n  return ctx;\n}\n\n/* O troço do vigia que decide quem está mudo. */\nfunction vigia(modulos, agora) {\n  const ctx = { seErroDeCodigo: () => {}, agora, x: { modulos } };\n  vm.createContext(ctx);\n  const txt = tira(SRC, '  const VIGIADOS = {', '  };\\n')\n    + 'const parados = [];\\n'\n    + tira(SRC, '      try {\\n        for (const id of Object.keys(VIGIADOS)) {', '      } catch (e) { seErroDeCodigo(e, \\'Frota\\'); }\\n')\n    + '\\nparados';\n  return vm.runInContext(txt, ctx);\n}\n\nconst h = (n) => Math.floor(Date.now() / 1000) - n * 3600;\nconst agora = Math.floor(Date.now() / 1000);\n\n(async () => {\n  {\n    const n = nucleo();\n    n.marcarFeito('aldeias');\n    const antes = n.uw.__maestroUltimoFeito().aldeias;\n    t.verifica('marcar: guarda a hora do módulo', antes > 0 && Math.abs(Date.now() - antes) < 2000, antes);\n    n.marcarFeito('apoio');\n    t.verifica('... por módulo, sem misturar', igual(Object.keys(n.uw.__maestroUltimoFeito()).sort(), ['aldeias', 'apoio']));\n  }\n  {\n    t.verifica('aldeias a correr e a fazer: nada a dizer',\n      igual(vigia({ aldeias: { a: 1, u: agora - 300, f: agora - 600 } }, agora), []));\n    /* Três horas era pouco: com a opção de 10 minutos e as aldeias em fases\n     * diferentes, há períodos legítimos sem nada pronto, e o vigia disparava\n     * dezenas de vezes por hora em todas as contas (16/09). */\n    t.verifica('aldeias caladas 4 h: ainda não avisa',\n      igual(vigia({ aldeias: { a: 1, u: agora - 300, f: h(4) } }, agora), []));\n    t.verifica('aldeias caladas 7 h: aí sim',\n      igual(vigia({ aldeias: { a: 1, u: agora - 300, f: h(7) } }, agora), ['aldeias']));\n    t.verifica('aldeias desligadas: não avisa',\n      igual(vigia({ aldeias: { a: 0, u: agora - 300, f: h(9) } }, agora), []));\n    t.verifica('módulo que nem está a correr: não avisa (é outro problema)',\n      igual(vigia({ aldeias: { a: 1, u: h(5), f: h(9) } }, agora), []));\n    t.verifica('nunca fez nada desde o arranque: não avisa (f a zero)',\n      igual(vigia({ aldeias: { a: 1, u: agora - 300, f: 0 } }, agora), []));\n    t.verifica('recrutamento calado 13 h: ainda não (pode estar à espera de recursos)',\n      igual(vigia({ recrutamento: { a: 1, u: agora - 300, f: h(13) } }, agora), []));\n    t.verifica('recrutamento calado 25 h: avisa',\n      igual(vigia({ recrutamento: { a: 1, u: agora - 300, f: h(25) } }, agora), ['recrutamento']));\n    /* O tique só trabalha quando há moedas: calado não é avaria. */\n    t.verifica('tique calado há dias: NÃO avisa',\n      igual(vigia({ tique: { a: 1, u: agora - 60, f: h(48) } }, agora), []));\n    t.verifica('módulos que passam dias sem ter o que fazer não são vigiados',\n      igual(vigia({ expansao: { a: 1, u: agora - 300, f: h(48) },\n        fecharilha: { a: 1, u: agora - 300, f: h(48) } }, agora), []));\n    t.verifica('dois mudos ao mesmo tempo: ambos na lista',\n      igual(vigia({ aldeias: { a: 1, u: agora - 60, f: h(9) },\n        construcao: { a: 1, u: agora - 60, f: h(30) } }, agora).sort(), ['aldeias', 'construcao']));\n  }\n  t.secao('SÓ SE AVISA O QUE PERSISTE');\n  {\n    /* Bastava ver o problema uma vez para avisar, e deixar de o ver uma vez\n     * para dar por resolvido: o Discord encheu-se de pares \"está parado\" /\n     * \"já não\", de dez em dez minutos, nas vinte contas (16/09). */\n    t.verifica('um problema só é anunciado à segunda passagem seguida',\n      /if \\(!jaAvisado && vezes >= 2\\) novos\\.push/.test(SRC));\n    t.verifica('... e conta as vezes que já foi visto',\n      /const vezes = \\(\\(antigo && antigo\\.vezes\\) \\|\\| 0\\) \\+ 1;/.test(SRC));\n    t.verifica('só se anuncia a resolução do que chegou a ser anunciado',\n      /if \\(antigo\\.avisado\\) resolvidos\\.push\\(\\{ nome, p \\}\\);/.test(SRC));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n"
};

const destino = path.join(process.cwd(), 'ferramentas');
fs.mkdirSync(destino, { recursive: true });
let n = 0;
for (const nome of Object.keys(FICHEIROS)) {
  fs.writeFileSync(path.join(destino, nome), FICHEIROS[nome], 'utf8');
  n++;
}
console.log(`Escritos ${n} ficheiro(s) em ${destino}`);
console.log('Agora: node ferramentas/testar-tudo.js maestro.user.js');
